missions.mission = assert(load("-- Mission state machine for the kit map editor. Pure Lua: no gd calls, so it loads under plain lua\n-- and the tests drive it with made-up observations. main.lua embeds this file verbatim between\n-- \"BEGIN/END GENERATED MISSION\" (the engine loads one entry file per mod and has no require);\n-- regenerate it with tools/port/map_mission_sync.py after editing.\nlocal M = {}\n-- Keep in step with gs_enemy_names in pc/platform/gw_script.c (topi is registered but not yet in the docs).\nM.KINDS = { 'goomba', 'koopa', 'redead', 'like_like', 'octorok', 'polar_bear', 'topi' }\n-- per_wave: gd.spawn_enemy allows 32 live script enemies; waves, checkpoints and the rest are authoring caps.\nM.LIMITS = { enemies = 64, per_wave = 32, waves = 8, checkpoints = 16, zone = 2000, time = 3600, lives = 99,\n             triggers = 16, text = 80, radius = 200 }\n-- Trigger actions: wave (spawn a wave now), message (HUD line), collision (open or close the parts near\n-- a point), complete / fail (end the mission).\nM.ACTIONS = { wave = true, message = true, collision = true, complete = true, fail = true }\nM.MESSAGE_FRAMES = 240 -- how long a message stays on the HUD\nM.OBJECTIVES = { reach_goal = 'Reach the goal', defeat_all = 'Defeat all enemies',\n                 defeat_then_goal = 'Defeat all enemies, then reach the goal' }\nM.FPS = 60 -- logic frames per second; time limits count on_frame calls\n-- P1 respawns through the engine's own sequence (platform and all) at stage spawn slot 4; the state\n-- machine only says where that point is ('respawn_point' actions: the start, then each checkpoint).\nM.RESPAWN_SLOT = 4\n\nlocal known = {}\nfor _, k in ipairs(M.KINDS) do known[k] = true end\n\nlocal function num(n) return type(n) == 'number' and n == n and math.abs(n) <= 100000 end\nlocal function plain(t, what) assert(type(t) == 'table' and getmetatable(t) == nil, what .. ' must be a table') end\nlocal function only(t, allowed, what)\n  for k in pairs(t) do assert(allowed[k], 'unknown ' .. what .. ' field: ' .. tostring(k)) end\nend\nlocal function list(t, what, max)\n  plain(t, what .. ' list')\n  local n = 0\n  for k in pairs(t) do\n    assert(type(k) == 'number' and k % 1 == 0 and k >= 1, what .. ' must be a plain list')\n    n = n + 1\n  end\n  assert(n == #t, what .. ' must be a plain list')\n  assert(n <= max, 'too many ' .. what .. ' (max ' .. max .. ')')\n  return t\nend\nlocal function point(t, what)\n  plain(t, what) only(t, { x = true, y = true }, what)\n  assert(num(t.x) and num(t.y), what .. ' needs finite x and y')\n  return { x = t.x, y = t.y }\nend\nlocal function zone(t, what)\n  plain(t, what) only(t, { x = true, y = true, w = true, h = true }, what)\n  assert(num(t.x) and num(t.y), what .. ' needs finite x and y')\n  assert(num(t.w) and num(t.h) and t.w > 0 and t.h > 0 and t.w <= M.LIMITS.zone and t.h <= M.LIMITS.zone,\n         what .. ' needs w and h in (0, ' .. M.LIMITS.zone .. ']')\n  return { x = t.x, y = t.y, w = t.w, h = t.h }\nend\n\n-- Strict structural check; returns a normalized copy (lists always present, wave defaulted). Whether\n-- the mission is complete enough to play is check_playable's job, so authoring can go step by step.\nfunction M.validate(m)\n  plain(m, 'mission')\n  only(m, { start = true, enemies = true, goal = true, checkpoints = true, objective = true,\n            waves = true, triggers = true }, 'mission')\n  local out = { enemies = {}, checkpoints = {}, waves = {}, triggers = {} }\n  if m.start ~= nil then out.start = point(m.start, 'start') end\n  if m.goal ~= nil then out.goal = zone(m.goal, 'goal') end\n  local per = {}\n  local es = m.enemies == nil and {} or list(m.enemies, 'enemies', M.LIMITS.enemies)\n  for i, e in ipairs(es) do\n    plain(e, 'enemy') only(e, { kind = true, x = true, y = true, wave = true }, 'enemy')\n    assert(known[e.kind], 'unknown enemy kind: ' .. tostring(e.kind))\n    assert(num(e.x) and num(e.y), 'enemy needs finite x and y')\n    local w = e.wave == nil and 1 or e.wave\n    assert(type(w) == 'number' and w % 1 == 0 and w >= 1 and w <= M.LIMITS.waves,\n           'enemy wave must be an integer 1..' .. M.LIMITS.waves)\n    per[w] = (per[w] or 0) + 1\n    assert(per[w] <= M.LIMITS.per_wave, 'too many enemies in wave ' .. w .. ' (max ' .. M.LIMITS.per_wave .. ')')\n    out.enemies[i] = { kind = e.kind, x = e.x, y = e.y, wave = w }\n  end\n  local cs = m.checkpoints == nil and {} or list(m.checkpoints, 'checkpoints', M.LIMITS.checkpoints)\n  for i, c in ipairs(cs) do out.checkpoints[i] = zone(c, 'checkpoint') end\n  -- Wave rules: a ruled wave appears on its own condition (seconds since the start, or P1 crossing x)\n  -- instead of waiting for the earlier waves to be cleared.\n  local ws = m.waves == nil and {} or list(m.waves, 'waves', M.LIMITS.waves)\n  local ruled = {}\n  for i, r in ipairs(ws) do\n    plain(r, 'wave rule') only(r, { wave = true, time = true, x = true, dir = true }, 'wave rule')\n    assert(type(r.wave) == 'number' and r.wave % 1 == 0 and r.wave >= 1 and r.wave <= M.LIMITS.waves,\n           'wave rule needs an integer wave 1..' .. M.LIMITS.waves)\n    assert(not ruled[r.wave], 'wave ' .. r.wave .. ' has two rules')\n    ruled[r.wave] = true\n    assert((r.time ~= nil) ~= (r.x ~= nil), 'wave rule needs exactly one of time or x')\n    assert(r.time == nil or (num(r.time) and r.time >= 0 and r.time <= M.LIMITS.time),\n           'wave rule time must be 0..' .. M.LIMITS.time .. ' seconds')\n    assert(r.x == nil or num(r.x), 'wave rule x must be finite')\n    assert(r.dir == nil or (r.x ~= nil and (r.dir == 1 or r.dir == -1)), 'wave rule dir is 1 or -1 and goes with x')\n    out.waves[i] = { wave = r.wave, time = r.time, x = r.x, dir = r.x ~= nil and (r.dir or 1) or nil }\n  end\n  -- Trigger zones: entering one runs its action (once unless once = false).\n  local ts = m.triggers == nil and {} or list(m.triggers, 'triggers', M.LIMITS.triggers)\n  for i, t in ipairs(ts) do\n    plain(t, 'trigger')\n    only(t, { x = true, y = true, w = true, h = true, action = true, wave = true, text = true, at = true,\n              r = true, open = true, once = true }, 'trigger')\n    local z = zone({ x = t.x, y = t.y, w = t.w, h = t.h }, 'trigger')\n    assert(M.ACTIONS[t.action], 'trigger action must be wave, message, collision, complete or fail')\n    assert(t.once == nil or type(t.once) == 'boolean', 'trigger once must be true or false')\n    local o = { x = z.x, y = z.y, w = z.w, h = z.h, action = t.action, once = t.once ~= false }\n    local function only_for(field, action)\n      assert(t[field] == nil or t.action == action,\n             'trigger field ' .. field .. ' only goes with the ' .. action .. ' action')\n    end\n    only_for('wave', 'wave') only_for('text', 'message') only_for('at', 'collision')\n    only_for('r', 'collision') only_for('open', 'collision')\n    if t.action == 'wave' then\n      assert(type(t.wave) == 'number' and t.wave % 1 == 0 and t.wave >= 1 and t.wave <= M.LIMITS.waves,\n             'trigger wave must be an integer 1..' .. M.LIMITS.waves)\n      o.wave = t.wave\n    elseif t.action == 'message' then\n      assert(type(t.text) == 'string' and #t.text >= 1 and #t.text <= M.LIMITS.text and not t.text:find('%c'),\n             'trigger text must be 1..' .. M.LIMITS.text .. ' printable characters')\n      o.text = t.text\n    elseif t.action == 'collision' then\n      o.at = point(t.at, 'trigger at')\n      assert(type(t.open) == 'boolean', 'trigger collision needs open = true or false')\n      o.open = t.open\n      assert(t.r == nil or (num(t.r) and t.r > 0 and t.r <= M.LIMITS.radius),\n             'trigger r must be in (0, ' .. M.LIMITS.radius .. ']')\n      o.r = t.r or 6.5\n    end\n    out.triggers[i] = o\n  end\n  local o = m.objective\n  if o ~= nil then\n    plain(o, 'objective') only(o, { type = true, time = true, lives = true }, 'objective')\n    assert(M.OBJECTIVES[o.type], 'objective must be reach_goal, defeat_all or defeat_then_goal')\n    assert(o.time == nil or (num(o.time) and o.time > 0 and o.time <= M.LIMITS.time),\n           'objective time must be 1..' .. M.LIMITS.time .. ' seconds')\n    assert(o.lives == nil or (type(o.lives) == 'number' and o.lives % 1 == 0 and o.lives >= 1 and o.lives <= M.LIMITS.lives),\n           'objective lives must be an integer 1..' .. M.LIMITS.lives)\n    out.objective = { type = o.type, time = o.time, lives = o.lives }\n  end\n  return out\nend\n\nfunction M.empty(m)\n  return m == nil or (not m.start and not m.goal and not m.objective and #m.enemies == 0 and #m.checkpoints == 0\n                      and #m.waves == 0 and #m.triggers == 0)\nend\n\n-- nil when the mission can run, else what is missing.\nfunction M.check_playable(m)\n  if not m.start then return 'mission has no start (map mission start)' end\n  if not m.objective then return 'mission has no objective (map mission objective <type>)' end\n  local t = m.objective.type\n  if (t == 'reach_goal' or t == 'defeat_then_goal') and not m.goal then\n    return t .. ' needs a goal zone (map mission goal <w> <h>)'\n  end\n  if (t == 'defeat_all' or t == 'defeat_then_goal') and #m.enemies == 0 then\n    return t .. ' needs at least one enemy (map mission enemy <kind>)'\n  end\n  local have = {}\n  for _, e in ipairs(m.enemies) do have[e.wave] = true end\n  for _, r in ipairs(m.waves) do\n    if not have[r.wave] then return 'wave rule for wave ' .. r.wave .. ' but that wave has no enemies' end\n  end\n  for _, t in ipairs(m.triggers) do\n    if t.action == 'wave' and not have[t.wave] then return 'trigger spawns wave ' .. t.wave .. ' but it has no enemies' end\n  end\nend\n\nlocal function inside(z, p)\n  return p ~= nil and math.abs(p.x - z.x) <= z.w / 2 and math.abs(p.y - z.y) <= z.h / 2\nend\n\nfunction M.new(m)\n  local seen, waves = {}, {}\n  for _, e in ipairs(m.enemies) do\n    if not seen[e.wave] then seen[e.wave] = true waves[#waves + 1] = e.wave end\n  end\n  table.sort(waves)\n  -- A wave is sequential (starts when everything before it is gone) unless a rule or a trigger owns it.\n  local rule, owned = {}, {}\n  for _, r in ipairs(m.waves or {}) do rule[r.wave] = r owned[r.wave] = true end\n  for _, t in ipairs(m.triggers or {}) do if t.action == 'wave' then owned[t.wave] = true end end\n  return { m = m, waves = waves, rule = rule, owned = owned, begun = {}, nbegun = 0, tracked = {}, pending = 0,\n           frames = 0, deaths = 0, falls = nil, cp = nil, started = false, defeated = 0, vanished = 0,\n           total = #m.enemies, cleared = #waves == 0, result = nil, fail = nil, fired = {}, inside_now = {} }\nend\n\n-- The glue reports each spawn action's outcome before the next step.\nfunction M.spawned(st, index, handle)\n  st.pending = st.pending - 1\n  st.tracked[handle] = { index = index, frame = st.frames }\nend\nfunction M.spawn_failed(st, index, why)\n  st.pending = st.pending - 1\n  local e = st.m.enemies[index]\n  st.fail = st.fail or { reason = 'spawn', detail = ('%s refused: %s'):format(e and e.kind or 'enemy', tostring(why)) }\nend\n\nlocal function sorted_handles(t)\n  local out = {}\n  for h in pairs(t) do out[#out + 1] = h end\n  table.sort(out)\n  return out\nend\n\n-- obs: {frames = logic frames since the mission began, player = {x,y} or nil, falls = P1's fall count,\n-- alive = {[handle] = true} for the enemies still fighting, defeated = {[handle] = true} for the ones\n-- the engine reports as stock-defeated (omitted: every enemy that is gone counts as defeated)}.\n-- A tracked enemy that is neither alive nor defeated has vanished (blast zone, item destroyed): it\n-- leaves the fight so the objective cannot stall, but it is not counted as a defeat.\n-- Returns actions (spawn / respawn_point / cleanup, for the glue to carry out) and events (for logging).\nfunction M.step(st, obs)\n  local actions, events = {}, {}\n  if st.result then return actions, events end\n  st.frames = obs.frames\n  local m, obj = st.m, st.m.objective\n\n  local function finish(status, reason, detail)\n    st.result = { status = status, reason = reason, detail = detail, frames = st.frames,\n                  deaths = st.deaths, defeated = st.defeated, vanished = st.vanished }\n    actions[#actions + 1] = { type = 'cleanup' }\n    events[#events + 1] = { type = status, reason = reason, detail = detail, frames = st.frames,\n                            deaths = st.deaths, defeated = st.defeated, vanished = st.vanished }\n  end\n  if st.fail then finish('failed', st.fail.reason, st.fail.detail) return actions, events end\n\n  -- The start is the first respawn point.\n  if not st.started then\n    st.started = true\n    if m.start then actions[#actions + 1] = { type = 'respawn_point', x = m.start.x, y = m.start.y } end\n  end\n\n  -- Defeats. A handle is not judged on the frame it spawned: the pool may not report it yet.\n  for _, h in ipairs(sorted_handles(st.tracked)) do\n    local t = st.tracked[h]\n    if obs.frames > t.frame and not obs.alive[h] then\n      st.tracked[h] = nil\n      local kind = m.enemies[t.index].kind\n      if obs.defeated == nil or obs.defeated[h] then\n        st.defeated = st.defeated + 1\n        events[#events + 1] = { type = 'defeat', handle = h, index = t.index, kind = kind }\n      else\n        st.vanished = st.vanished + 1\n        events[#events + 1] = { type = 'vanish', handle = h, index = t.index, kind = kind }\n      end\n    end\n  end\n\n  -- Triggers fire on entry. They run before the waves so a triggered wave appears the same step.\n  local function begin_wave(w)\n    if st.begun[w] then return end\n    st.begun[w] = true st.nbegun = st.nbegun + 1\n    local px = obs.player and obs.player.x or (m.start and m.start.x) or 0\n    for i, e in ipairs(m.enemies) do\n      if e.wave == w then\n        st.pending = st.pending + 1\n        actions[#actions + 1] = { type = 'spawn', index = i, kind = e.kind, x = e.x, y = e.y,\n                                  wave = w, facing = px >= e.x and 1 or -1 }\n      end\n    end\n    events[#events + 1] = { type = 'wave', n = st.nbegun, of = #st.waves, wave = w }\n  end\n  for i, t in ipairs(m.triggers) do\n    local now = inside(t, obs.player)\n    if now and not st.inside_now[i] and not (t.once and st.fired[i]) then\n      st.fired[i] = true\n      events[#events + 1] = { type = 'trigger', index = i, action = t.action }\n      if t.action == 'wave' then begin_wave(t.wave)\n      elseif t.action == 'message' then events[#events + 1] = { type = 'message', text = t.text }\n      elseif t.action == 'collision' then\n        actions[#actions + 1] = { type = 'collision', x = t.at.x, y = t.at.y, r = t.r, open = t.open }\n      elseif t.action == 'complete' then finish('complete') return actions, events\n      elseif t.action == 'fail' then finish('failed', 'trigger', 'trigger zone ' .. i) return actions, events\n      end\n    end\n    st.inside_now[i] = now\n  end\n\n  -- Waves. Ruled waves start on their own condition; the rest go in order once everything spawned is gone.\n  for _, w in ipairs(st.waves) do\n    local r = st.rule[w]\n    if r and not st.begun[w] then\n      local px = obs.player and obs.player.x\n      if (r.time and obs.frames >= r.time * M.FPS) or\n         (r.x and px and ((r.dir == 1 and px >= r.x) or (r.dir == -1 and px <= r.x))) then\n        begin_wave(w)\n      end\n    end\n  end\n  if next(st.tracked) == nil and st.pending == 0 then\n    for _, w in ipairs(st.waves) do\n      if not st.owned[w] and not st.begun[w] then begin_wave(w) break end\n    end\n  end\n  if not st.cleared and st.nbegun == #st.waves and next(st.tracked) == nil and st.pending == 0 then\n    st.cleared = true\n  end\n\n  -- Checkpoints: touching one makes it the respawn point.\n  local held = st.cp and inside(m.checkpoints[st.cp], obs.player) -- overlapping zones must not flip-flop\n  for i, z in ipairs(m.checkpoints) do\n    if not held and inside(z, obs.player) and st.cp ~= i then\n      st.cp = i\n      actions[#actions + 1] = { type = 'respawn_point', x = z.x, y = z.y }\n      events[#events + 1] = { type = 'checkpoint', index = i }\n      break\n    end\n  end\n\n  -- Deaths: the fall count rising is the KO. Lives only fail the mission when the author set them.\n  if st.falls == nil then st.falls = obs.falls end\n  local lost = obs.falls - st.falls\n  if lost > 0 then\n    st.falls = obs.falls st.deaths = st.deaths + lost\n    events[#events + 1] = { type = 'death', deaths = st.deaths,\n                            remaining = obj.lives and math.max(0, obj.lives - st.deaths) or nil }\n  end\n\n  local goal_open = obj.type == 'reach_goal' or (obj.type == 'defeat_then_goal' and st.cleared)\n  if (obj.type == 'defeat_all' and st.cleared) or (goal_open and inside(m.goal, obs.player)) then\n    finish('complete') return actions, events\n  end\n  if obj.lives and st.deaths >= obj.lives then finish('failed', 'lives') return actions, events end\n  if obj.time and obs.frames >= obj.time * M.FPS then finish('failed', 'time') return actions, events end\n  return actions, events\nend\n\nlocal function clock(frames, up)\n  local s = math.max(0, (up and math.ceil or math.floor)(frames / M.FPS))\n  return ('%d:%02d'):format(s // 60, s % 60)\nend\n\n-- One HUD line: objective, enemies left, time (remaining when limited, else elapsed), lives left.\nfunction M.hud(st)\n  local o = st.m.objective\n  local parts = { o.type == 'reach_goal' and 'Reach the goal' or o.type == 'defeat_all' and 'Defeat all'\n                  or (st.cleared and 'Reach the goal' or 'Defeat all, then the goal') }\n  if st.total > 0 then parts[#parts + 1] = 'enemies ' .. (st.total - st.defeated - st.vanished) end\n  if o.time then\n    parts[#parts + 1] = 'time ' .. clock(o.time * M.FPS - st.frames, true)\n  else\n    parts[#parts + 1] = 'time ' .. clock(st.frames)\n  end\n  if o.lives then parts[#parts + 1] = 'lives ' .. math.max(0, o.lives - st.deaths) end\n  return table.concat(parts, ' | ')\nend\n\nlocal WHY = { time = 'time ran out', lives = 'out of lives' }\nfunction M.result_text(st)\n  local r = st.result\n  if not r then return nil end\n  if r.status == 'complete' then return 'MISSION COMPLETE  ' .. clock(r.frames) end\n  return 'MISSION FAILED: ' .. (WHY[r.reason] or r.detail or r.reason)\nend\n\nreturn M\n", "@missions/mission.lua", "t"))()
missions.validator = assert(load("-- Layout normalization: same v1/v2 part, bounds and spawn rules as the editor.\nreturn function(D)\n  local V = {}\n  function V.number(n)\n    return type(n)=='number' and n==n and math.abs(n)<=100000\n  end\n  function V.plain(t, what)\n    assert(type(t)=='table' and getmetatable(t)==nil, what..' must be a plain table')\n  end\n  function V.list(t, what, max)\n    V.plain(t,what)\n    local n=0\n    for k in pairs(t) do\n      assert(type(k)=='number' and k%1==0 and k>=1,what..' must be a dense list')\n      n=n+1\n    end\n    assert(n==#t and n<=max,what..' sparse or oversized')\n  end\n  function V.name(s)\n    assert(type(s)=='string' and #s<=64 and s:match('^[%w_-]+$'),'use a plain folder or part name')\n    return s\n  end\n  function V.point(p,what)\n    V.plain(p,what)\n    assert(V.number(p.x) and V.number(p.y),what..' needs finite x and y')\n    return {x=p.x,y=p.y}\n  end\n  function V.rect(b,what)\n    V.plain(b,what)\n    for _,k in ipairs({'left','right','top','bottom'}) do assert(V.number(b[k]),'invalid '..what..' '..k) end\n    assert(b.left<b.right and b.bottom<b.top,what..' requires left < right and bottom < top')\n    return {left=b.left,right=b.right,top=b.top,bottom=b.bottom}\n  end\n  function V.camera(data)\n    V.plain(data,'camera settings')\n    local q={};local allowed={mode=true,window=true,ends=true,x=true,margin=true,frames=true,\n      min_dist=true,max_depth=true,fov=true,tilt=true,fixed_zoom=true,track_smooth=true,track_ratio=true,\n      yaw_gain=true,pitch_gain=true,pan=true,aspect=true,leash=true,vertical_leash=true,look_ahead=true,\n      velocity_lead=true,max_lead=true,vertical_lead=true,vertical_max=true,door_margin=true,safe_margin=true,commit_distance=true,vertical_commit_distance=true,\n      ease_frames=true,curve=true,doorway_margin=true,doors=true}\n    for k,v in pairs(data) do assert(allowed[k],'unknown camera setting '..tostring(k));q[k]=v end\n    assert(q.mode==nil or q.mode=='follow' or q.mode=='chunk' or q.mode=='shaft','invalid camera mode')\n    if q.window~=nil then\n      V.plain(q.window,'camera window')\n      assert(V.number(q.window.w) and q.window.w>0 and q.window.w<=49000 and\n        V.number(q.window.h) and q.window.h>0 and q.window.h<=49000,'invalid camera window')\n      q.window={w=q.window.w,h=q.window.h}\n    end\n    if q.ends~=nil then q.ends=V.rect(q.ends,'camera ends') end\n    assert(q.curve==nil or q.curve=='linear' or q.curve=='smoothstep','invalid camera curve')\n    if q.doors then\n      V.plain(q.doors,'camera doors');local doors={}\n      for name,v in pairs(q.doors)do V.name(name);doors[name]=V.door_camera(v)end\n      q.doors=doors\n    end\n    local ranges={min_dist={1,49000},max_depth={1,49000},fov={1,89},tilt={1,89},\n      fixed_zoom={0,10},track_smooth={0,10},track_ratio={0,10},yaw_gain={0,10},pitch_gain={0,10},\n      pan={-180,180},x={-49000,49000},margin={0,100},frames={30,60},aspect={0.5,4},leash={0,100},vertical_leash={0,100},look_ahead={0,100},\n      velocity_lead={0,30},max_lead={0,200},vertical_lead={0,30},vertical_max={0,200},\n      door_margin={0,100},safe_margin={0,100},commit_distance={1,32},vertical_commit_distance={1,40},ease_frames={1,120},doorway_margin={0,40}}\n    for k,b in pairs(ranges) do if q[k]~=nil then\n      assert(V.number(q[k]) and q[k]>=b[1] and q[k]<=b[2],'invalid camera '..k)\n    end end\n    assert(not q.frames or q.frames%1==0,'camera frames must be integer')\n    assert(not q.ease_frames or q.ease_frames%1==0,'camera ease_frames must be integer')\n    assert(not (q.min_dist and q.max_depth) or q.min_dist<=q.max_depth,'camera min_dist exceeds max_depth')\n    assert(not (q.fov and q.tilt) or q.fov==q.tilt,'camera fov and tilt differ')\n    return q\n  end\n  function V.door_camera(data)\n    V.plain(data,'door camera')\n    local allowed={commit_distance=true,vertical_commit_distance=true,ease_frames=true,curve=true,doorway_margin=true}\n    for k in pairs(data)do assert(allowed[k],'invalid door camera field '..tostring(k))end\n    return V.camera(data)\n  end\n  function V.layout(data, catalogue, work)\n    V.plain(data,'layout')\n    assert(data.version==1 or data.version==2,'layout version must be 1 or 2')\n    assert(data.units==6.5,'kit scale differs; units must be 6.5')\n    local out={parts={},spawn={},lines={},markers={},fighters={}}\n    if data.autostart~=nil then assert(type(data.autostart)=='boolean','autostart must be boolean');out.autostart=data.autostart end\n    if data.warm_items~=nil then\n      V.list(data.warm_items,'warm items',32);out.warm_items={}\n      for i,k in ipairs(data.warm_items)do assert(type(k)=='string'and #k<=127 or type(k)=='number'and k>=0 and k<2147483648 and k%1==0,'invalid warm item');out.warm_items[i]=k end\n    end\n    if data.starting_percent~=nil then\n      assert(V.number(data.starting_percent) and data.starting_percent%1==0 and\n        data.starting_percent>=0 and data.starting_percent<=999,'invalid starting percent')\n      out.starting_percent=data.starting_percent\n    end\n    if data.fighters~=nil then\n      V.plain(data.fighters,'fighters')\n      for port,mode in pairs(data.fighters) do\n        assert(type(port)=='number' and port%1==0 and port>=2 and port<=6,'fighter policy ports are 2-6')\n        assert(mode=='stand' or mode=='fight','fighter policy must be stand or fight');out.fighters[port]=mode\n      end\n    end\n    if data.mission~=nil then\n      assert(data.version==2,'mission requires layout version 2')\n      out.mission=D.mission.validate(data.mission)\n    end\n    if data.version==2 then\n      if data.camera~=nil then\n        V.plain(data.camera,'camera')\n        local cfg={}\n        for k,v in pairs(data.camera) do\n          if k~='left' and k~='right' and k~='top' and k~='bottom' then cfg[k]=v end\n        end\n        if data.camera.left~=nil or data.camera.right~=nil or data.camera.top~=nil or data.camera.bottom~=nil then\n          out.camera=V.rect(data.camera,'camera')\n        end  -- exporter writes rectangle and settings in one table\n        if next(cfg)~=nil then out.camera_settings=V.camera(cfg) end\n      end\n      if data.blast~=nil then out.blast=V.rect(data.blast,'blast') end\n      if data.spawn~=nil then\n        V.plain(data.spawn,'spawn')\n        for slot,p in pairs(data.spawn) do\n          assert(type(slot)=='number' and slot%1==0 and ((slot>=0 and slot<=7) or (slot>=127 and slot<=146)),\n                 'spawn slots are 0-7 or 127-146')\n          out.spawn[slot]=V.point(p,'spawn')\n        end\n      end\n    end\n    out.zones={};V.list(data.zones or {},'zones',4096)\n    local zone_names={}\n    for _,z in ipairs(data.zones or {})do\n      V.plain(z,'zone');V.name(z.name);assert(not zone_names[z.name],'duplicate zone '..z.name);zone_names[z.name]=true\n      assert(z.kind=='room' or z.kind=='transition' or z.kind=='region','invalid zone kind '..z.name)\n      local q={name=z.name,kind=z.kind,rect=V.rect(z.rect,'zone '..z.name)}\n      if z.kind=='room' then q.room=V.name(z.room)\n      elseif z.kind=='region'then q.region=V.name(z.region)\n      else\n        V.list(z.rooms,'zone rooms',16);assert(#z.rooms>=2,'transition needs at least two rooms');q.rooms={}\n        local ids={};for _,id in ipairs(z.rooms)do V.name(id);assert(not ids[id],'duplicate zone room');ids[id]=true;q.rooms[#q.rooms+1]=id end\n        if z.camera then q.camera=V.door_camera(z.camera)end\n      end\n      out.zones[#out.zones+1]=q;if work then work('normalize zone')end\n    end\n    V.list(data.parts,'parts',128)\n    for i,p in ipairs(data.parts) do\n      V.plain(p,'part'); V.name(p.part)\n      assert(catalogue[p.part],'unknown folder part: '..p.part)\n      local label=p.name or p.label or p.part\n      assert(type(label)=='string' and #label>=1 and #label<=80 and not label:find('%c'),'invalid part label')\n      local q={part=p.part,path=catalogue[p.part],label=label}\n      for _,k in ipairs({'x','y','z','rot'}) do assert(V.number(p[k]),'invalid '..k);q[k]=p[k] end\n      assert(math.abs(p.rot)<=360,'rotation must be -360..360')\n      assert(type(p.collision)=='boolean','collision must be boolean')\n      assert(type(p.floor_flags)=='number' and p.floor_flags%1==0 and p.floor_flags>=0 and p.floor_flags<=3,\n             'floor_flags must be 0..3')\n      q.collision=p.collision;q.floor_flags=p.floor_flags\n      for _,k in ipairs({'scale','scale_x','scale_y','scale_z'}) do\n        local n=p[k]==nil and 1 or p[k]\n        assert(V.number(n) and math.abs(n)>=0.001 and math.abs(n)<=100,'invalid '..k);q[k]=n\n      end\n      out.parts[i]=q\n    end\n    V.list(data.lines or {},'lines',768)\n    for i,l in ipairs(data.lines or {}) do\n      V.plain(l,'line')\n      local q={}\n      for _,k in ipairs({'x1','y1','x2','y2'}) do assert(V.number(l[k]),'invalid line '..k);q[k]=l[k] end\n      assert(l.kind=='floor' or l.kind=='ceiling' or l.kind=='left_wall' or l.kind=='right_wall','invalid line kind')\n      assert((l.kind=='floor' and l.x1<l.x2) or (l.kind=='ceiling' and l.x1>l.x2) or\n             (l.kind=='left_wall' and l.y1<l.y2) or (l.kind=='right_wall' and l.y1>l.y2),'wrong line direction')\n      q.kind=l.kind;q.opts={}\n      for _,k in ipairs({'passthrough','ledges','draw'}) do\n        assert(l[k]==nil or type(l[k])=='boolean','line '..k..' must be boolean');q.opts[k]=l[k]\n      end\n      out.lines[i]=q\n    end\n    V.list(data.markers or {},'markers',512)\n    local names={}\n    for i,p in ipairs(data.markers or {}) do\n      local q=V.point(p,'marker');q.name=V.name(p.name)\n      assert(not names[q.name],'duplicate marker name');names[q.name]=true\n      V.list(p.cleared_waves or {},'cleared_waves',8)\n      q.cleared_waves={}\n      for j,w in ipairs(p.cleared_waves or {}) do\n        assert(type(w)=='number' and w%1==0 and w>=1 and w<=8,'invalid cleared wave')\n        q.cleared_waves[j]=w\n      end\n      assert(p.checkpoint==nil or (type(p.checkpoint)=='number' and p.checkpoint%1==0 and p.checkpoint>=1),'invalid marker checkpoint')\n      assert(p.frames==nil or (V.number(p.frames) and p.frames%1==0 and p.frames>=0),'invalid marker frames')\n      q.checkpoint=p.checkpoint;q.frames=p.frames or 0;q.authored=true\n      out.markers[i]=q;if work then work('normalize marker')end\n    end\n    return out\n  end\n  return V\nend\n", "@missions/validator.lua", "t"))()(missions)
missions.maze_set = assert(load("-- Authored data recipes, not generated art. Coordinates are local game units.\nreturn function()\n  local exits={\n    {side='left',slot=1,traversal='walk'}, {side='right',slot=1,traversal='walk'},\n    {side='up',slot=1,traversal='climb'}, {side='down',slot=1,traversal='drop'}}\n  local platforms={{x1=29,x2=61,y=20},{x1=69,x2=101,y=40},\n    {x1=49,x2=81,y=60},{x1=49,x2=81,y=80},{x1=49,x2=81,y=100}}\n  return {version=1,size={w=130,h=104},door={width=24,height=32},\n    exits=exits,platforms=platforms,spawn={x=20,y=8},\n    -- Potential exits; any unused potential slot is sealed at assembly.\n    templates={\n      {id='gallery',sides='LRUD',tags={'theme:gallery'}},\n      {id='vault',sides='LRUD',tags={'theme:vault'}},\n      {id='switchback',sides='LRUD',tags={'theme:switchback'}},\n      {id='well',sides='LRUD',tags={'theme:well'}},\n      {id='corridor',sides='LR',tags={'theme:kit'}},\n      {id='corner_up',sides='RU',tags={'theme:kit'}},\n      {id='corner_down',sides='RD',tags={'theme:kit'}},\n      {id='t_junction',sides='LRU',tags={'theme:kit'}},\n      {id='platform_room',sides='LRUD',tags={'theme:kit'}},\n      {id='shaft',sides='UD',tags={'theme:kit'}},\n      {id='drop',sides='RD',tags={'drop','theme:kit'}},\n      {id='reward_end',sides='LRUD',tags={'secret','reward'}},\n      {id='start',sides='LRUD',tags={'start'}},\n      {id='goal',sides='LRUD',tags={'goal'}},\n      {id='boss_room',sides='LRUD',tags={'boss'}}},\n    enemy_kinds={'goomba','koopa'},enemy_slots={{x=32,y=8},{x=88,y=8},{x=104,y=8}},\n    -- Render-only slabs: collision is explicit, so kit floor sidecar pass-through\n    -- flags cannot accidentally open a sealed roof/floor.\n    part='bf_floor_4m',\n    -- One hand-authored shell shared by the starter recipes. The generator\n    -- translates these lines; only doorway seals are added procedurally.\n    shell={\n      {'floor',0,0,53,0},{'ceiling',53,0,0,0},\n      {'floor',77,0,130,0},{'ceiling',130,0,77,0},\n      {'floor',0,104,53,104},{'ceiling',53,104,0,104},\n      {'floor',77,104,130,104},{'ceiling',130,104,77,104},\n      {'left_wall',0,32,0,104},{'right_wall',0,104,0,32},\n      {'left_wall',130,32,130,104},{'right_wall',130,104,130,32}},\n    slabs={{x1=0,x2=53,y=0},{x1=77,x2=130,y=0}}}\nend\n", "@missions/maze_set.lua", "t"))()(missions)
missions.maze_clearance = assert(load("-- Conservative collision certificates, including neighbouring chunks/seams.\nreturn function()\n  local C={HEADROOM=50,CRAWL=20,WALL_GAP=6,STEP=20,LANDING=32}\n  local function horizontal(l)return l.y1==l.y2 end\n  local function span(l)return math.min(l.x1,l.x2),math.max(l.x1,l.x2)end\n  function C.check(m,work)\n    local errors,grid={},{}\n    local function name(c,l,i)return c.id..'/'..(l.label or ('line'..i))end\n    for _,c in ipairs(m.cells or {})do grid[c.x..','..c.y]=c end\n    for _,c in ipairs(m.cells or {})do\n      for i,p in ipairs(c.level and c.level.parts or {})do if p.collision then errors[#errors+1]=c.id..'/'..(p.name or 'part'..i)..': opaque model collision needs explicit render-only parts and certified lines'end end\n      for i,l in ipairs(c.level and c.level.lines or {})do\n        if (l.kind=='floor'or l.kind=='ceiling')and not horizontal(l)then errors[#errors+1]=name(c,l,i)..': sloped surface lacks a clearance certificate'end\n        if (l.kind=='left_wall'or l.kind=='right_wall')and l.x1~=l.x2 then errors[#errors+1]=name(c,l,i)..': diagonal wall lacks a clearance certificate'end\n      end\n      for _,e in ipairs(c.exits or{})do if e.side=='up'and e.to and e.traversal=='climb'then\n        local previous=0\n        for i,p in ipairs(c.platforms or{})do\n          if p.y-previous>C.STEP then errors[#errors+1]=c.id..'/climb'..i..': step '..(p.y-previous)..' > '..C.STEP end\n          previous=p.y\n        end\n      end end\n      for i,l in ipairs(c.level and c.level.lines or {})do if l.kind=='floor'and horizontal(l)then\n        local crawl=l.label and l.label:match('^crawl:')\n        for _,tag in ipairs(c.tags or{})do if tag=='crawl'then crawl=true end end\n        local a,z=span(l);local required=crawl and C.CRAWL or C.HEADROOM\n        for dx=-1,1 do for dy=-1,1 do local other=grid[(c.x+dx)..','..(c.y+dy)]\n          for j,o in ipairs(other and other.level and other.level.lines or {})do\n            if o.kind=='ceiling'and horizontal(o)and o.y1>l.y1 and o.y1-l.y1<required then\n              local oa,oz=span(o)\n              if oa<z+5.55 and oz>a-5.55 then errors[#errors+1]=name(c,l,i)..': headroom '..(o.y1-l.y1)..' < '..required..' under '..name(other,o,j)end\n            end\n            if l.y1>c.y*104 and l.y1<c.y*104+104 and (o.kind=='left_wall'or o.kind=='right_wall')and o.x1==o.x2 and\n              math.max(o.y1,o.y2)>l.y1 and math.min(o.y1,o.y2)<l.y1+required then\n              local gap=math.max(a-o.x1,o.x1-z,0)\n              if gap<C.WALL_GAP then errors[#errors+1]=name(c,l,i)..': wall gap '..gap..' < '..C.WALL_GAP..' at '..name(other,o,j)end\n            end\n          end\n        end end\n      end end\n      -- A drop must encounter a broad supporting span, or a contiguous sealed floor.\n      for _,e in ipairs(c.exits or {})do if e.side=='down'and e.to then\n        local below=grid[c.x..','..(c.y-1)];local found=false\n        for _,l in ipairs(below and below.level.lines or {})do if l.kind=='floor'and horizontal(l)then\n          local a,z=span(l);if a<=c.x*130+65 and z>=c.x*130+65 and z-a>=C.LANDING then found=true end\n        end end\n        if not found and below then\n          local spans={};for _,l in ipairs(below.level.lines)do if l.kind=='floor'and l.y1==below.y*104 and horizontal(l)then local a,z=span(l);spans[#spans+1]={a,z}end end\n          table.sort(spans,function(a,z)return a[1]<z[1]end);local lo,hi\n          for _,p in ipairs(spans)do if not hi or p[1]>hi then lo,hi=p[1],p[2]else hi=math.max(hi,p[2])end\n            if lo<=c.x*130+65 and hi>=c.x*130+65 and hi-lo>=C.LANDING then found=true end\n          end\n        end\n        if not found then errors[#errors+1]=c.id..'/down: no '..C.LANDING..'-unit landing in '..tostring(e.to)end\n      end end\n      if work then work('clearance')end\n    end\n    return {ok=#errors==0,errors=errors}\n  end\n  return C\nend\n", "@missions/maze_clearance.lua", "t"))()(missions)
missions.maze_metrics = assert(load("-- Shape measurements independent of geometry/generation.\nreturn function()\n  local T={}\n  function T.measure(m)\n    local ids,degree,edges={},{},0\n    for _,c in ipairs(m.cells)do ids[c.id]=c;degree[c.id]=0\n      for _,e in ipairs(c.exits)do if e.to then degree[c.id]=degree[c.id]+1;edges=edges+1 end end\n    end\n    local q={branches=0,longest_dead_end=0,turns=0,cycles=edges/2-#m.cells+1,directions={left=0,right=0,up=0,down=0},adjacent_repeats=0}\n    for _,c in ipairs(m.cells)do\n      if degree[c.id]>=3 then q.branches=q.branches+1 end\n      for _,e in ipairs(c.exits)do if e.to and ids[e.to]and c.id<e.to and c.template==ids[e.to].template then q.adjacent_repeats=q.adjacent_repeats+1 end end\n      if degree[c.id]==1 and c.id~=m.start and c.id~=m.goal then\n        local at,previous,length=c,nil,0;local seen={}\n        while at and not seen[at.id]do\n          seen[at.id]=true\n          if degree[at.id]>2 then break end\n          local nextid;for _,e in ipairs(at.exits)do if e.to and e.to~=previous then nextid=e.to;break end end\n          if not nextid then break end\n          length=length+1;previous=at.id;at=ids[nextid]\n        end\n        q.longest_dead_end=math.max(q.longest_dead_end,length)\n      end\n    end\n    local previous\n    for i=2,#(m.main_path or {})do local a,b=ids[m.main_path[i-1]],ids[m.main_path[i]]\n      local direction=b.x>a.x and 'right'or b.x<a.x and 'left'or b.y>a.y and 'up'or 'down'\n      q.directions[direction]=q.directions[direction]+1\n      if previous and previous~=direction then q.turns=q.turns+1 end;previous=direction\n    end\n    return q\n  end\n  return T\nend\n", "@missions/maze_metrics.lua", "t"))()(missions)
missions.maze_topology = assert(load("-- Seeded graph layout: a loop core, self-avoiding route and sustained wrong turns.\nreturn function(D)\n  local T={};local dirs={{'left',-1,0,'right','L'},{'right',1,0,'left','R'},{'up',0,1,'down','U'},{'down',0,-1,'up','D'}}\n  function T.generate(seed,options,choose,copy)\n    local size,length=options.size,options.length\n    local m={version=2,seed=seed,size=size,cells={},main_path={},start='c1'};local occupied={}\n    local canclimb=not options.templates\n    for _,t in ipairs(options.templates or {})do\n      if not t.exits and not t.level and t.sides and t.sides:find('U',1,true)then canclimb=true end\n      for _,e in ipairs(t.exits or(t.level and t.level.exits)or{})do if e.side=='up'and e.traversal=='climb'then canclimb=true end end end\n    local function key(x,y)return x..','..y end\n    local function add(x,y,parent,d,branch)\n      local c={id='c'..(#m.cells+1),x=x,y=y,exits=copy(D.maze_set.exits),platforms=copy(D.maze_set.platforms),links={},forward={},branch=branch}\n      m.cells[#m.cells+1]=c;occupied[key(x,y)]=c\n      if parent then c.links[d[4]]=parent.id;parent.links[d[1]]=c.id;parent.forward[d[1]]=true end\n      return c\n    end\n    local c=add(0,0);m.main_path[1]=c.id;local depth=2\n    if options.loops~=false and canclimb then\n      local a=dirs[choose(4)];local perpendicular={}\n      for _,d in ipairs(dirs)do if d[2]*a[2]+d[3]*a[3]==0 then perpendicular[#perpendicular+1]=d end end\n      local b=perpendicular[choose(2)];local opposite\n      for _,d in ipairs(dirs)do if d[1]==a[4]then opposite=d end end\n      for _,d in ipairs({a,b,opposite})do c=add(c.x+d[2],c.y+d[3],c,d);m.main_path[depth]=c.id;depth=depth+1 end\n      c.links[b[4]]=m.start;m.cells[1].links[b[1]]=c.id\n    end\n    local search=0\n    local function choices(p)\n      local out={};for _,d in ipairs(dirs)do if (canclimb or d[1]~='up')and not occupied[key(p.x+d[2],p.y+d[3])]then out[#out+1]=d end end;return out\n    end\n    local function grow(parent,n)\n      if n>length then c=parent;return true end\n      search=search+1;if search>512 then return false end\n      local out=choices(parent)\n      while #out>0 do local d=table.remove(out,choose(#out));local child=add(parent.x+d[2],parent.y+d[3],parent,d);m.main_path[n]=child.id\n        if grow(child,n+1)then return true end\n        occupied[key(child.x,child.y)]=nil;table.remove(m.cells);m.main_path[n]=nil;parent.links[d[1]]=nil;parent.forward[d[1]]=nil\n      end;return false\n    end\n    if not grow(c,depth)then\n      local out=choices(c);local d=out[choose(#out)]\n      for n=depth,length do c=add(c.x+d[2],c.y+d[3],c,d);m.main_path[n]=c.id end\n    end\n    m.goal=c.id\n    local last,age,limit=nil,0,0\n    while #m.cells<size do\n      local out=last and age<limit and choices(last)or{}\n      local parent=last\n      if #out==0 then\n        local roots={};for _,p in ipairs(m.cells)do if p.id~=m.goal then for _,d in ipairs(choices(p))do roots[#roots+1]={p=p,d=d}end end end\n        local q=roots[choose(#roots)];parent=q.p;out={q.d};age=0;limit=math.min(size-#m.cells,3+choose(4))\n      end\n      local d=out[choose(#out)];last=add(parent.x+d[2],parent.y+d[3],parent,d,true);age=age+1\n    end\n    if options.loops~=false then for _,p in ipairs(m.cells)do if not p.branch then for _,d in ipairs(dirs)do\n      local other=occupied[key(p.x+d[2],p.y+d[3])]\n      if other and not other.branch and not p.links[d[1]]and choose(4)~=1 then p.links[d[1]]=other.id;other.links[d[4]]=p.id end\n    end end end end\n    local dist={[m.start]=0};local queue={m.cells[1]};local i=1\n    while queue[i]do local p=queue[i];i=i+1;for _,d in ipairs(dirs)do local id=p.links[d[1]]\n      if id and dist[id]==nil then dist[id]=dist[p.id]+1;queue[#queue+1]=m.cells[tonumber(id:sub(2))]end\n    end end\n    return m,dist\n  end\n  return T\nend\n", "@missions/maze_topology.lua", "t"))()(missions)
missions.maze_check = assert(load("-- Independent proof over emitted exits and actual collision lines. No generator calls.\nreturn function(D)\n  local C={}\n  local vectors={left={-1,0,'right'},right={1,0,'left'},up={0,1,'down'},down={0,-1,'up'}}\n  local function hasline(c,kind,x1,y1,x2,y2,label,pass)\n    for _,l in ipairs(c.level and c.level.lines or {}) do\n      if l.kind==kind and l.x1==x1 and l.y1==y1 and l.x2==x2 and l.y2==y2 and\n        (not label or l.label==label) and (pass==nil or l.passthrough==pass) then return true end\n    end\n    return false\n  end\n  local function climb(c)\n    local previous={x1=0,x2=53,y=0}\n    if #(c.platforms or {})==0 then return false end\n    for _,p in ipairs(c.platforms) do\n      if not (type(p.y)=='number' and p.y>previous.y and p.y-previous.y<=20 and\n        p.x1<p.x2 and p.x2-p.x1>=12 and p.x1>=0 and p.x2<=130) then return false end\n      if math.max(p.x1-previous.x2,previous.x1-p.x2,0)>12 then return false end\n      if not hasline(c,'floor',c.x*130+p.x1,c.y*104+p.y,c.x*130+p.x2,c.y*104+p.y) then return false end\n      previous=p\n    end\n    return 104-previous.y>=0 and 104-previous.y<=20 and previous.x1<=77 and previous.x2>=53\n  end\n  function C.check(m,work)\n    local errors,ids,grid,graph,costs,actions={},{},{},{},{},{}\n    local function error(s) errors[#errors+1]=s end\n    for _,c in ipairs(m.cells or {}) do\n      if ids[c.id] then error('duplicate chunk '..c.id) end;ids[c.id]=c;graph[c.id]={};costs[c.id]={};actions[c.id]={}\n      if type(c.x)~='number' or type(c.y)~='number' or c.x%1~=0 or c.y%1~=0 then error('invalid grid') end\n      local key=tostring(c.x)..','..tostring(c.y)\n      if grid[key] then error('overlap '..c.id) end;grid[key]=c.id\n    end\n    if not ids[m.start] then error('missing start') end\n    if not ids[m.goal] then error('missing goal') end\n    for _,c in ipairs(m.cells or {}) do\n      local slots={}\n      for _,e in ipairs(c.exits or {}) do\n        local v=vectors[e.side];local slot=e.side..':'..tostring(e.slot)\n        if not v or e.slot~=1 or slots[slot] then error('invalid exit slot '..slot)\n        else\n          slots[slot]=true\n          if e.sealed then\n            if e.to then error('sealed joined exit '..slot) end\n            local x,y=c.x*130,c.y*104;local label='seal:'..slot\n            local ok\n            if e.side=='left' or e.side=='right' then\n              if e.side=='right' then x=x+130 end\n              ok=hasline(c,'left_wall',x,y,x,y+32,label) and hasline(c,'right_wall',x,y+32,x,y,label)\n            else\n              if e.side=='up' then y=y+104 end\n              ok=hasline(c,'floor',x+53,y,x+77,y,label) and hasline(c,'ceiling',x+77,y,x+53,y,label)\n            end\n            if not ok then error('missing seal collision '..c.id..':'..slot) end\n          elseif not e.to then error('unsealed exit '..c.id..':'..slot)\n          else\n            local other=ids[e.to];local mate\n            if other then for _,f in ipairs(other.exits or {}) do\n              if f.side==v[3] and f.slot==e.slot then mate=f end\n            end end\n            if not other or other.x~=c.x+v[1] or other.y~=c.y+v[2] or\n              not mate or mate.to~=c.id or mate.sealed then error('mismatched exit slot '..c.id..':'..slot)\n            else\n              local pass=false\n              if e.side=='left' or e.side=='right' then\n                pass=e.traversal=='walk' and mate.traversal=='walk'\n              elseif e.side=='down' then pass=e.traversal=='drop'\n              elseif e.traversal=='climb' then\n                pass=climb(c);if not pass then error('invalid climb platforms '..c.id) end\n              elseif e.traversal~='drop' then error('invalid climb traversal '..c.id) end\n              if pass then graph[c.id][#graph[c.id]+1]=e.to\n                local hole=c.exits[4]and c.exits[4].to\n                local hop=(e.side=='left'or e.side=='right')and hole\n                actions[c.id][e.to]=hop and 'hop'or e.traversal\n                costs[c.id][e.to]=e.traversal=='climb'and #(c.platforms or {})+1 or hop and 2 or 1\n              end\n            end\n          end\n        end\n      end\n      for side in pairs(vectors) do if not slots[side..':1'] then error('missing exit slot '..c.id..':'..side) end end\n      if work then work('graph proof')end\n    end\n    local distance={};local queue={}\n    if ids[m.start] then queue[1]=m.start;distance[m.start]=0 end\n    local index=1\n    while queue[index] do local id=queue[index];index=index+1\n      for _,to in ipairs(graph[id]) do if distance[to]==nil then\n        distance[to]=distance[id]+1;queue[#queue+1]=to end end\n    end\n    if distance[m.goal]==nil then error('goal unreachable') end\n    local unreachable={}\n    for _,c in ipairs(m.cells or {}) do if distance[c.id]==nil then unreachable[#unreachable+1]=c.id;error('unreachable chunk '..c.id) end end\n    if D and D.maze_clearance then for _,s in ipairs(D.maze_clearance.check(m,work).errors)do error(s)end end\n    return {ok=#errors==0,errors=errors,distance=distance,unreachable=unreachable,costs=costs,actions=actions}\n  end\n  function C.folder(g,name,work)\n    assert(type(name)=='string' and name:match('^[%w_-]+$'),'unsafe mission name')\n    local base='missions/'..name..'/'\n    local function data(path)\n      local text=assert(g.mod_read(path),'missing '..path)\n      return assert(load(text,'@'..path,'t',{}))()\n    end\n    local root=data(base..'level.lua');local m=assert(root.maze,'folder lacks maze metadata')\n    local ids={};for _,c in ipairs(m.cells) do ids[c.id]=c end\n    local errors,seen={},{}\n    for _,entry in ipairs(root.chunks) do\n      if seen[entry.id] then errors[#errors+1]='duplicate chunk folder reference' end\n      seen[entry.id]=true\n      local c=assert(ids[entry.id],'chunk absent from maze metadata')\n      local rect=entry.rect\n      if rect.right-rect.left~=130 or rect.top-rect.bottom~=104 then errors[#errors+1]='invalid chunk size' end\n      c.x=rect.left/130;c.y=rect.bottom/104\n      c.level=data(base..'chunks/'..entry.id..'/level.lua');c.exits=c.level.exits;if work then work('check child')end\n    end\n    for id in pairs(ids) do if not seen[id] then errors[#errors+1]='missing chunk folder reference '..id end end\n    if #root.chunks~=#m.cells then errors[#errors+1]='missing chunk folder reference' end\n    local mission=data(base..'mission.lua')\n    for _,which in ipairs({'start','goal'}) do\n      local c=ids[m[which]];local p=mission[which]\n      if not c or not p or p.x<c.x*130 or p.x>=c.x*130+130 or p.y<c.y*104 or p.y>=c.y*104+104 then\n        errors[#errors+1]='mission '..which..' outside declared graph chunk'\n      end\n    end\n    local result=m.world and D.maze_world_check.check(m,work)or C.check(m,work)\n    for _,e in ipairs(errors) do result.errors[#result.errors+1]=e end\n    result.ok=#result.errors==0;return result\n  end\n  return C\nend\n", "@missions/maze_check.lua", "t"))()(missions)
missions.maze_world_check = assert(load("-- Whole-world reachability and every regional connector pair, using directed edges.\nreturn function(D)\n  local W={}\n  function W.check(m,work)\n    local proof=D.maze_check.check(m,work);local world=m.world\n    if not world then proof.errors[#proof.errors+1]='missing world metadata';proof.ok=false;return proof end\n    local ids,ports,regions={},{},{}\n    for _,c in ipairs(m.cells)do ids[c.id]=c end\n    for _,r in ipairs(world.regions)do regions[r.id]=r;ports[r.id]={}end\n    local function reach(start,region)\n      local seen={[start]=true};local q={start};local i=1\n      while q[i]do local c=ids[q[i]];i=i+1\n        for _,e in ipairs(c and c.exits or {})do\n          local pass=e.side=='left'or e.side=='right'or e.side=='down'or e.traversal=='climb'\n          if pass and e.to and ids[e.to]and(not region or ids[e.to].region==region)and not seen[e.to]then seen[e.to]=true;q[#q+1]=e.to end\n        end\n      end;return seen\n    end\n    local reverse={};for _,c in ipairs(m.cells)do reverse[c.id]={}end\n    for _,c in ipairs(m.cells)do for _,e in ipairs(c.exits)do\n      local pass=e.side=='left'or e.side=='right'or e.side=='down'or e.traversal=='climb'\n      if pass and e.to and reverse[e.to]then reverse[e.to][#reverse[e.to]+1]=c.id end\n    end end\n    local escape={[m.goal]=true};local queue={m.goal};local index=1\n    while queue[index]do for _,id in ipairs(reverse[queue[index]]or{})do if not escape[id]then escape[id]=true;queue[#queue+1]=id end end;index=index+1 end\n    for _,c in ipairs(m.cells)do if not escape[c.id]then proof.errors[#proof.errors+1]='soft lock: '..c.id..' cannot reach goal'end end\n    for _,link in ipairs(world.links)do\n      if not regions[link.a]or not regions[link.b]or not ids[link.from]or not ids[link.to]then proof.errors[#proof.errors+1]='invalid world connector '..tostring(link.name)\n      else ports[link.a][#ports[link.a]+1]=link.from;ports[link.b][#ports[link.b]+1]=link.to\n        local chain={link.from};for _,id in ipairs(link.chunks or{})do chain[#chain+1]=id end;chain[#chain+1]=link.to\n        if ids[link.from].region~=link.a or ids[link.to].region~=link.b then proof.errors[#proof.errors+1]='connector region mismatch '..link.name end\n        local function pass(from,to)\n          for _,e in ipairs(ids[from]and ids[from].exits or{})do\n            if e.to==to and not e.sealed and(e.side=='left'or e.side=='right'or e.side=='down'or e.traversal=='climb')then return true end\n          end\n        end\n        for i=2,#chain do\n          if not pass(chain[i-1],chain[i])then proof.errors[#proof.errors+1]='broken forward connector '..link.name..' '..chain[i-1]..' -> '..chain[i]end\n          if not link.oneway and not pass(chain[i],chain[i-1])then proof.errors[#proof.errors+1]='broken return connector '..link.name..' '..chain[i]..' -> '..chain[i-1]end\n        end\n        local seen=reach(link.from);if not seen[link.to]then proof.errors[#proof.errors+1]='broken world connector '..link.name end\n      end\n    end\n    proof.region_pairs=0\n    for _,r in ipairs(world.regions)do\n      local list=ports[r.id];list[#list+1]=r.start;list[#list+1]=r.goal\n      for _,a in ipairs(list)do local seen=reach(a,r.id)\n        for _,z in ipairs(list)do if not seen[z]then proof.errors[#proof.errors+1]=r.id..': connector pair '..a..' -> '..z..' unreachable'else proof.region_pairs=proof.region_pairs+1 end end\n        if work then work('connector proof')end\n      end\n    end\n    proof.ok=#proof.errors==0;return proof\n  end\n  return W\nend\n", "@missions/maze_world_check.lua", "t"))()(missions)
missions.maze_route = assert(load("-- Deterministic bounded A* through unused grid cells.\nreturn function()\n  local R={}\n  function R.find(a,z,blocked,bounds,work)\n    local function key(x,y)return x..','..y end\n    local heap,serial={},0\n    local function less(a,b)return a.score<b.score or(a.score==b.score and a.order<b.order)end\n    local function push(n)\n      serial=serial+1;n.order=serial;heap[#heap+1]=n;local i=#heap\n      while i>1 do local p=i//2;if not less(heap[i],heap[p])then break end;heap[i],heap[p]=heap[p],heap[i];i=p end\n    end\n    local function pop()\n      local n=heap[1];heap[1]=heap[#heap];heap[#heap]=nil;local i=1\n      while heap[i]do local c=i*2;if not heap[c]then break end;if heap[c+1]and less(heap[c+1],heap[c])then c=c+1 end\n        if not less(heap[c],heap[i])then break end;heap[i],heap[c]=heap[c],heap[i];i=c\n      end;return n\n    end\n    local start=key(a.x,a.y);local best={[start]=0};local previous={};local points={[start]=a}\n    push({x=a.x,y=a.y,cost=0,score=math.abs(z.x-a.x)+math.abs(z.y-a.y)})\n    local steps=0\n    while #heap>0 do\n      local n=pop();local id=key(n.x,n.y)\n      if n.x==z.x and n.y==z.y then\n        local path={};while id do table.insert(path,1,points[id]);id=previous[id]end;return path\n      end\n      if n.cost==best[id]then for _,d in ipairs({{1,0},{0,1},{-1,0},{0,-1}})do local x,y=n.x+d[1],n.y+d[2];local k=key(x,y)\n        if x>=bounds.left and x<=bounds.right and y>=bounds.bottom and y<=bounds.top and not blocked(x,y)and(best[k]==nil or n.cost+1<best[k])then\n          best[k]=n.cost+1;previous[k]=id;points[k]={x=x,y=y};push({x=x,y=y,cost=n.cost+1,score=n.cost+1+math.abs(z.x-x)+math.abs(z.y-y)})\n        end\n      end end\n      steps=steps+1;if steps%64==0 and work then work('route')end\n      assert(steps<=50000,'connector routing search limit')\n    end\n    error('connector cannot be routed without overlap')\n  end\n  return R\nend\n", "@missions/maze_route.lua", "t"))()(missions)
missions.maze_encounters = assert(load("-- Spatial encounter adapter; the pure mission machine remains unchanged.\nreturn function(D)\n  local E={}\n  function E.plan(m,work)\n    local groups,owner={},{}\n    for i,c in ipairs(m.cells)do groups[i]={cells={c},count=c.enemy_budget};owner[c.id]=i end\n    local count=#m.cells\n    while count>8 do\n      local bestA,bestB,best\n      for _,c in ipairs(m.cells)do for _,e in ipairs(c.exits)do if e.to then\n        local a,b=owner[c.id],owner[e.to]\n        if a~=b then local size=groups[a].count+groups[b].count\n          local score=#groups[a].cells+#groups[b].cells+size*10\n          if size<=32 and (not best or score<best)then bestA,bestB,best=a,b,score end\n        end\n      end end end\n      assert(bestA,'cannot partition connected spatial waves')\n      local a,b=groups[bestA],groups[bestB]\n      for _,c in ipairs(b.cells)do a.cells[#a.cells+1]=c;owner[c.id]=bestA end\n      a.count=a.count+b.count;groups[bestB]=nil;count=count-1\n      if work then work('partition')end\n    end\n    local map,n={},0\n    for i=1,#m.cells do local group=groups[i]\n      if group and group.count>0 then n=n+1;map[i]=n end\n    end\n    for id,w in pairs(owner)do owner[id]=map[w]end\n    return owner,n\n  end\n  function E.observe(c)\n    if not c.doc.maze then return end\n    local z=c.membership;local room=z and not z.transition and z.room==z.committed and z.committed\n    if room and not c.stream.loaded[room.id]then room=nil end\n    if not c.encounter_cells then c.encounter_cells={}\n      for _,cell in ipairs(c.doc.maze.cells)do c.encounter_cells[cell.id]=cell end\n    end\n    local cell=room and c.encounter_cells[room.id]\n    local wave=cell and cell.enemy_budget>0 and cell.enemy_wave\n    for _,t in ipairs(c.run.state.m.triggers)do if t.action=='wave'then\n      t.x,t.y=99999,99999\n      if t.wave==wave then local r=room.rect;t.x=(r.left+r.right)/2;t.y=(r.bottom+r.top)/2;t.w=r.right-r.left;t.h=r.top-r.bottom end\n    end end\n    c.run.encounter_room=room\n  end\n  function E.actions(c,actions)\n    if not c.doc.maze then return actions end\n    local run=c.run;run.encounter_pending=run.encounter_pending or {};local out={}\n    for _,a in ipairs(actions)do if a.type=='spawn'then run.encounter_pending[a.index]=a else out[#out+1]=a end end\n    if run.state.result then run.encounter_pending={};return out end\n    local room=run.encounter_room\n    local live=0;for _ in pairs(run.state.tracked)do live=live+1 end\n    if room then local r=room.rect\n      for i=1,#run.state.m.enemies do local a=run.encounter_pending[i]\n        if live<D.mission.LIMITS.per_wave and a and a.x>=r.left and a.x<r.right and a.y>=r.bottom and a.y<r.top then out[#out+1]=a;run.encounter_pending[i]=nil;live=live+1 end\n      end\n    end\n    return out\n  end\n  return E\nend\n", "@missions/maze_encounters.lua", "t"))()(missions)
missions.maze = assert(load("-- Pure generation/serialization. Python invokes this exact implementation.\nreturn function(D)\n  local M={};local set=D.maze_set\n  local dirs={{'left',-1,0,'right','L'},{'right',1,0,'left','R'},\n    {'up',0,1,'down','U'},{'down',0,-1,'up','D'}}\n  local function copy(t) if type(t)~='table' then return t end\n    local q={};for k,v in pairs(t) do q[k]=copy(v) end;return q end\n  function M.encode(t,work)\n    if type(t)=='string' then return string.format('%q',t) end\n    if type(t)~='table' then return tostring(t) end\n    if work then work('encode')end\n    local keys={};for k in pairs(t) do keys[#keys+1]=k end\n    table.sort(keys,function(a,b) if type(a)==type(b) then return a<b end return type(a)<type(b) end)\n    local q={};for _,k in ipairs(keys) do q[#q+1]='['..M.encode(k,work)..']='..M.encode(t[k],work) end\n    return '{'..table.concat(q,',')..'}'\n  end\n  function M.random(seed)\n    local state=seed%2147483647;if state==0 then state=1 end\n    return function(n) state=(state*48271)%2147483647;return 1+state%n end\n  end\n  local function line(out,x1,y1,x2,y2,kind,pass,label)\n    out[#out+1]={x1=x1,y1=y1,x2=x2,y2=y2,kind=kind,passthrough=pass or false,draw=true,label=label}\n  end\n  function M.geometry(c,authored)\n    local x,y=c.x*130,c.y*104\n    local q={version=2,units=6.5,parts={},lines={},camera={mode='chunk',margin=4,frames=45}}\n    local function edge(a,b,d,e,kind,label) line(q.lines,x+a,y+b,x+d,y+e,kind,false,label) end\n    -- Double-faced boundary collision; a wall stops entry from either side.\n    local function horizontal(a,b,h,label)\n      edge(a,h,b,h,'floor',label);edge(b,h,a,h,'ceiling',label)\n    end\n    local function vertical(a,b,h,label)\n      edge(h,a,h,b,'left_wall',label);edge(h,b,h,a,'right_wall',label)\n    end\n    if authored then\n      q=copy(authored)\n      q.lines=q.lines or {};q.parts=q.parts or {}\n      local keep={};for _,l in ipairs(q.lines) do if not (l.label and l.label:match('^seal:')) then keep[#keep+1]=l end end\n      q.lines=keep\n      for _,p in ipairs(q.parts) do p.x=p.x+x;p.y=p.y+y;p.name=c.id..'_'..(p.name or p.part) end\n      for _,l in ipairs(q.lines) do l.x1=l.x1+x;l.x2=l.x2+x;l.y1=l.y1+y;l.y2=l.y2+y end\n      for _,p in pairs(q.spawn or {}) do p.x=p.x+x;p.y=p.y+y end\n      for _,p in ipairs(q.markers or {}) do p.x=p.x+x;p.y=p.y+y end\n      local function shift(rect)\n        if rect then rect.left=rect.left+x;rect.right=rect.right+x;rect.bottom=rect.bottom+y;rect.top=rect.top+y end\n      end\n      for _,z in ipairs(q.zones or{})do z.name=c.id..'_'..z.name;shift(z.rect)end\n      shift(q.blast)\n      if q.camera then\n        if q.camera.left then shift(q.camera) end\n        shift(q.camera.ends)\n        if q.camera.x then q.camera.x=q.camera.x+x end\n      end\n    else\n      for _,l in ipairs(set.shell) do edge(l[2],l[3],l[4],l[5],l[1]) end\n    end\n    for _,e in ipairs(c.exits) do if e.sealed then\n      local label='seal:'..e.side..':'..e.slot\n      if e.side=='left' then vertical(0,32,0,label)\n      elseif e.side=='right' then vertical(0,32,130,label)\n      elseif e.side=='up' then horizontal(53,77,104,label)\n      else horizontal(53,77,0,label) end\n    end end\n    for _,p in ipairs(authored and {} or c.platforms) do\n      line(q.lines,x+p.x1,y+p.y,x+p.x2,y+p.y,'floor',true,'climb')\n    end\n    -- Existing kit slabs decorate the supported floor strips and platforms.\n    local slabs=authored and {} or copy(set.slabs)\n    if not authored then for _,p in ipairs(c.platforms) do slabs[#slabs+1]=p end end\n    for i,p in ipairs(slabs) do q.parts[#q.parts+1]={part=set.part,name=c.id..'_slab'..i,\n      x=x+(p.x1+p.x2)/2,y=y+p.y,z=0,rot=0,scale_x=(p.x2-p.x1)/26,\n      collision=false,floor_flags=0} end\n    if not authored then\n      for i,side in ipairs({0,130})do q.parts[#q.parts+1]={part=i==1 and 'bf_wall_solid_4m' or 'bf_wall_doorway_4m',\n        name=c.id..'_wall'..i,x=x+side,y=y+32,z=0,rot=0,scale_x=0.12,scale_y=72/26,collision=false,floor_flags=0}end\n      if c.template=='goal'or c.template=='boss_room'then\n        q.parts[#q.parts+1]={part='bf_door_leaf',name=c.id..'_goal_marker',x=x+104,y=y,z=0,rot=0,collision=false,floor_flags=0}\n      end\n      -- Visually distinguish vertical/turn recipes using the existing beam kit.\n      if c.template=='shaft'or c.template=='corner_up'or c.template=='corner_down'or c.template=='gallery'or c.template=='well'then q.parts[3].part='bf_beam_4m' end\n      if c.template=='vault'or c.template=='switchback'then q.parts[4].part='bf_beam_4m' end\n    end\n    local keep={}\n    for _,l in ipairs(q.lines)do\n      local remove=l.label=='walk_bridge'\n      if l.label=='climb'and c.exits[3].sealed and l.y1-y>54 then remove=true end\n      if l.kind=='ceiling'and l.y1==l.y2 and ((l.y1==y+104 and c.exits[3].sealed)or(l.y1==y and c.exits[4].sealed))then\n        if l.x1==x+43 and l.x2==x then l.x1=x+53 end\n        if l.x1==x+130 and l.x2==x+87 then l.x2=x+77 end\n      end\n      if l.kind=='ceiling'and l.y1==l.y2 and ((l.y1==y+104 and not c.exits[3].sealed)or(l.y1==y and not c.exits[4].sealed))then\n        if l.x1==x+53 and l.x2==x then l.x1=x+43 end\n        if l.x1==x+130 and l.x2==x+77 then l.x2=x+87 end\n      end\n      if not remove then keep[#keep+1]=l end\n    end\n    q.lines=keep;keep={}\n    for _,p in ipairs(q.parts)do\n      local remove=p.name and p.name:find('drop_bridge',1,true)\n      if c.exits[3].sealed and p.part==set.part and p.y-y>54 and p.y-y<104 then remove=true end\n      if not remove then keep[#keep+1]=p end\n    end\n    q.parts=keep\n    return q\n  end\n  function M.generate(seed,options,random)\n    options=options or {};local size=options.size or 12\n    assert(type(seed)=='number' and seed==seed and seed%1==0 and math.abs(seed)<=2147483646,'seed must be signed 31-bit integer')\n    assert(type(size)=='number' and size%1==0 and size>=8 and size<=20,'size must be 8..20')\n    local length=options.length or math.max(4,math.ceil(size*.55))\n    assert(length%1==0 and length>=4 and length<=size,'length must be 4..size')\n    local rng=random or M.random(seed)\n    local function choose(n) local i=rng(n);assert(type(i)=='number' and i%1==0 and i>=1 and i<=n,'RNG out of bounds');return i end\n    options=copy(options);options.size=size;options.length=length\n    local m,dist=D.maze_topology.generate(seed,options,choose,copy)\n    for _,p in ipairs(m.cells) do\n      local needed='';local degree=0\n      for _,d in ipairs(dirs) do if p.links[d[1]] then needed=needed..d[5];degree=degree+1 end end\n      local candidates={}\n      local templates=options.templates or set.templates\n      local function declared(t,side,letter)\n        local exits=t.exits or (t.level and t.level.exits)\n        if exits then\n          for _,e in ipairs(exits) do\n            if e.side==side and e.slot==1 and not e.sealed then return e end\n          end\n          return nil\n        end\n        if t.sides:find(letter,1,true) then\n          for _,e in ipairs(set.exits) do if e.side==side then return e end end\n        end\n      end\n      local function fits(t)\n        for _,d in ipairs(dirs) do if p.links[d[1]] then\n          local e=declared(t,d[1],d[5]);if not e then return false end\n          if (d[1]=='left' or d[1]=='right') and e.traversal~='walk' then return false end\n          if d[1]=='down' and e.traversal~='drop' then return false end\n          if d[1]=='up' and (e.traversal~='climb' and e.traversal~='drop') then return false end\n          if p.forward.up and d[1]=='up' and e.traversal~='climb' then return false end\n        end end;return true\n      end\n      for _,t in ipairs(templates) do\n        if fits(t) and t.id~='start' and t.id~='goal' and t.id~='boss_room' and t.id~='reward_end' then candidates[#candidates+1]=t end\n      end\n      assert(#candidates>0,'no traversable recipe for '..p.id..' '..needed)\n      local different={}\n      for _,t in ipairs(candidates)do local repeat_room=false\n        for _,id in pairs(p.links)do local old=m.cells[tonumber(id:sub(2))];if old.template==t.id then repeat_room=true end end\n        if not repeat_room then different[#different+1]=t end\n      end\n      if #different>0 then candidates=different end\n      local template=candidates[choose(#candidates)]\n      local roles={}\n      for _,t in ipairs(templates) do roles[t.id]=t end\n      if p.id==m.start then template=assert(roles.start,'missing start recipe')\n      elseif p.id==m.goal then template=assert(roles[options.boss and 'boss_room' or 'goal'],'missing goal recipe')\n      elseif degree==1 then template=assert(roles.reward_end,'missing reward recipe');p.reward=true end\n      assert(fits(template),'role recipe lacks required traversable exit')\n      if p.reward then p.reward_amount=25 end\n      p.template=template.id;p.tags=copy(template.tags)\n      if template.platforms then p.platforms=copy(template.platforms) end\n      p.spawn=copy(template.spawn or (template.level and template.level.spawn and template.level.spawn[0]) or set.spawn)\n      p.enemy_slots=copy(template.enemy_slots or set.enemy_slots)\n      p.distance=dist[p.id];p.difficulty=1+dist[p.id]/math.max(1,dist[m.goal])\n      p.enemy_budget=math.min(template.enemy_budget or 3,3,math.floor(dist[p.id]/3))\n      assert(p.enemy_budget>=0 and p.enemy_budget%1==0 and #p.enemy_slots>=p.enemy_budget,'invalid enemy budget/slots')\n      p.enemy_kinds=copy(template.enemy_kinds or set.enemy_kinds)\n      assert(#p.enemy_kinds>0,'enemy kinds must not be empty')\n      for i,e in ipairs(p.exits) do\n        local authored=declared(template,e.side,dirs[i][5])\n        if authored then e.traversal=authored.traversal end\n        e.to=p.links[e.side];e.sealed=e.to==nil\n      end\n      p.links=nil;p.forward=nil;p.level=M.geometry(p,template.level)\n      if options.work then options.work('region geometry')end\n    end\n    if D.maze_clearance then local proof=D.maze_clearance.check(m,options.work);assert(proof.ok,table.concat(proof.errors,'; '))end\n    m.metrics=D.maze_metrics.measure(m)\n    return m\n  end\n  function M.ascii(m)\n    local cells={};local minx,maxx,miny,maxy=0,0,0,0\n    for _,c in ipairs(m.cells) do cells[c.x..','..c.y]=c\n      minx=math.min(minx,c.x);maxx=math.max(maxx,c.x);miny=math.min(miny,c.y);maxy=math.max(maxy,c.y) end\n    local rows={'maze seed='..m.seed..' size='..#m.cells..' (L R U D; *=sealed)'}\n    for y=maxy,miny,-1 do local row={}\n      for x=minx,maxx do local c=cells[x..','..y]\n        if not c then row[#row+1]='[     ]' else\n          local text=c.id==m.start and 'S' or c.id==m.goal and 'G' or c.reward and '$' or '.'\n          for i,e in ipairs(c.exits) do text=text..(e.to and dirs[i][5] or '*') end\n          row[#row+1]='['..text..']'\n        end\n      end;rows[#rows+1]=table.concat(row,'')\n    end\n    local q=m.metrics or D.maze_metrics.measure(m)\n    rows[#rows+1]=('shape branches=%d dead_end=%d turns=%d cycles=%d L/R/U/D=%d/%d/%d/%d'):format(q.branches,q.longest_dead_end,q.turns,q.cycles,q.directions.left,q.directions.right,q.directions.up,q.directions.down)\n    return table.concat(rows,'\\n')\n  end\n  function M.starters()\n    local files,templates={},copy(set.templates)\n    for _,t in ipairs(templates) do\n      local c={id=t.id,template=t.id,x=0,y=0,platforms=copy(set.platforms),exits=copy(set.exits)}\n      for i,e in ipairs(c.exits) do e.sealed=not t.sides:find(dirs[i][5],1,true) end\n      local level=M.geometry(c);level.size=copy(set.size);level.exits=copy(c.exits)\n      level.tags=copy(t.tags);level.spawn={[0]=copy(set.spawn)}\n      t.level=level;t.platforms=copy(set.platforms)\n      files['missions/maze-chunks/'..t.id..'/level.lua']='return '..M.encode(level)..'\\n'\n    end\n    files['missions/maze-chunks/library.lua']='return '..M.encode(templates)..'\\n'\n    return files\n  end\n  function M.files(m,name,work)\n    assert(name:match('^[%w_-]+$'),'unsafe folder name')\n    local report=m.world and D.maze_world_check.check(m,work)or D.maze_check.check(m,work);assert(report.ok,table.concat(report.errors,'; '))\n    local root={version=2,units=6.5,parts={},chunks={},camera={mode='chunk'},markers={},zones={}}\n    local mission={enemies={},triggers={},objective={type='reach_goal'}}\n    local files={};local folder='missions/'..name..'/'\n    local owner,waves=D.maze_encounters.plan(m,work)\n    for w=1,waves do mission.triggers[#mission.triggers+1]={x=99999,y=99999,w=1,h=1,action='wave',wave=w}end\n    local bounds={left=0,right=130,bottom=0,top=104}\n    for _,r in ipairs(m.world and m.world.regions or {})do root.zones[#root.zones+1]={name='region_'..r.id,kind='region',region=r.id,rect=copy(r.rect)}end\n    for _,c in ipairs(m.cells) do local x,y=c.x*130,c.y*104\n      local spawn={x=x+c.spawn.x,y=y+c.spawn.y}\n      root.chunks[#root.chunks+1]={id=c.id,rect={left=x,right=x+130,bottom=y,top=y+104},spawn=spawn}\n      root.zones[#root.zones+1]={name='room_'..c.id,kind='room',room=c.id,rect={left=x,right=x+130,bottom=y,top=y+104}}\n      for _,e in ipairs(c.exits)do if e.to and tonumber(c.id:sub(2))<tonumber(e.to:sub(2))then\n        local rect\n        if e.side=='left'or e.side=='right'then local border=x+(e.side=='right'and 130 or 0)\n          rect={left=border-8,right=border+8,bottom=y,top=y+32}\n        else local border=y+(e.side=='up'and 104 or 0)\n          rect={left=x+53,right=x+77,bottom=border-12,top=border+12}\n        end\n        root.zones[#root.zones+1]={name='door_'..c.id..'_'..e.to,kind='transition',rooms={c.id,e.to},rect=rect,\n          camera={ease_frames=24,curve='smoothstep',doorway_margin=12}}\n      end end\n      root.markers[#root.markers+1]={name=c.id,x=spawn.x,y=spawn.y}\n      bounds.left=math.min(bounds.left,x);bounds.right=math.max(bounds.right,x+130)\n      bounds.bottom=math.min(bounds.bottom,y);bounds.top=math.max(bounds.top,y+104)\n      if c.id==m.start then mission.start=spawn end\n      if c.id==m.goal then mission.goal={x=x+104,y=y+12,w=24,h=32} end\n      for i=1,c.enemy_budget do local p=c.enemy_slots[i]\n        assert(p.x>=0 and p.x<130 and p.y>=0 and p.y<104,'enemy slot outside chunk')\n        mission.enemies[#mission.enemies+1]={x=x+p.x,y=y+p.y,kind=c.enemy_kinds[(i-1)%#c.enemy_kinds+1],\n          wave=owner[c.id]}\n      end\n      local child=copy(c.level);child.size=copy(set.size);child.exits=copy(c.exits)\n      child.maze={template=c.template,tags=c.tags,difficulty=c.difficulty,enemy_budget=c.enemy_budget}\n      files[folder..'chunks/'..c.id..'/level.lua']='return '..M.encode(child,work)..'\\n'\n    end\n    root.blast={left=bounds.left-200,right=bounds.right+200,bottom=bounds.bottom-200,top=bounds.top+200}\n    root.maze={};for k,v in pairs(m)do if k~='cells'then root.maze[k]=copy(v)end end\n    root.maze.cells={}\n    for _,c in ipairs(m.cells)do local q={};for k,v in pairs(c)do if k~='level'then q[k]=copy(v)end end\n      q.enemy_wave=owner[c.id];root.maze.cells[#root.maze.cells+1]=q;if work then work('metadata')end\n    end\n    files[folder..'level.lua']='return '..M.encode(root,work)..'\\n'\n    files[folder..'mission.lua']='return '..M.encode(mission,work)..'\\n'\n    return files\n  end\n  return M\nend\n", "@missions/maze.lua", "t"))()(missions)
missions.maze_world = assert(load("-- Regions stay independently seeded; connectors form one continuous streamed graph.\nreturn function(D)\n  local W={MAX_CHUNKS=512,MAX_COORD=40000,MAX_REGIONS=6}\n  local dirs={{'left',-1,0,2},{'right',1,0,1},{'up',0,1,4},{'down',0,-1,3}}\n  local function copy(t)if type(t)~='table'then return t end;local q={};for k,v in pairs(t)do q[k]=copy(v)end;return q end\n  function W.generate(seed,options)\n    options=options or{};local n,size=options.regions or 4,options.size or 12;local work=options.work\n    assert(type(seed)=='number'and seed==seed and seed%1==0 and math.abs(seed)<=2147483646,'world seed must be signed31-bit integer')\n    assert(n%1==0 and n>=2 and n<=W.MAX_REGIONS,'world regions must be2..6');assert(size%1==0 and size>=8 and size<=20,'region size must be8..20')\n    local m={version=2,seed=seed,cells={},main_path={},world={seed=seed,size=size,start='r1',goal='r'..n,regions={},links={}}}\n    local occupied,authored,recipes={},{},{};local function key(x,y)return x..','..y end\n    local function append(c)\n      assert(not occupied[key(c.x,c.y)],'world overlap '..c.id);m.cells[#m.cells+1]=c;occupied[key(c.x,c.y)]=c\n      assert(#m.cells<=W.MAX_CHUNKS,'world exceeds512 chunks; use a real level change')\n      assert(math.abs(c.x*130)+130<W.MAX_COORD and math.abs(c.y*104)+104<W.MAX_COORD,'world exceeds40000-unit bounds; use a real level change')\n    end\n    for i=1,n do\n      local id='r'..i;local derived=((seed%2147483647+i*104729)*48271)%2147483647\n      local rseed=options.seeds and options.seeds[id]or derived\n      local themes={'gallery','vault','well','switchback'};local theme=themes[(derived%4)+1]\n      local templates={}\n      for _,t in ipairs(options.templates or D.maze_set.templates)do\n        local role=t.id=='start'or t.id=='goal'or t.id=='boss_room'or t.id=='reward_end'\n        if role or t.id==theme or not(t.id=='gallery'or t.id=='vault'or t.id=='well'or t.id=='switchback')then templates[#templates+1]=t end\n      end\n      local byname={};for _,t in ipairs(templates)do byname[t.id]=t end\n      local localmaze=D.maze.generate(rseed,{size=size,templates=templates,boss=i==n,loops=true,work=work})\n      local region={id=id,seed=rseed,theme=i==n and 'boss'or theme,chunks={},map=D.maze.ascii(localmaze)}\n      local rename={};for j,c in ipairs(localmaze.cells)do rename[c.id]='c'..(#m.cells+j)end\n      local quota=64//n+(i<=64%n and 1 or 0)\n      local left,right,bottom,top=math.huge,-math.huge,math.huge,-math.huge\n      for _,source in ipairs(localmaze.cells)do local c=copy(source);c.level=nil;c.id=rename[c.id];c.region=id\n        recipes[c.id]=byname[c.template];authored[c.id]=recipes[c.id]and recipes[c.id].level\n        c.x=c.x+(i-1)*(2*size+6)+size;c.y=c.y+size\n        if i~=n and c.template=='goal'then c.template='gallery'\n          if authored[c.id]then authored[c.id]=copy(authored[c.id]);local keep={};for _,p in ipairs(authored[c.id].parts or{})do if not(p.name and p.name:find('goal_marker',1,true))then keep[#keep+1]=p end end;authored[c.id].parts=keep end\n        end\n        for _,e in ipairs(c.exits)do if e.to then e.to=rename[e.to]end end\n        c.enemy_budget=math.min(c.enemy_budget,quota);quota=quota-c.enemy_budget\n        append(c);region.chunks[#region.chunks+1]=c.id\n        left=math.min(left,c.x);right=math.max(right,c.x+1);bottom=math.min(bottom,c.y);top=math.max(top,c.y+1)\n      end\n      region.start=rename[localmaze.start];region.goal=rename[localmaze.goal];region.grid={left=left,right=right,bottom=bottom,top=top}\n      region.rect={left=left*130,right=right*130,bottom=bottom*104,top=top*104};m.world.regions[i]=region\n      if i==1 then m.start=region.start end;if i==n then m.goal=region.goal end\n      if work then work('region '..id)end\n    end\n    local edges={};for i=1,n-1 do edges[#edges+1]={i,i+1,2,1}end\n    if n>=3 then table.insert(edges,n,{1,n==3 and n or n-1,3,3})end\n    local used={}\n    local function port(region,preferred)\n      local order={preferred};for side=1,4 do if side~=preferred then order[#order+1]=side end end\n      for _,side in ipairs(order)do local d=dirs[side];local best,candidates=nil,{}\n        for _,id in ipairs(region.chunks)do local c=m.cells[tonumber(id:sub(2))];local value=c.x*d[2]+c.y*d[3]\n          if not best or value>best then best=value;candidates={c}elseif value==best then candidates[#candidates+1]=c end\n        end\n        for _,c in ipairs(candidates)do\n          local recipe=recipes[c.id];local capable=not recipe\n          local exits=recipe and(recipe.exits or(recipe.level and recipe.level.exits))\n          if exits then for _,e in ipairs(exits)do if e.side==d[1]and not e.sealed then capable=true end end\n          elseif recipe and recipe.sides then capable=recipe.sides:find(d[1]:sub(1,1):upper(),1,true)~=nil end\n          if capable and not used[c.id..':'..side]and not occupied[key(c.x+d[2],c.y+d[3])]then used[c.id..':'..side]=true;return c,side end\n        end\n      end\n      error('no connector-capable exterior port for '..region.id)\n    end\n    local function stitch(a,z)\n      local side;for i,d in ipairs(dirs)do if z.x==a.x+d[2]and z.y==a.y+d[3]then side=i end end\n      assert(side,'connector cells are not adjacent');local opposite=dirs[side][4]\n      assert(not a.exits[side].to and not z.exits[opposite].to,'connector reuses an occupied exit')\n      a.exits[side].to=z.id;a.exits[side].sealed=false;z.exits[opposite].to=a.id;z.exits[opposite].sealed=false\n      if side==3 then a.exits[side].traversal='climb'elseif side==4 then z.exits[opposite].traversal='climb'end\n    end\n    for index,edge in ipairs(edges)do\n      local a,z=m.world.regions[edge[1]],m.world.regions[edge[2]];local from,aside=port(a,edge[3]);local to,zside=port(z,edge[4]);local da,dz=dirs[aside],dirs[zside]\n      local start={x=from.x+da[2],y=from.y+da[3]};local finish={x=to.x+dz[2],y=to.y+dz[3]}\n      local function blocked(x,y)\n        if occupied[key(x,y)]then return true end\n        for _,r in ipairs(m.world.regions)do local b=r.grid;if x>=b.left and x<b.right and y>=b.bottom and y<b.top then return true end end\n        return false\n      end\n      local path=D.maze_route.find(start,finish,blocked,{left=-size-8,right=n*(2*size+6),bottom=-size-8,top=3*size+24},work)\n      local link={name='connector'..index,a=a.id,b=z.id,from=from.id,to=to.id,chunks={}}\n      local previous=from\n      for _,p in ipairs(path)do local c={id='c'..(#m.cells+1),x=p.x,y=p.y,template='gallery',connector=link.name,\n        tags={'connector'},enemy_budget=0,enemy_slots=copy(D.maze_set.enemy_slots),enemy_kinds=copy(D.maze_set.enemy_kinds),\n        platforms=copy(D.maze_set.platforms),spawn=copy(D.maze_set.spawn),exits=copy(D.maze_set.exits),difficulty=1,distance=0}\n        for _,e in ipairs(c.exits)do e.sealed=true end\n        append(c);link.chunks[#link.chunks+1]=c.id;stitch(previous,c);previous=c\n        if work then work('connector chunk')end\n      end\n      stitch(previous,to);m.world.links[#m.world.links+1]=link\n    end\n    for _,c in ipairs(m.cells)do c.level=D.maze.geometry(c,authored[c.id]);if work then work('geometry')end end\n    m.size=#m.cells\n    local parents={[m.start]=false};local queue={m.start};local i=1\n    while queue[i]do local c=m.cells[tonumber(queue[i]:sub(2))];i=i+1\n      for _,e in ipairs(c.exits)do if e.to and parents[e.to]==nil then parents[e.to]=c.id;queue[#queue+1]=e.to end end\n    end\n    local at=m.goal;while at do table.insert(m.main_path,1,at);at=parents[at]end\n    m.metrics=D.maze_metrics.measure(m);local proof=D.maze_world_check.check(m,work);assert(proof.ok,table.concat(proof.errors,'; '))\n    return m\n  end\n  function W.ascii(m)\n    local rows={'world seed='..m.seed..' start='..m.world.start..' goal='..m.world.goal..' chunks='..#m.cells,'connectors:'}\n    local ids={};for _,c in ipairs(m.cells)do ids[c.id]=c end\n    for _,e in ipairs(m.world.links)do rows[#rows+1]=e.a..(e.oneway and ' -> 'or ' <-> ')..e.b..' ['..e.name..', '..#e.chunks..' chunks; '..e.from..' / '..e.to..']'end\n    for _,r in ipairs(m.world.regions)do\n      rows[#rows+1]=r.id..' seed='..r.seed..' theme='..r.theme\n      local grid={};for _,id in ipairs(r.chunks)do local c=ids[id];grid[c.x..','..c.y]=c end\n      for y=r.grid.top-1,r.grid.bottom,-1 do local row={}\n        for x=r.grid.left,r.grid.right-1 do local c=grid[x..','..y]\n          if not c then row[#row+1]='[     ]'else\n            local text=c.id==m.start and 'S'or c.id==m.goal and 'G'or c.reward and '$'or '.'\n            for i,e in ipairs(c.exits)do text=text..(e.to and dirs[i][1]:sub(1,1):upper()or '*')end\n            row[#row+1]='['..text..']'\n          end\n        end;rows[#rows+1]=table.concat(row,'')\n      end\n    end\n    return table.concat(rows,'\\n')\n  end\n  return W\nend\n", "@missions/maze_world.lua", "t"))()(missions)
missions.loader = assert(load("-- Read and validate the entire folder before any gameplay writes.\nreturn function(D)\n  local V,L=D.validator,{}\n  -- Runtime cannot write the mounted mod. Generated data uses an overlay;\n  -- models still resolve to real mounted kit files. Ordinary folders are unchanged.\n  L.generated={}\n  function L.view(g)\n    return setmetatable({\n      mod_read=function(path)\n        for _,doc in pairs(L.generated) do if doc.files[path] then return doc.files[path] end end\n        return g.mod_read(path)\n      end,\n      mod_stamp=function(path)\n        for _,doc in pairs(L.generated) do if doc.files[path] then return doc.stamp end end\n        return g.mod_stamp(path)\n      end,\n    },{__index=g})\n  end\n  function L.data(g,path,optional)\n    local text,why=g.mod_read(path)\n    if text==nil then\n      assert(optional and g.mod_stamp(path)==nil,'cannot read '..path..': '..tostring(why))\n      return nil\n    end\n    local f,err=load(text,'@'..path,'t',{})\n    assert(f,err)\n    local ok,value=pcall(f);assert(ok,value)\n    V.plain(value,path)\n    return value\n  end\n  function L.catalogue(g,folder,shared)\n    for name,doc in pairs(L.generated) do\n      if folder:sub(1,#name)==name then return doc.catalogue end\n    end\n    local entries,why=g.mod_list(folder..'models/')\n    assert(entries or (shared and next(shared)),'cannot list models: '..tostring(why))\n    local out={}\n    for _,e in ipairs(entries or {}) do\n      if not e.dir and type(e.name)=='string' then\n        local name=e.name:match('^(.-)%.gxmesh$')\n        if name then V.name(name);out[name]=folder..'models/'..e.name end\n      end\n    end\n    -- Root meshes resolve their sidecars/colour/glow in the shared models folder.\n    -- Prefer them over duplicated chunk copies; retain unique chunk-local meshes.\n    for name,path in pairs(shared or {}) do out[name]=path end\n    return out\n  end\n  function L.stamps(g,folder)\n    g=L.view(g)\n    return {g.mod_stamp(folder..'level.lua'),g.mod_stamp(folder..'mission.lua')}\n  end\n  function L.same(a,b) return a[1]==b[1] and a[2]==b[2] end\n  function L.folder(g,name,work)\n    g=L.view(g)\n    V.name(name)\n    local folder='missions/'..name..'/'\n    local stamps=L.stamps(g,folder)\n    local prepared=L.generated[folder]\n    if prepared and prepared.doc and L.same(prepared.doc.stamps,stamps)then return prepared.doc end\n    local data=L.data(g,folder..'level.lua')\n    if data.maze and D.maze_check then\n      local proof=D.maze_check.folder(g,name,work)\n      assert(proof.ok,'maze refused: '..table.concat(proof.errors,'; '))\n    end\n    local catalogue=L.catalogue(g,folder)\n    local level=V.layout(data,catalogue,work)\n    local raw=L.data(g,folder..'mission.lua',true)\n    local mission=raw and D.mission.validate(raw) or level.mission\n    assert(mission,'folder needs mission.lua or an embedded mission')\n    assert(not D.mission.check_playable(mission),D.mission.check_playable(mission))\n    local waves={};for _,e in ipairs(mission.enemies) do waves[e.wave]=true end\n    for _,p in ipairs(level.markers) do\n      assert(p.checkpoint==nil or mission.checkpoints[p.checkpoint],'marker checkpoint does not exist')\n      for _,w in ipairs(p.cleared_waves) do assert(waves[w],'marker cleared wave does not exist') end\n    end\n    local chunks,ids={},{}\n    V.list(data.chunks or {},'chunks',4096)\n    for i,c in ipairs(data.chunks or {}) do\n      V.plain(c,'chunk');V.name(c.id);assert(not ids[c.id],'duplicate chunk id');ids[c.id]=true\n      local rect=V.rect(c.rect,'chunk rectangle');local spawn=V.point(c.spawn,'chunk spawn')\n      if chunks[1] then\n        local first=chunks[1].rect;local w,h=first.right-first.left,first.top-first.bottom\n        local function integral(n) return math.abs(n-math.floor(n+0.5))<0.000001 end\n        assert(math.abs(rect.right-rect.left-w)<0.000001 and math.abs(rect.top-rect.bottom-h)<0.000001,\n               'chunks must have equal rectangle sizes for a 3x3 grid')\n        assert(integral((rect.left-first.left)/w) and integral((rect.bottom-first.bottom)/h),'chunks must align to the grid')\n      end\n      assert(spawn.x>=rect.left and spawn.x<rect.right and spawn.y>=rect.bottom and spawn.y<rect.top,'spawn outside chunk')\n      for _,old in ipairs(chunks) do\n        local b=old.rect\n        assert(not (rect.left<b.right and rect.right>b.left and rect.bottom<b.top and rect.top>b.bottom),'overlapping chunks')\n      end\n      local path=folder..'chunks/'..c.id..'/'\n      local child=V.layout(L.data(g,path..'level.lua'),L.catalogue(g,path,catalogue),work)\n      assert(not child.mission,'chunk mission belongs in the root mission.lua')\n      local camera={}\n      for k,v in pairs(level.camera_settings or {}) do camera[k]=v end\n      for k,v in pairs(child.camera_settings or {}) do camera[k]=v end\n      V.camera(camera) -- catch conflicting inherited parameters even in unloaded chunks\n\n      chunks[i]={id=c.id,serial=i,rect=rect,spawn=spawn,level=child}\n      if work then work('validate child')end\n    end\n    assert(L.same(stamps,L.stamps(g,folder)),'folder changed while reading; retry export')\n    local doc={name=name,folder=folder,level=level,mission=mission,catalogue=catalogue,chunks=chunks,stamps=stamps,maze=data.maze}\n    if D.zones then D.zones.prepare(doc,work)end\n    return doc\n  end\n  return L\nend\n", "@missions/loader.lua", "t"))()(missions)
missions.world = assert(load("-- Area builders own geometry; references are released only after their instances disappear.\nreturn function(D)\n  local W={}\n  function W.options(p)\n    local o={}\n    for _,k in ipairs({'x','y','z','rot','scale','scale_x','scale_y','scale_z','collision','floor_flags'}) do o[k]=p[k] end\n    return o\n  end\n  function W.load(g,name,level,staging)\n    local area={name=name,assets={},parts={},level=level,replacements={},serial=0,lines={},borrowed=staging and staging.assets,offset=staging and staging.offset}\n    local ok,why=pcall(function()\n      for _,p in ipairs(level.parts) do\n        if not area.assets[p.path] then area.assets[p.path]=staging and assert(staging.assets[p.path]) or assert(g.model_load(p.path)) end\n      end\n      local prepared=g.area_prepare and g.area_activate\n      local build=prepared and g.area_prepare or g.area_load\n      local token=build(name,function()\n        for i,p in ipairs(level.parts) do\n          local options=W.options(p)\n          if staging then options.y=options.y+staging.offset;options.visible=false end\n          area.parts[i]={handle=assert(g.model_spawn(area.assets[p.path],options)),part=p,position_offset=staging and staging.offset or 0}\n          if g.model_label then g.model_label(area.parts[i].handle,p.label or p.part) end\n        end\n        for _,l in ipairs(level.lines) do\n          local offset=staging and staging.offset or 0\n          area.lines[#area.lines+1]={handle=assert(g.stage_add_line(l.x1,l.y1+offset,l.x2,l.y2+offset,l.kind,l.opts)),line=l}\n        end\n      end)\n      assert(token,'area construction refused');area.constructed=true\n      if prepared then area.prepared=token;assert(g.area_activate(token),'area activation refused')end\n    end)\n    if not ok then\n      if area.constructed then pcall(g.area_unload,name)end\n      if not area.borrowed then for _,a in pairs(area.assets) do pcall(g.model_release,a) end end\n      error(why,0)\n    end\n    return area\n  end\n  function W.unload(g,a)\n    for _,replacement in pairs(a.replacements) do W.unload(g,replacement) end\n    -- Match-end hooks may run after native scene cleanup has reclaimed these handles.\n    local ok,why=pcall(g.area_unload,a.name)\n    if not ok and g.match().active then g.log('mission: cleanup refused '..tostring(why)) end\n    if not a.borrowed then for _,asset in pairs(a.assets) do pcall(g.model_release,asset) end end\n  end\n  function W.position(g,area,offset)\n    if (area.offset or 0)==offset then return end\n    for _,replacement in pairs(area.replacements) do W.position(g,replacement,offset) end\n    for _,entry in ipairs(area.parts) do\n      local options=W.options(entry.part);options.y=options.y+offset;options.visible=offset==0\n      local live=g.model_get and g.model_get(entry.handle);local desired={}\n      for k,v in pairs(options)do if k~='collision'and k~='floor_flags'then desired[k]=v end end\n      local changed=entry.position_offset~=offset\n      if live and D.install_restore then changed=not D.install_restore.same(live,desired)end\n      if changed then assert(g.model_set(entry.handle,options),'model activation refused')end\n      entry.position_offset=offset\n    end\n    for _,entry in ipairs(area.lines) do\n      local l=entry.line\n      if (entry.position_offset or area.offset or 0)~=offset then\n        assert(g.stage_move(entry.handle,(l.x1+l.x2)/2,(l.y1+l.y2)/2+offset),'line activation refused');entry.position_offset=offset\n      end\n    end\n    area.offset=offset\n  end\n  function W.bounds(g,level)\n    for _,k in ipairs({'camera','blast'}) do\n      local b=level[k]\n      if b then\n        if D.install_restore then D.install_restore.bounds(g,k,b)else assert(g['stage_set_'..k..'_bounds'](b.left,b.right,b.top,b.bottom))end\n      end\n    end\n    for slot,p in pairs(level.spawn)do\n      if D.install_restore then D.install_restore.spawn(g,slot,p)else assert(g.stage_set_spawn(slot,p.x,p.y))end\n    end\n  end\n  -- Trigger edits can touch hundreds of instances. Visit at most one match per tick.\n  function W.collision_tick(g,current,job)\n    job.area=job.area or 1;job.part=job.part or 1\n    while job.areas[job.area]do\n      local area=job.areas[job.area];local live=area==current.root\n      for _,v in pairs(current.stream.loaded)do if v==area then live=true;break end end\n      if live then\n        while area.parts[job.part]do\n          local entry=area.parts[job.part];job.part=job.part+1;local p=entry.part;local a=job.action\n          if (p.x-a.x)^2+(p.y-a.y)^2<=a.r^2 then\n            -- A one-entry view retains the area's ownership and replacement table.\n            local view={name=area.name,parts={entry},serial=area.serial,replacements=area.replacements}\n            W.collision(g,{view},a);area.serial=view.serial;return false,true\n          end\n        end\n      end\n      job.area=job.area+1;job.part=1\n    end\n    return true,false\n  end\n  function W.collision(g,areas,a)\n    -- Collision is spawn-only. Replacement areas belong to the source area and\n    -- are unloaded with it, including on streaming, reload and script unload.\n    local changed={}\n    local ok,why=pcall(function()\n      for _,area in ipairs(areas) do\n      for i,entry in ipairs(area.parts) do\n        local p=entry.part\n        if (p.x-a.x)^2+(p.y-a.y)^2<=a.r^2 then\n          local q=W.options(p);q.part=p.part;q.path=p.path;q.label=p.label;q.collision=not a.open\n          area.serial=area.serial+1\n          local replacement=W.load(g,area.name..'_r'..area.serial..'_'..i,{parts={q},lines={}})\n          changed[#changed+1]={area=area,replacement=replacement,entry=entry,new=replacement.parts[1].handle,old=entry.handle}\n        end\n      end\n      end\n    end)\n    if not ok then for _,c in ipairs(changed) do W.unload(g,c.replacement) end error(why,0) end\n    for _,c in ipairs(changed) do\n      g.model_despawn(c.old)\n      local previous=c.area.replacements[c.entry]\n      if previous then W.unload(g,previous) end\n      c.entry.handle=c.new;c.area.replacements[c.entry]=c.replacement\n    end\n  end\n  return W\nend\n", "@missions/world.lua", "t"))()(missions)
missions.zones = assert(load("-- Non-physical authored membership; P1 cur_pos (x,y), once per logic frame.\nreturn function(D)\n  local Z={defaults={commit_distance=8,vertical_commit_distance=12,ease_frames=24,curve='smoothstep',doorway_margin=12}}\n  local function inside(b,p,closed)\n    return p and p.x>=b.left and (closed and p.x<=b.right or p.x<b.right)\n      and p.y>=b.bottom and (closed and p.y<=b.top or p.y<b.top)\n  end\n  local function overlap(a,b)return a.left<b.right and a.right>b.left and a.bottom<b.top and a.top>b.bottom end\n  function Z.tuning(doc,door,room)\n    local q={};for k,v in pairs(Z.defaults)do q[k]=v end\n    for k,v in pairs(doc.level.camera_settings or {})do q[k]=v end\n    for k,v in pairs(room and room.level and room.level.camera_settings or {})do q[k]=v end\n    for k,v in pairs(q.doors and door and q.doors[door.name] or {})do q[k]=v end\n    for k,v in pairs(door and door.camera or {})do q[k]=v end\n    return q\n  end\n  function Z.prepare(doc,work)\n    if doc.zone_data then return doc.zone_data end\n    local out={zones={},rooms={},regions={},chunks={}};local names={};local authored_rooms=false;local authored_doors=false\n    for _,c in ipairs(doc.chunks)do out.chunks[c.id]=c end\n    local function add(z)\n      assert(not names[z.name],'duplicate zone '..z.name);names[z.name]=true\n      out.zones[#out.zones+1]=z\n      if z.kind=='room' then\n        assert(out.chunks[z.room],'unknown room '..tostring(z.room)..' in '..z.name)\n        for _,old in ipairs(out.rooms)do assert(not overlap(z.rect,old.rect),'overlapping room zones '..old.name..' and '..z.name)end\n        out.rooms[#out.rooms+1]=z\n      elseif z.kind=='region'then out.regions[#out.regions+1]=z\n      else\n        for _,id in ipairs(z.rooms)do assert(out.chunks[id],'unknown room '..id..' in '..z.name)end\n      end\n      if work then work('zone membership')end\n    end\n    local function authored(level)\n      for _,z in ipairs(level.zones or {})do\n        if z.kind=='room' then authored_rooms=true elseif z.kind=='transition'then authored_doors=true end;add(z)\n      end\n    end\n    authored(doc.level);for _,c in ipairs(doc.chunks)do authored(c.level or {})end\n    if not authored_rooms then for _,c in ipairs(doc.chunks)do add({name='room_'..c.id,kind='room',room=c.id,rect=c.rect})end end\n    local cells={};for _,c in ipairs(doc.maze and doc.maze.cells or {})do cells[c.id]=c end\n    if not authored_doors then\n      for i,a in ipairs(doc.chunks)do for j=i+1,#doc.chunks do\n        local b=doc.chunks[j];local ar,br=a.rect,b.rect;local axis,border,lo,hi,side\n        if ar.right==br.left or br.right==ar.left then\n          axis='x';border=ar.right==br.left and ar.right or ar.left;side=ar.right==br.left and 'right' or 'left'\n          lo=math.max(ar.bottom,br.bottom);hi=math.min(ar.top,br.top)\n        elseif ar.top==br.bottom or br.top==ar.bottom then\n          axis='y';border=ar.top==br.bottom and ar.top or ar.bottom;side=ar.top==br.bottom and 'up' or 'down'\n          lo=math.max(ar.left,br.left);hi=math.min(ar.right,br.right)\n        end\n        local cell=cells[a.id];local open=not cell\n        if cell then for _,e in ipairs(cell.exits or {})do if e.side==side and e.to==b.id and not e.sealed then open=true end end end\n        if axis and lo<hi and open then\n          local z={name='door_'..a.id..'_'..b.id,kind='transition',rooms={a.id,b.id},axis=axis}\n          local q=Z.tuning(doc,z,a);local distance=axis=='x' and q.commit_distance or q.vertical_commit_distance\n          if cell then\n            if axis=='x' then lo,hi=ar.bottom,ar.bottom+32 else lo,hi=ar.left+53,ar.left+77 end\n          end\n          z.rect=axis=='x' and {left=border-distance,right=border+distance,bottom=lo,top=hi}\n            or {bottom=border-distance,top=border+distance,left=lo,right=hi}\n          add(z)\n        end\n      end end\n    end\n    doc.zone_data=out;return out\n  end\n  -- Only this adapter knows about native membership. Until an owner supplies a\n  -- name mapping, Lua volumes are authoritative; raw native handle lists are not guessed.\n  function Z.source(g,data,p)\n    if g.zones_at and Z.native_source then\n      local result=Z.native_source(g.zones_at(1),data,p)\n      if result then return result end\n    end\n    local hits={};for _,z in ipairs(data.zones)do if inside(z.rect,p,z.kind=='transition')then hits[#hits+1]=z end end\n    return hits\n  end\n  function Z.initial(doc,p,previous)\n    local data=Z.prepare(doc)\n    if previous and data.chunks[previous.id]then return data.chunks[previous.id]end\n    local door,room\n    for _,z in ipairs(data.zones)do if inside(z.rect,p,z.kind=='transition')then\n      if z.kind=='transition' then door=door or z elseif z.kind=='room'then room=data.chunks[z.room]end\n    end end\n    if not door then return room end\n    -- A fresh marker inside a doorway has no crossing history: prefer the\n    -- authored start room if joined, otherwise the door's first declared room.\n    for _,id in ipairs(door.rooms)do\n      for _,z in ipairs(data.rooms)do if z.room==id and inside(z.rect,doc.mission.start)then return data.chunks[id]end end\n    end\n    return data.chunks[door.rooms[1]]\n  end\n  function Z.sample(g,c,p,frame)\n    if c.membership and c.membership.frame==frame then return c.membership end\n    local initializing=not c.zone_state\n    local data=Z.prepare(c.doc);local st=c.zone_state or {committed=c.stream.current,transitions=0,lock=0};c.zone_state=st\n    local prior={committed=st.committed,lock=st.lock,transitions=st.transitions,door=st.door}\n    local hits=Z.source(g,data,p)\n    if not p or (p.action and p.action<=13)then hits={}end\n    local rooms,doors={},{}\n    for _,z in ipairs(hits)do if z.kind=='room' then rooms[#rooms+1]=z elseif z.kind=='transition'then doors[#doors+1]=z end end\n    table.sort(doors,function(a,b)return a.name<b.name end)\n    local door=doors[1];local room=#rooms==1 and data.chunks[rooms[1].room] or nil\n    local outside=#rooms==0 and #doors==0 and #data.rooms>0\n    if outside and not st.outside then g.log('mission: zones outside left='..(st.last_names or 'none')..'; committed='..(st.committed and st.committed.id or 'none'))end\n    if not outside and st.outside then\n      local names={};for _,z in ipairs(hits)do names[#names+1]=z.name end\n      g.log('mission: zones re-enter '..table.concat(names,','))\n    end\n    if not outside then local names={};for _,z in ipairs(hits)do names[#names+1]=z.name end;st.last_names=table.concat(names,',')end\n    st.outside=outside\n    if door then st.door=door end\n    local tuning=Z.tuning(c.doc,door or st.door,room or st.committed);local changed=false\n    if room and not door and room~=st.committed and frame>=st.lock and (not initializing or not st.committed) then\n      local old=st.committed\n      -- Upward airborne excursions do not own an upper room until landing.\n      local upward=old and room.rect.bottom>=old.rect.top\n      if not (upward and p and p.airborne==true)then\n        st.committed=room;changed=true\n        if old then st.transitions=st.transitions+1;st.lock=frame+(tuning.mode=='chunk' and tuning.ease_frames or 0) end\n        st.door=nil\n        g.log('mission: zones commit '..room.id)\n      end\n    end\n    local result={frame=frame,point=p,hits=hits,room=room,transition=door,outside=outside,\n      prior=prior,committed=st.committed,changed=changed,transitions=st.transitions,tuning=tuning,lock=st.lock}\n    result.region=Z.region(c.doc,result.committed)\n    c.membership=result;c.stream.membership=result;c.stream.zone_state=st;return result\n  end\n  function Z.region(doc,room)\n    if doc.maze and doc.maze.world and room then\n      for _,cell in ipairs(doc.maze.cells)do if cell.id==room.id then return cell.region or cell.connector end end\n    end\n  end\n  function Z.reject(stream,result)\n    if not result or not result.changed then return end\n    local st=stream.zone_state\n    for k,v in pairs(result.prior)do st[k]=v end\n    st.committed=result.prior.committed;st.door=result.prior.door\n    result.committed=st.committed;result.changed=false;result.transitions=st.transitions;result.region=Z.region(stream.doc,result.committed)\n  end\n  function Z.describe(g,c)\n    local data=Z.prepare(c.doc)\n    for _,z in ipairs(data.zones)do local b=z.rect\n      g.log(('mission: zone %s %s rooms=%s rect=%.1f,%.1f,%.1f,%.1f'):format(z.name,z.kind,\n        z.room or z.region or table.concat(z.rooms,','),b.left,b.right,b.bottom,b.top))\n    end\n    local m=c.membership\n    g.log('mission: zones membership room='..(m and m.room and m.room.id or 'none')..\n      ' transition='..(m and m.transition and m.transition.name or 'none')..\n      ' committed='..(m and m.committed and m.committed.id or 'none')..' outside='..tostring(m and m.outside or false))\n  end\n  return Z\nend\n", "@missions/zones.lua", "t"))()(missions)
missions.chunks = assert(load("-- Rectangles use half-open containment: the shared border belongs to the next chunk.\nreturn function(D)\n  local C={}\n  -- Predict one neighbouring window before a doorway, from committed membership.\n  function C.prefetch(s,p,c)\n    if not c or not p then return nil end\n    local old=s.last_point;s.last_point={x=p.x,y=p.y}\n    if not old then return nil end\n    local dx,dy=p.x-old.x,p.y-old.y;local b=c.rect\n    local w,h=b.right-b.left,b.top-b.bottom\n    local x,y=p.x,p.y\n    if math.abs(dx)>=math.abs(dy) and dx~=0 then\n      if dx>0 and b.right-p.x<=w*.5 then x=b.right+w*.5\n      elseif dx<0 and p.x-b.left<=w*.5 then x=b.left-w*.5 else return nil end\n    elseif dy~=0 then\n      if dy>0 and b.top-p.y<=h*.5 then y=b.top+h*.5\n      elseif dy<0 and p.y-b.bottom<=h*.5 then y=b.bottom-h*.5 else return nil end\n    else return nil end\n    return C.containing(s.doc.chunks,{x=x,y=y})\n  end\n  function C.containing(chunks,p)\n    if not p then return nil end\n    for _,c in ipairs(chunks) do\n      local b=c.rect\n      if p.x>=b.left and p.x<b.right and p.y>=b.bottom and p.y<b.top then return c end\n    end\n  end\n  function C.new(g,doc,prefix) return {g=g,doc=doc,prefix=prefix,loaded={},current=nil} end\n  function C.respawn(s,force)\n    local c=s.current\n    if c and (force or s.spawn~=c) then\n      assert(s.g.stage_set_spawn(D.mission.RESPAWN_SLOT,c.spawn.x,c.spawn.y))\n      s.spawn=c\n    end\n  end\n  function C.preload(s,target,player)\n    local previous=s.destination;s.destination=C.containing(s.doc.chunks,target)\n    local ok,why=C.update(s,player,s.membership)\n    if not ok then s.destination=previous end\n    return ok,why\n  end\n  function C.plan(doc,target,selected,zoned)\n    local centre;if zoned then centre=selected else centre=C.containing(doc.chunks,target)end;local out={}\n    if not centre then return out,nil end\n    local b=centre.rect;local w,h=b.right-b.left,b.top-b.bottom\n    for _,c in ipairs(doc.chunks) do\n      local r=c.rect\n      if r.left<b.right+w and r.right>b.left-w and r.bottom<b.top+h and r.top>b.bottom-h then out[#out+1]=c end\n    end\n    local function distance(c)\n      local r=c.rect;return ((r.left+r.right)/2-target.x)^2+((r.bottom+r.top)/2-target.y)^2\n    end\n    table.sort(out,function(a,b)local x,y=distance(a),distance(b);if x==y then return a.id<b.id end;return x<y end)\n    return out,centre\n  end\n  function C.update(s,p,...)\n    local membership=select(1,...)\n    local c=membership and membership.committed or s.current\n    if not membership then\n      local holder={doc=s.doc,stream=s,zone_state=s.zone_state,membership=s.membership}\n      membership=D.zones.sample(s.g,holder,p,(s.zone_frame or 0)+1)\n      s.zone_state=holder.zone_state;s.zone_frame=membership.frame;c=membership.committed\n    end\n    if not c and not s.destination then return true end\n    local arrived=c and s.destination==c\n    local wanted={}\n    local function window(center)\n      if not center then return end\n      local b=center.rect;local w,h=b.right-b.left,b.top-b.bottom\n      for _,v in ipairs(s.doc.chunks) do\n      local r=v.rect\n      if r.left<b.right+w and r.right>b.left-w and r.bottom<b.top+h and r.top>b.bottom-h then wanted[v.id]=v end\n      end\n    end\n    window(c);if not arrived then window(s.destination) end\n    local ahead=C.prefetch(s,p,c);if not s.destination then window(ahead)end\n    -- Build one missing area per observation tick. Keep the old window and spawn\n    -- while the requested window fills. Commit only a room with installed collision.\n    if c and s.current~=c then\n      local ok,why=pcall(function()assert(s.g.stage_set_spawn(D.mission.RESPAWN_SLOT,c.spawn.x,c.spawn.y))end)\n      if not ok then D.zones.reject(s,membership);return nil,why end\n    end\n    local missing,best\n    for _,v in pairs(wanted)do if not s.loaded[v.id]then\n      local b=v.rect;local d=((b.left+b.right)/2-p.x)^2+((b.bottom+b.top)/2-p.y)^2\n      if not best or d<best or (d==best and v.id<missing.id)then missing=v;best=d end\n    end end\n    if s.destination and not s.loaded[s.destination.id]then missing=s.destination end\n    if c and not s.loaded[c.id]then missing=c end\n    if missing then\n      local frame=membership.frame\n      if frame and (s.load_frame==frame or s.wave_frame==frame) then s.pending=true;D.zones.reject(s,membership);return true end\n      s.load_frame=frame\n      local t=s.g.time()\n      local ok,area=pcall(D.world.load,s.g,s.prefix..missing.serial,missing.level)\n      if not ok then\n        if s.current then s.g.stage_set_spawn(D.mission.RESPAWN_SLOT,s.current.spawn.x,s.current.spawn.y)end\n        D.zones.reject(s,membership);return nil,area\n      end\n      s.loaded[missing.id]=area\n      s.g.log(('mission: chunk load %s seconds=%.6f'):format(missing.id,s.g.time()-t))\n\n    end\n    if c and not s.loaded[c.id]then\n      s.pending=true\n      if s.current then s.g.stage_set_spawn(D.mission.RESPAWN_SLOT,s.current.spawn.x,s.current.spawn.y)end\n      D.zones.reject(s,membership);return true\n    end\n    local pending=false\n    for id in pairs(wanted)do if not s.loaded[id]then pending=true end end\n    s.pending=pending\n    if not pending and not missing and s.load_frame~=membership.frame and s.wave_frame~=membership.frame then\n      local id;for key in pairs(s.loaded)do if not wanted[key]and(not id or key<id)then id=key end end\n      if id then s.load_frame=membership.frame;D.world.unload(s.g,s.loaded[id]);s.loaded[id]=nil;s.g.log('mission: chunk unload '..id)end\n    end\n    if c and s.current~=c then\n      s.current=c;s.spawn=c\n      s.g.log(('mission: chunk spawn %s %.1f %.1f player=%.1f,%.1f'):format(c.id,c.spawn.x,c.spawn.y,p.x,p.y))\n    end\n    if arrived then s.destination=nil end\n    return true\n  end\n  function C.stop(s)\n    for id,a in pairs(s.loaded) do D.world.unload(s.g,a);s.loaded[id]=nil end\n  end\n  return C\nend\n", "@missions/chunks.lua", "t"))()(missions)
missions.glue = assert(load("-- Engine observations/actions around the unchanged pure mission machine.\nreturn function(D)\n  local M,G=D.mission,{}\n  function G.markers(doc)\n    local m,out=doc.mission,{}\n    local function add(name,p,kind,index) out[#out+1]={name=name,x=p.x,y=p.y,kind=kind,index=index} end\n    add('start',m.start,'start')\n    for i,e in ipairs(m.enemies) do add('enemy'..i,e,'enemy',i) end\n    for i,p in ipairs(m.checkpoints) do add('checkpoint'..i,p,'checkpoint',i) end\n    for i,p in ipairs(m.triggers) do add('trigger'..i,p,'trigger',i) end\n    if m.goal then add('goal',m.goal,'goal') end\n    for _,p in ipairs(doc.level.markers) do\n      local replaced=false\n      for i,old in ipairs(out) do if old.name==p.name then out[i]=p;replaced=true;break end end\n      if not replaced then out[#out+1]=p end\n    end\n    local direction=m.goal and m.goal.x<m.start.x and -1 or 1\n    table.sort(out,function(a,b)\n      if a.kind=='start' then return b.kind~='start' end\n      if b.kind=='start' then return false end\n      if a.x~=b.x then return a.x*direction<b.x*direction end\n      if a.y~=b.y then return a.y<b.y end\n      return a.name<b.name\n    end)\n    return out\n  end\n  function G.marker(doc,name)\n    for _,p in ipairs(G.markers(doc)) do if p.name==name then return p end end\n    error('unknown marker: '..tostring(name),0)\n  end\n  function G.new(doc,marker)\n    local normalized=M.validate(doc.mission)\n    local st=M.new(normalized)\n    local run={state=st,frames=0,last={},falls=0,message=nil,handles={},damaged={}}\n    if marker and marker~='start' then\n      local target=G.marker(doc,marker)\n      local visited,waves={},{}\n      for _,p in ipairs(G.markers(doc)) do\n        if p.name==target.name then break end\n        visited[p.name]=true\n      end\n      for i,e in ipairs(doc.mission.enemies) do\n        waves[e.wave]=waves[e.wave]~=false and visited['enemy'..i]==true\n      end\n      if target.authored then\n        waves={};for _,w in ipairs(target.cleared_waves) do waves[w]=true end\n        run.frames=target.frames\n      end\n      for w,done in pairs(waves) do if done then st.begun[w]=true;st.nbegun=st.nbegun+1 end end\n      for _,e in ipairs(doc.mission.enemies) do if st.begun[e.wave] then st.defeated=st.defeated+1 end end\n      for _,p in ipairs(G.markers(doc)) do\n        if p.kind=='checkpoint' and (visited[p.name] or p.name==target.name) then st.cp=p.index end\n        if p.kind=='trigger' and visited[p.name] then st.fired[p.index]=true end\n      end\n      if target.authored then st.cp=target.checkpoint end\n      st.started=true;st.cleared=st.nbegun==#st.waves\n      run.respawn=st.cp and doc.mission.checkpoints[st.cp] or target\n    end\n    return run\n  end\n  function G.cleanup(g,run)\n    for h in pairs(run.handles) do pcall(g.enemy_remove,h) end\n    run.handles={};run.damaged={};run.spawn_queue={};run.collision_queue={}\n    run.state.tracked={}\n  end\n  function G.step(g,current,player)\n    local run= current.run\n    local st=run.state\n    local p=player or (current.membership and current.membership.point) or g.player(1)\n    run.observation={player=p,zones=current.membership} -- shared trigger/contact trace reference\n    local alive,defeated={},{}\n    for h in pairs(st.tracked) do\n      local status=g.enemy_status(h)\n      if status=='alive' then\n        alive[h]=true;local e=g.enemy_state(h);run.last[h]=e\n        if e and (e.received or 0)>0 and e.last_attacker==1 then run.damaged[h]=true end\n      elseif status=='defeated' then defeated[h]=true\n      else\n        local at,b=run.last[h],current.doc.level.blast\n        local near=at and b and (at.x<=b.left+30 or at.x>=b.right-30 or at.y<=b.bottom+30 or at.y>=b.top-30)\n        if not near or run.damaged[h] then defeated[h]=true end\n      end\n    end\n    run.falls=p and p.falls or run.falls\n    if D.maze_encounters then D.maze_encounters.observe(current)end\n    local actions,events=M.step(st,{frames=run.frames,player=p,falls=run.falls or 0,alive=alive,defeated=defeated})\n    if st.result and not run.terminal_logged then\n      local text=st.result.status\n      if text=='failed'then text='failed reason='..tostring(st.result.reason)..' '..tostring(st.result.detail or '')end\n      g.log('mission: '..text);run.terminal_logged=true\n    end\n    if D.maze_encounters and current.doc.maze then\n      for _,a in ipairs(run.spawn_queue or{})do actions[#actions+1]=a end\n      run.spawn_queue={};actions=D.maze_encounters.actions(current,actions)\n    end\n    run.spawn_queue=run.spawn_queue or {}\n    local immediate={}\n    for _,a in ipairs(actions)do if a.type=='spawn'then run.spawn_queue[#run.spawn_queue+1]=a else immediate[#immediate+1]=a end end\n    actions=immediate\n    if st.result then run.spawn_queue={}end\n    local frame=current.membership and current.membership.frame or run.frames\n    local committed=current.membership and current.membership.committed\n    local safe_room=not committed or current.stream.loaded[committed.id]\n    local live=0;for _ in pairs(st.tracked)do live=live+1 end\n    if live<M.LIMITS.per_wave and safe_room and not current.stream.pending and current.stream.load_frame~=frame and #run.spawn_queue>0 then\n      actions[#actions+1]=table.remove(run.spawn_queue,1);run.execute_spawn=actions[#actions]\n    else run.execute_spawn=nil end\n    for _,a in ipairs(actions) do\n      if a.type=='spawn' and a==run.execute_spawn then\n        current.stream.wave_frame=frame\n        local ok,h,why=pcall(g.spawn_enemy,a.kind,a.x,a.y,{facing=a.facing})\n        if ok and h then run.handles[h]=true;M.spawned(st,a.index,h)\n        else M.spawn_failed(st,a.index,ok and why or h) end\n      elseif a.type=='respawn_point' then\n        if current.stream.current then D.chunks.respawn(current.stream)\n        else assert(g.stage_set_spawn(M.RESPAWN_SLOT,a.x,a.y)) end\n      elseif a.type=='collision' then\n        local areas={current.root}\n        for _,area in pairs(current.stream.loaded) do areas[#areas+1]=area end\n        run.collision_queue=run.collision_queue or{}\n        run.collision_queue[#run.collision_queue+1]={areas=areas,action=a}\n      elseif a.type=='cleanup' then G.cleanup(g,run) end\n    end\n    if not st.result and not current.stream.pending and current.stream.load_frame~=frame and current.stream.wave_frame~=frame then\n      local job=run.collision_queue and run.collision_queue[1]\n      if job then\n        local done,changed=D.world.collision_tick(g,current,job)\n        if changed then current.stream.load_frame=frame end\n        if done then table.remove(run.collision_queue,1)end\n      end\n    end\n    for _,e in ipairs(events) do\n      local text=e.type\n      if e.type=='wave' then text=('wave %d of %d'):format(e.n,e.of)\n      elseif e.type=='checkpoint' then text='checkpoint '..e.index\n      elseif e.type=='message' then run.message={text=e.text,left=M.MESSAGE_FRAMES};text='message '..e.text\n      elseif e.type=='defeat' then text='defeated '..e.kind\n      elseif e.type=='vanish' then text='lost '..e.kind..' (not a defeat)'\n      elseif e.type=='failed' then text='failed reason='..tostring(e.reason)..' '..tostring(e.detail or '') end\n      if e.type~='complete' and e.type~='failed' then g.log('mission: '..text)end\n    end\n    if run.message then run.message.left=run.message.left-1;if run.message.left<=0 then run.message=nil end end\n  end\n  return G\nend\n", "@missions/glue.lua", "t"))()(missions)
missions.fighters = assert(load("-- CPU ports are level guests; humans retain their controller and placement.\nreturn function(D)\n  local F={}\n  function F.ready(p)\n    if not p then return false end\n    local a=p.action\n    -- Public common motion IDs; mirror Geno fly's dead/held/throw ranges.\n    return a==nil or (a>13 and a~=42 and a~=43 and not (a>=223 and a<=232) and not (a>=239 and a<=243) and not (a>=266 and a<=339))\n  end\n  function F.stage_ready(g)\n    if not F.ready(g.player(1))then return false end\n    if g.fighter_benched then\n      local held,entities=g.fighter_benched(1)\n      if held then return false end\n      for _,e in ipairs(entities or {})do\n        if e.present and (e.refusal_code or 0)~=0 then return false end\n      end\n    end\n    return true\n  end\n  function F.transient(why)\n    local s=tostring(why)\n    return s:find('state cannot fly',1,true) or s:find('respawning',1,true) or s:find('dead fighter',1,true)\n  end\n  function F.tick(g,c)\n    c.fighters=c.fighters or {}\n    local at=c.stream.current and c.stream.current.spawn or c.run.respawn or c.doc.mission.start\n    for port=2,6 do\n      local p=g.player(port);local old=c.fighters[port]\n      if p and p.cpu then\n        local mode=c.doc.level.fighters[port] or 'stand'\n        if not old or old.kind~=p.kind or old.char~=p.char then\n          old={kind=p.kind,char=p.char,original={x=p.x,y=p.y}};c.fighters[port]=old\n        end\n        if old.mode~=mode or old.falls~=p.falls then\n          old.mode=mode;old.falls=p.falls;old.ticks=0;old.configured=nil;old.at=nil\n        end\n        old.ticks=(old.ticks or 0)+1\n        local benched=g.fighter_benched and g.fighter_benched(port)\n        if old.owned and not benched then old.owned=nil;old.configured=nil end\n        if mode=='fight' then\n          if old.owned then\n            local ok,called=pcall(g.fighter_call,port,at.x,at.y,{intangible_frames=0})\n            if ok and called then old.owned=nil;old.configured=nil;benched=false end\n          end\n          if not old.owned and not benched and not old.configured and g.cpu_mode then\n            local ok,accepted=pcall(g.cpu_mode,port,'fight')\n            if ok and accepted then old.configured=true end\n          end\n        elseif not old.owned and not benched then\n          if g.fighter_bench and (old.ticks-1)%30==0 then\n            local ok,accepted,why=pcall(g.fighter_bench,port)\n            if ok and accepted then old.owned=true;old.refusal=nil;g.log('mission: CPU '..port..' benched') end\n          end\n          if not old.owned and F.ready(p) and (old.ticks-1)%6==0 then\n            local ok=pcall(function()\n              if not old.configured and g.cpu_mode then\n                assert(g.cpu_mode(port,'stand'),'CPU stand refused');old.configured=true;old.fallback=true\n              end\n              if old.at~=at then g.teleport(port,at.x,at.y);old.at=at end\n            end)\n            if not ok then old.at=nil end\n          end\n        end\n      else c.fighters[port]=nil end\n    end\n  end\n  function F.guard(g,state)\n    state.ticks=(state.ticks or 0)+1;state.fighters=state.fighters or {};local safe=true\n    for port=2,6 do\n      local p=g.player(port)\n      if p and p.cpu and not (g.fighter_benched and g.fighter_benched(port)) then\n        local old=state.fighters[port] or {kind=p.kind,char=p.char,original={x=p.x,y=p.y}}\n        state.fighters[port]=old\n        if g.cpu_mode and not old.stood then\n          local ok,accepted=pcall(g.cpu_mode,port,'stand');old.stood=ok and accepted;old.fallback=old.stood\n        end\n        if g.fighter_bench and (state.ticks-1)%30==0 then\n          local ok,accepted=pcall(g.fighter_bench,port)\n          if ok and accepted then old.owned=true;g.log('mission: CPU '..port..' benched') end\n        end\n        if not old.owned then safe=false end\n      end\n    end\n    return safe\n  end\n  function F.prepare(g,c)\n    -- Reserve every CPU before loading collision; unsafe reserves defer the whole load.\n    c.fighters=c.fighters or {}\n    for port=2,6 do\n      local p=g.player(port)\n      if p and p.cpu and not (g.fighter_benched and g.fighter_benched(port)) then\n        assert(g.fighter_bench,'mission load requires fighter_bench for CPU safety')\n        local ok,accepted=pcall(g.fighter_bench,port)\n        if not ok or not accepted then error('respawning or unsafe CPU '..port..': waiting for bench before mission load') end\n        local old=c.fighters[port] or {kind=p.kind,char=p.char,original={x=p.x,y=p.y}}\n        old.owned=true;c.fighters[port]=old;g.log('mission: CPU '..port..' benched')\n      end\n    end\n  end\n  function F.stop(g,c)\n    for port,old in pairs(c and c.fighters or {}) do\n      if old.owned and g.fighter_call then\n        local at=old.original\n        local ok,called=pcall(g.fighter_call,port,at.x,at.y,{intangible_frames=0})\n        if not ok or not called then g.log('mission: CPU '..port..' reserve release refused') end\n      end\n      if old.fallback and g.cpu_mode then pcall(g.cpu_mode,port,'fight') end\n    end\n  end\n  return F\nend\n", "@missions/fighters.lua", "t"))()(missions)
missions.camera = assert(load("-- Standard native camera with Lua-owned origin interpolation and fixed world KO edges.\nreturn function(D)\n  local C={}\n  local EPS=0.01 -- game-unit tolerance exceeds native projection rounding jitter\n  local function near(a,b) return a~=nil and b~=nil and math.abs(a-b)<=EPS end\n  local function clamp(v,lo,hi)\n    if lo>hi then return (lo+hi)/2 end\n    return math.max(lo,math.min(hi,v))\n  end\n  local function leash(origin,target,size) return clamp(origin,target-size,target+size) end\n  function C.settings(c)\n    local settings={mode='follow'}\n    for k,v in pairs(c.doc.level.camera_settings or {}) do settings[k]=v end\n    local chunk=c.stream.current\n    for k,v in pairs(chunk and chunk.level.camera_settings or {}) do settings[k]=v end\n    return settings,chunk\n  end\n  function C.ends(c,config)\n    local ends=config.ends or c.doc.level.camera\n    if not ends and #c.doc.chunks>0 then\n      ends={left=math.huge,right=-math.huge,bottom=math.huge,top=-math.huge}\n      for _,v in ipairs(c.doc.chunks) do\n        ends.left=math.min(ends.left,v.rect.left);ends.right=math.max(ends.right,v.rect.right)\n        ends.bottom=math.min(ends.bottom,v.rect.bottom);ends.top=math.max(ends.top,v.rect.top)\n      end\n    end\n    return ends\n  end\n  function C.aspect(g,pose)\n    local area=g.safe_area and g.safe_area() or {w=640,h=480}\n    local aspect=area.w/area.h\n    if g.project and pose then\n      local e,t=pose.eye,pose.interest\n      local fx,fy,fz=t.x-e.x,t.y-e.y,t.z-e.z\n      local n=math.sqrt(fx*fx+fy*fy+fz*fz);local r=math.sqrt(fx*fx+fz*fz)\n      if n>0 and r>0 then\n        local rx,rz=-fz/r,fx/r\n        local ux,uy,uz=-rz*fy/n,(rz*fx-rx*fz)/n,rx*fy/n\n        local x,y=g.project(t.x,t.y,t.z)\n        local a,b=g.project(t.x+rx,t.y,t.z+rz)\n        local u,v=g.project(t.x+ux,t.y+uy,t.z+uz)\n        if x and a and u then\n          local horizontal=math.sqrt(((a-x)/area.w)^2+((u-x)/area.w)^2)\n          local vertical=math.sqrt(((b-y)/area.h)^2+((v-y)/area.h)^2)\n          if horizontal>0 and vertical>0 then aspect=vertical/horizontal end\n        end\n      end\n    end\n    assert(aspect>0 and aspect<100,'invalid live camera aspect')\n    return aspect,area\n  end\n  function C.footprint(g,pose,area)\n    if not g.project or not pose then return end\n    local cx,cy=pose.interest.x,pose.interest.y\n    local u,v,_,depth=g.project(cx,cy,0)\n    local ux,vx,_,dx=g.project(cx+1,cy,0)\n    local uy,vy,_,dy=g.project(cx,cy+1,0)\n    if not depth or not dx or not dy or depth<=0 then return end\n    -- Screen*depth and depth are affine on z=0: invert their exact homography.\n    local a0,b0=u*depth,v*depth\n    local a1,a2=ux*dx-a0,uy*dy-a0;local b1,b2=vx*dx-b0,vy*dy-b0\n    local d1,d2=dx-depth,dy-depth\n    local out={left=math.huge,right=-math.huge,bottom=math.huge,top=-math.huge}\n    for _,screen in ipairs({{0,0},{area.w,0},{area.w,area.h},{0,area.h}}) do\n      local x,y=screen[1],screen[2]\n      local A,B,Cc,Dd=a1-x*d1,a2-x*d2,b1-y*d1,b2-y*d2\n      local U,V=x*depth-a0,y*depth-b0;local det=A*Dd-B*Cc\n      if math.abs(det)<0.00000001 then return end\n      local wx,wy=cx+(U*Dd-B*V)/det,cy+(A*V-U*Cc)/det\n      out.left=math.min(out.left,wx);out.right=math.max(out.right,wx)\n      out.bottom=math.min(out.bottom,wy);out.top=math.max(out.top,wy)\n    end\n    return out\n  end\n  function C.release(g,force)\n    if C.cut_owned and (force or not g.frame or C.cut_frame~=g.frame()) then\n      g.camera_attach(0);C.cut_owned=nil;C.cut_frame=nil\n    end\n  end\n  function C.cut(g,pose)\n    assert(g.camera_set and g.camera_attach,'mission camera cut requires camera_set/camera_attach')\n    g.camera_set(pose);C.cut_owned=true;C.cut_frame=g.frame and g.frame()\n  end\n  function C.geometry(config,chunk,ends)\n    local mode=config.mode;local aspect=config.aspect or 16/9\n    local w,h=250,180\n    if mode=='shaft' then w,h=150,260\n    elseif mode=='chunk' then w,h=138,112 end -- 130x104 room plus 4 per side\n    if config.window then w,h=config.window.w,config.window.h end\n    if mode=='chunk' and chunk then\n      local b=chunk.rect;local margin=config.margin or 4\n      w=b.right-b.left+2*margin;h=b.top-b.bottom+2*margin\n    end\n    local fov=config.fov or config.tilt or (mode=='shaft' and 20 or 25)\n    local half=math.tan(math.rad(fov)/2)\n    -- Follow fits its desired window; rooms/shafts fit height, accepting neighbours.\n    local distance=h/(2*half)\n    if mode=='follow' then distance=math.min(distance,w/(2*aspect*half)) end\n    distance=config.min_dist or distance\n    local depth=config.max_depth or distance\n    assert(distance>=1 and depth>=distance and depth<=49000,'camera footprint cannot fit level at legal distance')\n    local params={min_dist=distance,max_depth=depth,fov=fov,fixed_zoom=config.fixed_zoom or 1,\n      yaw_gain=config.yaw_gain or 0,pitch_gain=config.pitch_gain or 0,pan=config.pan or 0,\n      track_smooth=config.track_smooth or 1.8,track_ratio=config.track_ratio or 1}\n    return params,2*depth*half*aspect,2*depth*half\n  end\n  function C.move(g,c,state,x,y)\n    if state.compensated and near(x,state.x) and near(y,state.y) then return end\n    local before=g.stage_bounds();local origin=before.origin or {x=state.x,y=state.y}\n    local blast=c.doc.level.blast or state.blast or before.blast\n    local ok,why=pcall(function()\n      -- No native tween: its intermediate origins cannot share our compensation.\n      assert(g.stage_set_origin(x,y,{frames=0}))\n      assert(g.stage_set_blast_bounds(blast.left-x,blast.right-x,blast.top-y,blast.bottom-y))\n    end)\n    if not ok then\n      pcall(g.stage_set_origin,origin.x,origin.y,{frames=0})\n      local b=before.blast\n      if b then pcall(g.stage_set_blast_bounds,b.left-origin.x,b.right-origin.x,b.top-origin.y,b.bottom-origin.y) end\n      error(why,0)\n    end\n    state.x=x;state.y=y;state.blast=blast;state.compensated=true\n  end\n  function C.tick(g,c,p)\n    assert(g.camera_params and g.stage_set_origin,'mission camera requires engine batch-2 camera APIs')\n    C.release(g) -- one native update has consumed the previous committed cut\n    local pose=g.camera_get and g.camera_get()\n    local aspect,area\n    if C.cut_owned then aspect=C.cached_aspect;area=g.safe_area()\n    else aspect,area=C.aspect(g,pose);C.cached_aspect=aspect end\n    local footprint=not C.cut_owned and C.footprint(g,pose,area)\n    local config,chunk=C.settings(c);local mode=config.mode;local membership=c.membership\n    if mode=='chunk' and membership and membership.outside then mode='follow';config.mode='chunk';config.look_ahead=0;config.velocity_lead=0 end\n    config.aspect=aspect\n    local ends=C.ends(c,config);local params,w,h=C.geometry(config,chunk,ends)\n    local state=c.camera\n    if not state then\n      local origin=g.stage_bounds().origin or {x=0,y=0}\n      state={x=origin.x,y=origin.y};c.camera=state\n    end\n    if state.aspect and math.abs(aspect-state.aspect)<=0.0001 then\n      config.aspect=state.aspect;params,w,h=C.geometry(config,chunk,ends)\n    else state.aspect=aspect end\n    local changed=state.mode~=mode or not near(state.w,w) or not near(state.h,h)\n    local params_changed=not state.params\n    for k,v in pairs(params) do if not state.params or not near(state.params[k],v) then params_changed=true end end\n    changed=changed or params_changed\n    if changed then\n      if params_changed then g.camera_params(params) end\n      -- A tiny target rectangle centres the retail frustum, independent of its aspect.\n      if not state.started then assert(g.stage_set_camera_bounds(-0.5,0.5,0.5,-0.5)) end\n      state.mode=mode;state.w=w;state.h=h;state.params=params\n    end\n    local action=p and p.action;local falls=p and p.falls\n    local respawning=not p or (action and action<=13)\n    if not p or (action and action<12) then\n      local at=chunk and chunk.spawn or c.run.respawn or c.doc.mission.start\n      p={x=at.x,y=at.y}\n    end\n    local vx,vy=p.vx or 0,p.vy or 0\n    local direction=vx~=0 and (vx>0 and 1 or -1) or (p.facing or 0)\n    local lead=clamp(direction*(config.look_ahead or 18)+vx*(config.velocity_lead or 6),\n      -(config.max_lead or 40),config.max_lead or 40)\n    local vertical=clamp(vy*(config.vertical_lead or (mode=='shaft' and 6 or 3)),\n      -(config.vertical_max or (mode=='shaft' and 48 or 24)),config.vertical_max or (mode=='shaft' and 48 or 24))\n    if respawning then lead,vertical=0,0 end\n    local event=not state.started or (respawning and not state.respawning) or\n      (falls~=nil and state.falls~=nil and falls~=state.falls and not state.respawning) or\n      (state.px and (math.abs(p.x-state.px)>w or math.abs(p.y-state.py)>h))\n    if membership and (membership.outside or state.outside)then event=false end\n    local returning=membership and state.outside and not membership.outside\n    state.outside=membership and membership.outside\n    local snap=event or respawning\n    state.respawning=respawning;state.falls=falls or state.falls;state.px=p.x;state.py=p.y\n    local x,y\n    if mode=='chunk' and chunk then\n      local b=chunk.rect;local tx,ty=(b.left+b.right)/2,(b.bottom+b.top)/2\n      local tuning=membership and membership.tuning or D.zones.defaults\n      if state.room~=chunk then\n        state.room=chunk;state.tx=tx;state.ty=ty;state.ease={x=state.x,y=state.y,age=0,frames=tuning.ease_frames,curve=tuning.curve}\n      end\n      local ease=state.ease\n      if snap and not (membership and membership.outside)then x,y=tx,ty;state.ease=nil\n      elseif ease then\n        ease.age=math.min(ease.frames,ease.age+1);local t=ease.age/ease.frames\n        if ease.curve=='smoothstep' then t=t*t*(3-2*t)end\n        x=ease.x+(tx-ease.x)*t;y=ease.y+(ty-ease.y)*t\n        if ease.age==ease.frames then state.ease=nil end\n      else x,y=tx,ty end\n      if membership and membership.transition then\n        -- Preserve the current framing unless visibility requires a small shift.\n        local door=membership.transition;local loX,hiX,loY,hiY=tx,tx,ty,ty\n        for _,id in ipairs(door.rooms)do local room=c.doc.zone_data.chunks[id];local r=room.rect\n          loX=math.min(loX,(r.left+r.right)/2);hiX=math.max(hiX,(r.left+r.right)/2)\n          loY=math.min(loY,(r.bottom+r.top)/2);hiY=math.max(hiY,(r.bottom+r.top)/2)\n        end\n        local safe=math.min(tuning.doorway_margin,w/4,h/4)\n        x=clamp(ease and x or state.x,p.x-w/2+safe,p.x+w/2-safe);y=clamp(ease and y or state.y,p.y-h/2+safe,p.y+h/2-safe)\n        x=clamp(x,loX,hiX);y=clamp(y,loY,hiY)\n      end\n    else\n      local lx=config.leash or 10;local ly=config.vertical_leash or (mode=='shaft' and 4 or lx)\n      x=snap and p.x+lead or leash(state.x,p.x+lead,lx)\n      y=snap and p.y+vertical or leash(state.y,p.y+vertical,ly)\n      if mode=='shaft' then x=config.x or (chunk and (chunk.rect.left+chunk.rect.right)/2) or 0 end\n    end\n    local safe=math.min(config.safe_margin or 12,w/4,h/4)\n    if mode~='shaft' then x=clamp(x,p.x-w/2+safe,p.x+w/2-safe) end\n    y=clamp(y,p.y-h/2+safe,p.y+h/2-safe)\n    if ends then\n      x=clamp(x,ends.left+w/2,ends.right-w/2)\n      y=clamp(y,ends.bottom+h/2,ends.top-h/2)\n    end\n    if membership and membership.outside then\n      -- Bounded follow even after a debug teleport: no out-of-zone camera cut.\n      x=clamp(x,state.x-12,state.x+12);y=clamp(y,state.y-12,state.y+12)\n    end\n    local moved=not near(x,state.x) or not near(y,state.y)\n    C.move(g,c,state,x,y);state.started=true\n    if pose and event and (math.abs(pose.interest.x-x)>w or math.abs(pose.interest.y-y)>h) then\n      C.cut(g,{eye={x=x,y=y,z=params.min_dist},interest={x=x,y=y,z=0},fov=params.fov,roll=0})\n    elseif footprint and ends and not returning and not (membership and membership.outside) and (event or moved or changed) then\n      local fw,fh=footprint.right-footprint.left,footprint.top-footprint.bottom\n      local cx,cy=(footprint.left+footprint.right)/2,(footprint.bottom+footprint.top)/2\n      local dx=clamp(cx,ends.left+fw/2,ends.right-fw/2)-cx\n      local dy=clamp(cy,ends.bottom+fh/2,ends.top-fh/2)-cy\n      if math.abs(dx)>EPS or math.abs(dy)>EPS then\n        local e,t=pose.eye,pose.interest\n        C.cut(g,{eye={x=e.x+dx,y=e.y+dy,z=e.z},interest={x=t.x+dx,y=t.y+dy,z=t.z},fov=pose.fov,roll=pose.roll or 0})\n      end\n    end\n  end\n  function C.stop(g) if C.cut_owned then pcall(C.release,g,true) end;if g.camera_params then pcall(g.camera_params,nil) end end\n  return C\nend\n", "@missions/camera.lua", "t"))()(missions)
missions.maze_commands = assert(load("-- Small mission extension: keep generated geometry on the standard loader path.\nreturn function(D)\n  local C={}\n  function C.settle(r)\n    local t=r.maze_pending;if not t or r.staging then return end\n    if r.last_install_error then\n      D.loader.generated[t.next.folder]=t.previous;r.maze_pending=nil\n    elseif r.current and r.current.doc.folder==t.next.folder then\n      if t.old and t.old.folder~=t.next.folder then D.loader.generated[t.old.folder]=nil end\n      r.maze=t.next;r.maze_pending=nil;r.g.log(D.maze.ascii(t.next.output))\n    else D.loader.generated[t.next.folder]=t.previous;r.maze_pending=nil\n    end\n  end\n  function C.dispatch(r,words)\n    assert(D.maze and D.maze_check,'maze modules missing from bundle')\n    if words[2]=='map' then\n      assert(#words==2 and r.maze,'usage: mission maze map (after generation)')\n      r.g.log(D.maze.ascii(r.maze.output));return\n    end\n    local seed,size\n    if words[2]=='reroll' then\n      assert(#words==2 and r.maze,'usage: mission maze reroll (after generation)')\n      seed=(r.maze.seed+1)%2147483647;size=r.maze.size\n    else\n      assert(#words==2 or #words==3,'usage: mission maze <seed> [size]')\n      seed=tonumber(words[2]);size=words[3] and assert(tonumber(words[3]),'invalid size') or 12\n    end\n    local templates=D.loader.data(r.g,'missions/maze-chunks/library.lua',true)\n    local output=D.maze.generate(seed,{size=size,templates=templates})\n    local name='maze_'..seed..'_'..size;local folder='missions/'..name..'/'\n    local catalogue=D.loader.catalogue(r.g,'missions/')\n    assert(catalogue[D.maze_set.part],'maze kit missing; run tools/maze/generate.py --prepare-mod --kit <room-kit>')\n    local previous=D.loader.generated[folder]\n    D.loader.generated[folder]={files=D.maze.files(output,name),catalogue=catalogue,\n      stamp=(previous and previous.stamp or 0)+1}\n    local ok,why=pcall(r.install,r,name,nil,false)\n    if not ok then D.loader.generated[folder]=previous;error(why,0) end\n    local next_maze={seed=seed,size=size,output=output,folder=folder}\n    if r.staging then r.maze_pending={old=r.maze,next=next_maze,previous=previous}\n    else\n      if r.maze and r.maze.folder~=folder then D.loader.generated[r.maze.folder]=nil end\n      r.maze=next_maze;r.g.log(D.maze.ascii(output))\n    end\n  end\n  return C\nend\n", "@missions/maze_commands.lua", "t"))()(missions)
missions.maze_rewards = assert(load("-- Maze-only reward policy; the shared mission state machine remains unchanged.\nreturn function(D)\n  local R={}\n  function R.tick(g,c)\n    local maze=c.doc.maze;if not maze then return end\n    local p=c.membership and c.membership.point or g.player(1);if not D.fighters.ready(p) then return end\n    c.maze_rewards=c.maze_rewards or {}\n    for _,cell in ipairs(maze.cells) do\n      if cell.reward and not c.maze_rewards[cell.id] and\n        math.abs(p.x-(cell.x*130+20))<=12 and math.abs(p.y-(cell.y*104+12))<=16 then\n        local percent=math.max(0,math.floor(p.percent or 0)-(cell.reward_amount or 25))\n        -- The native setter returns zero values. Verify synchronous readback;\n        -- treating nil as refusal repeatedly reapplied an unconsumed cache.\n        if math.abs((p.percent or 0)-percent)>0.01 then g.set_damage(1,percent) end\n        local live=g.player(1)\n        if live and math.abs((live.percent or 0)-percent)<=0.01 then\n          c.maze_rewards[cell.id]=true\n          g.log('mission: maze reward '..cell.id..' heal '..(cell.reward_amount or 25))\n        end\n      end\n    end\n  end\n  return R\nend\n", "@missions/maze_rewards.lua", "t"))()(missions)
missions.world_commands = assert(load("-- Generate/validate incrementally, then hand one continuous world to staged install.\nreturn function(D)\n  local C={}\n  function C.cancel(r)\n    local t=r.world_generation\n    if t then D.loader.generated[t.folder]=t.previous;r.world_generation=nil end\n  end\n  function C.settle(r)\n    local t=r.world_pending;if not t or r.staging then return end\n    if not r.last_install_error and r.current and r.current.doc.folder==t.next.folder then\n      if t.old and t.old.folder~=t.next.folder then D.loader.generated[t.old.folder]=nil end\n      if r.maze then D.loader.generated[r.maze.folder]=nil;r.maze=nil end\n      r.world=t.next;r.world_pending=nil;r.g.log(D.maze_world.ascii(t.next.output))\n    else D.loader.generated[t.next.folder]=t.previous;r.world_pending=nil end\n  end\n  function C.dispatch(r,words)\n    if words[2]=='map'then assert(#words==2 and r.world,'mission world map requires a world');r.g.log(D.maze_world.ascii(r.world.output));return end\n    local seed,regions,size\n    if words[2]=='reroll'then assert(#words==2 and r.world,'mission world reroll requires a world');seed=(r.world.seed+1)%2147483647;regions=r.world.regions;size=r.world.size\n    else assert(#words>=2 and #words<=4,'usage: mission world <seed> [regions] [size]');seed=assert(tonumber(words[2]),'invalid world seed');regions=words[3]and assert(tonumber(words[3]))or 4;size=words[4]and assert(tonumber(words[4]))or 12 end\n    assert(seed%1==0 and math.abs(seed)<=2147483646 and regions%1==0 and regions>=2 and regions<=6 and size%1==0 and size>=8 and size<=20,'invalid world seed/regions/size')\n    assert(r.g.match().active and not r.g.match().netplay,'active offline match required')\n    assert(not r.world_generation,'world generation already running')\n    local templates=D.loader.data(r.g,'missions/maze-chunks/library.lua',true)\n    local catalogue=D.loader.catalogue(r.g,'missions/')\n    local name='world_'..seed..'_'..regions..'_'..size;local folder='missions/'..name..'/'\n    local t={folder=folder,previous=D.loader.generated[folder],frames=0,phase='regions'}\n    local counts={}\n    local function work(label)\n      counts[label]=(counts[label]or 0)+1\n      local batch=label=='encode'and 64 or label=='route'and 2 or label=='partition'and 2 or\n        (label=='graph proof'or label=='normalize zone'or label=='normalize marker'or label=='zone membership'or label=='geometry'or label=='region geometry'or label=='metadata'or label=='connector chunk'or label=='clearance'or label=='check child'or label=='validate child')and 8 or 1\n      if counts[label]%batch==0 then coroutine.yield(label)end\n    end\n    t.co=coroutine.create(function()\n      local output=D.maze_world.generate(seed,{regions=regions,size=size,templates=templates,work=work})\n      local files=D.maze.files(output,name,work)\n      D.loader.generated[folder]={files=files,catalogue=catalogue,stamp=(t.previous and t.previous.stamp or 0)+1}\n      local doc=D.loader.folder(r.g,name,work);D.loader.generated[folder].doc=doc\n      t.next={seed=seed,regions=regions,size=size,output=output,folder=folder};t.name=name\n    end)\n    if r.current then D.commands.cancel(r);r.current.stream.destination=nil end\n    r.world_generation=t;r.g.log('mission: world generating '..name)\n  end\n  function C.tick(r)\n    local t=r.world_generation;if not t then return end;t.frames=t.frames+1\n    if coroutine.status(t.co)~='dead'then\n      local ok,phase=coroutine.resume(t.co)\n      if not ok then C.cancel(r);r.g.log('mission: world refused '..tostring(phase));return end\n      t.phase=phase or 'install'\n      if t.frames%60==0 then r.g.log('mission: world generating '..t.phase)end\n      return\n    end\n    if not D.fighters.stage_ready(r.g)then\n      t.wait=(t.wait or 0)+1;if t.wait>=600 then C.cancel(r);r.g.log('mission: world timed out waiting for reserve-ready P1')end;return\n    end\n    local ok,why=pcall(r.install,r,t.name,nil,false)\n    if not ok then C.cancel(r);r.g.log('mission: world install refused '..tostring(why));return end\n    r.world_generation=nil;r.world_pending={old=r.world,next=t.next,previous=t.previous}\n    C.settle(r)\n  end\n  return C\nend\n", "@missions/world_commands.lua", "t"))()(missions)
missions.commands = assert(load("-- Fly operations are fixtures, never traversal verdicts.\nreturn function(D)\n  local C={}\n  C.TARGET_LIMIT=1500\n  function C.cancel(r)\n    local c,g=r.current,r.g\n    local clear=c and c.clear\n    if clear and clear.deadline and g.deadline_done then pcall(g.deadline_done,clear.deadline) end\n    if c then c.clear=nil;c.pending_visit=nil;c.visit_frames=nil end\n    if g.fly_clear then pcall(g.fly_clear,1) else pcall(g.fly_attack,1,false);pcall(g.fly,1,false) end\n  end\n  function C.target(g,p,control,frame)\n    if control then\n      local previous=control.target\n      if g.fly(1) and previous and math.abs(previous.x-p.x)<1 and math.abs(previous.y-p.y)<1 then return true end\n      if control.last_frame and frame-control.last_frame<6 then return false end\n      control.last_frame=frame\n    end\n    if math.abs(p.x)>10000 or math.abs(p.y)>10000 then\n      assert(math.abs(p.x)<50000 and math.abs(p.y)<50000,'target exceeds native coordinate limit')\n      g.fly(1,true);g.teleport(1,p.x,p.y)\n      g.log('mission: long range teleport fixture')\n    else g.fly_target(1,p.x,p.y) end\n    if control then control.target={x=p.x,y=p.y} end\n    return true\n  end\n  function C.visit(r,p)\n    local c,g=r.current,r.g\n    local ok,why=D.chunks.preload(c.stream,p,g.player(1))\n    assert(ok,why)\n    local destination=D.chunks.containing(c.doc.chunks,p)\n    if destination and (not c.stream.loaded[destination.id] or c.stream.pending)then c.pending_visit=p;return end\n    c.pending_visit=p\n    C.target(g,p)\n    c.pending_visit=nil;c.visit_frames=nil\n    g.log(('mission: fly %s %.1f %.1f'):format(p.name,p.x,p.y))\n  end\n  function C.fly(r,name)\n    C.cancel(r);r.current.tour=nil\n    local markers=D.glue.markers(r.current.doc)\n    local index=r.current.cursor or 0\n    if name=='next' then index=index%#markers+1\n    elseif name=='prev' then index=(index-2)%#markers+1\n    else\n      index=nil\n      for i,p in ipairs(markers) do if p.name==name then index=i end end\n      assert(index,'unknown marker: '..tostring(name))\n    end\n    C.visit(r,markers[index]);r.current.cursor=index\n  end\n  function C.tour(r)\n    local queue=D.glue.markers(r.current.doc)\n    for _,c in ipairs(r.current.doc.chunks) do\n      queue[#queue+1]={name='chunk:'..c.id,x=c.spawn.x,y=c.spawn.y}\n    end\n    r.current.tour={queue=queue,index=1,started=r.g.time(),sent=false,frames=0}\n  end\n  function C.tick(r)\n    local c,g=r.current,r.g\n    if c.pending_visit then\n      c.visit_frames=(c.visit_frames or 0)+1\n      local ok,why=true,nil\n      if not c.stream.pending then ok,why=pcall(C.visit,r,c.pending_visit)end\n      if c.visit_frames and c.visit_frames>=600 then ok,why=false,'queued fly timed out'end\n      if not ok and not D.fighters.transient(why)then\n        c.pending_visit=nil;c.visit_frames=nil\n        if c.tour then c.tour.refusal=tostring(why)end\n        g.log('mission: queued fly refused '..tostring(why))\n      end\n    end\n    if c.clear then\n      local clear=c.clear\n      clear.elapsed=clear.elapsed+1\n      local function finish(text)C.cancel(r);g.log('mission: '..text)end\n      if clear.elapsed>=clear.limit then finish('clear whole-command timeout');return end\n      while clear.handles[clear.index] and g.enemy_status(clear.handles[clear.index])~='alive' do\n        clear.index=clear.index+1;clear.target_h=nil\n      end\n      local h=clear.handles[clear.index]\n      if not h then finish('clear complete');return end\n      if clear.target_h~=h then\n        clear.target_h=h;clear.age=0;clear.pulse=0;clear.target=nil;clear.last_frame=nil\n      end\n      local e=g.enemy_state(h)\n      if clear.age>=C.TARGET_LIMIT then\n        finish(('clear: %s not defeated after %d frames (state %s, vulnerable=%s)'):format(\n          e and e.kind or 'unknown',clear.age,tostring(e and e.state),tostring(e and e.vulnerable)))\n        return\n      end\n      local player=c.membership and c.membership.point or g.player(1)\n      local attacking=clear.pulse%40<28 -- leave 12 frames for hitlag/death logic\n      local flight=g.fly_state and g.fly_state(1)\n      local changed=clear.falls~=(player or {}).falls or not g.fly(1)\n        or (flight and flight.attacking~=attacking) or clear.attacking~=attacking\n      if not D.fighters.ready(player) then\n        clear.wait=(clear.wait or 0)+1\n      else\n        local ok,why=true,true\n        if changed then ok,why=pcall(g.fly_attack,1,attacking,30,30) end\n        if ok and (not attacking or why) then\n          clear.attacking=attacking;clear.falls=player.falls\n          if e then\n            -- Escalate by moving across the target rather than pinning one contact point.\n            local target={x=e.x,y=e.y}\n            if clear.age>=600 then target.x=target.x+(clear.age%80<40 and -8 or 8)end\n            ok,why=pcall(C.target,g,target,clear,c.run.frames)\n          end\n        end\n        if not ok then\n          if not D.fighters.transient(why)then finish('clear refused '..tostring(why));return end\n          clear.refusal=tostring(why);clear.wait=(clear.wait or 0)+1\n        elseif why==false and (clear.refusal or (attacking and changed)) then clear.wait=(clear.wait or 0)+1\n        else clear.refusal=nil;clear.wait=0;clear.pulse=clear.pulse+1 end\n      end\n      clear.age=clear.age+1\n      if (clear.wait or 0)>=600 then finish('clear timed out waiting for controllable P1');return end\n    end\n    local t=c.tour\n    if not t then return end\n    local target=t.queue[t.index]\n    if not target then c.tour=nil;C.cancel(r);g.log('mission: tour complete');return end\n    t.frames=t.frames+1\n    if not t.sent then\n      t.started=g.time()\n      local ok,why=pcall(C.visit,r,target)\n      t.sent=ok\n      if not ok and not D.fighters.transient(why) then t.refusal=tostring(why) end\n    end\n    local p=c.membership and c.membership.point or g.player(1)\n    if t.refusal or (p and (p.x-target.x)^2+(p.y-target.y)^2<=1) or t.frames>=600 then\n      local loaded={}\n      for id in pairs(c.stream.loaded) do loaded[#loaded+1]=id end;table.sort(loaded)\n      g.log(('mission: tour %s loaded=%s seconds=%.6f refusal=%s'):format(target.name,table.concat(loaded,','),\n        g.time()-t.started,t.refusal or (t.frames>=600 and 'arrival timeout' or 'none')))\n      t.index=t.index+1;t.sent=false;t.frames=0;t.refusal=nil\n    end\n  end\n  function C.dispatch(r,arg)\n    local words={};for w in arg:gmatch('%S+') do words[#words+1]=w end\n    local op=words[1]\n    if op=='world'then D.world_commands.dispatch(r,words);return end\n    if op=='maze' then D.maze_commands.dispatch(r,words);return end\n    if op=='list' then\n      assert(#words==1,'usage: mission list')\n      local entries,why=r.g.mod_list('missions/');assert(entries,why)\n      table.sort(entries,function(a,b)return a.name<b.name end)\n      for _,e in ipairs(entries) do if e.dir then r.g.log('mission: folder '..e.name) end end\n      return\n    elseif op=='stop' then assert(#words==1);r:stop('stopped');return\n    elseif op=='play' then\n      assert(#words==2 or (#words==4 and words[3]=='from'),'usage: mission play <name> [from <marker>]')\n      r:install(words[2],words[4],false);return\n    end\n    assert(r.current,'no running mission; mission play <name>')\n    if op=='reload' or op=='restart' then\n      assert(#words==1);r:install(r.current.doc.name,op=='restart' and r.current.from or nil,op=='reload')\n    elseif op=='zones' then assert(#words==1,'usage: mission zones');D.zones.describe(r.g,r.current)\n    elseif op=='fly' then assert(#words==2,'usage: mission fly next|prev|<marker>');C.fly(r,words[2])\n    elseif op=='drop' then\n      assert(#words==1);C.cancel(r);r.current.tour=nil;r.current.stream.destination=nil\n      pcall(r.g.fly_attack,1,false);r.g.fly(1,'place')\n      r.g.log('mission: drop normal control')\n    elseif op=='clear' then\n      assert(#words==1);C.cancel(r);r.current.tour=nil\n      local handles={};for h in pairs(r.current.run.state.tracked) do handles[#handles+1]=h end;table.sort(handles)\n      local clear={handles=handles,index=1,elapsed=0,limit=601+(C.TARGET_LIMIT+1)*#handles}\n      r.current.clear=clear\n      if r.g.deadline and r.g.deadline_done then\n        clear.deadline='mission.clear.'..r.generation\n        local ok,why=pcall(r.g.deadline,clear.deadline,clear.limit+1)\n        if not ok or not why then C.cancel(r);error('clear deadline refused: '..tostring(why))end\n      end\n      C.tick(r);r.g.log('mission: clear begin (target limit 1500 frames; pulse 28/12)')\n    elseif op=='tour' then assert(#words==1);C.cancel(r);C.tour(r)\n    else error('usage: mission play|stop|restart|reload|list|fly|clear|drop|tour|maze') end\n  end\n  return C\nend\n", "@missions/commands.lua", "t"))()(missions)
missions.mission_finish = assert(load("-- The existing mission result owns an offline finish panel and one pause.\nreturn function(D)\n  local F={}\n  function F.tick(r)\n    local c=r.current;if not c or not c.run.state.result then return end\n    if r.staging or r.pending or r.world_generation or r.stopping then return end\n    if c.run.finish then\n      if c.run.finish_restore then\n        if r.g.pause and not(r.g.paused and r.g.paused())then r.g.pause();c.run.finish_pause=true end\n        c.run.finish_restore=nil\n      end\n      return\n    end\n    if c.run.state.result.status~='complete'then return end\n    D.commands.cancel(r);c.tour=nil\n    c.run.finish=true\n    if r.g.pause and not(r.g.paused and r.g.paused())then r.g.pause();c.run.finish_pause=true end\n    r.g.log('mission: finish - restart, reroll or stop')\n  end\n  function F.release(r,restore)\n    local c=r.current\n    if c and c.run.finish_pause then c.run.finish_restore=restore or nil;if r.g.resume then r.g.resume()end;c.run.finish_pause=nil end\n  end\n  function F.draw(g,c)\n    if not c.run.finish then return end\n    local area=g.safe_area and g.safe_area()or{w=640,h=480};local x=math.max(16,(area.w-480)/2)\n    if g.fill then g.fill(x,170,480,130,0x10151FEE)end\n    g.text(x+24,192,'MISSION COMPLETE',0xEBD175FF)\n    g.text(x+24,224,D.mission.result_text(c.run.state))\n    g.text(x+24,258,c.doc.maze and c.doc.maze.world and 'mission restart / world reroll / stop'or 'mission restart / maze reroll / stop')\n  end\n  return F\nend\n", "@missions/mission_finish.lua", "t"))()(missions)
missions.hud = assert(load("return function(D)\n  local H={}\n  function H.draw(g,current)\n    if not current then return end\n    local run=current.run\n    local text=D.mission.result_text(run.state) or D.mission.hud(run.state)\n    local m=current.membership\n    if m and m.region then text=text..' | region '..m.region end\n    if current.doc.maze and current.doc.maze.world then\n      local links={};for _,e in ipairs(current.doc.maze.world.links)do links[#links+1]=e.a..'-'..e.b end\n      g.text(16,64,'World: '..table.concat(links,' / '))\n    end\n    if m then text=text..' | zones room='..(m.room and m.room.id or 'none')..' transition='..(m.transition and m.transition.name or 'none')..' committed='..(m.committed and m.committed.id or 'none')end\n    g.text(16,24,current.doc.name..' | '..text)\n    if D.mission_finish then D.mission_finish.draw(g,current)end\n    if run.message then g.text(16,44,run.message.text) end\n  end\n  return H\nend\n", "@missions/hud.lua", "t"))()(missions)
missions.mission_warm = assert(load("-- Material readiness is part of installation, never an in-play surprise.\nreturn function(D)\n  local W={DRAW_FRAMES=24}\n  function W.cleanup(g,t)\n    local w=t.warming;if not w then return end\n    if w.handle and g.warm_release then g.warm_release(w.handle);w.handle=nil end\n    if w.enemy then g.enemy_remove(w.enemy);w.enemy=nil end\n    if w.model then g.model_despawn(w.model);w.model=nil end\n    if w.item then g.item_remove(w.item);w.item=nil end\n  end\n  function W.tick(g,t)\n    if not t.warming then\n      local w={started=g.time(),enemies={},items={},models={},index=1,draws=0};t.warming=w\n      local seen={};local function enemy(k)if not seen[k]then seen[k]=true;w.enemies[#w.enemies+1]=k end end\n      for _,e in ipairs(t.doc.mission.enemies)do enemy(e.kind)end\n      for _,c in ipairs(t.doc.maze and t.doc.maze.cells or{})do for _,k in ipairs(c.enemy_kinds or{})do enemy(k)end end\n      local items={};local function item(k)if not items[k]then items[k]=true;w.items[#w.items+1]=k end end\n      for _,k in ipairs(t.doc.level.warm_items or{})do item(k)end\n      for _,c in ipairs(t.doc.chunks or{})do for _,k in ipairs(c.level.warm_items or{})do item(k)end end\n      if g.item_kinds then for _,k in ipairs(g.item_kinds())do if k.name=='drive'then item('drive')end end end\n      for _,path in ipairs(t.asset_paths or{})do w.models[#w.models+1]=t.assets[path]end\n      w.native=type(g.warm)=='function'and type(g.warm_done)=='function'and type(g.warm_release)=='function'\n      w.jobs={};local batch={enemies=w.enemies,items={}};local count=#w.enemies\n      for _,k in ipairs(w.items)do\n        if count==120 then w.jobs[#w.jobs+1]=batch;batch={items={}};count=0 end\n        batch.items[#batch.items+1]=k;count=count+1\n      end\n      if count>0 then w.jobs[#w.jobs+1]=batch end;local job={models={}}\n      for _,h in ipairs(w.models)do job.models[#job.models+1]=h;if #job.models==120 then w.jobs[#w.jobs+1]=job;job={models={}}end end\n      if #job.models>0 then w.jobs[#w.jobs+1]=job end\n      w.queue={};for _,k in ipairs(w.enemies)do w.queue[#w.queue+1]={kind='enemy',value=k}end\n      for _,k in ipairs(w.items)do w.queue[#w.queue+1]={kind='item',value=k}end\n      for _,h in ipairs(w.models)do w.queue[#w.queue+1]={kind='model',value=h}end\n    end\n    local w=t.warming\n    if w.native then\n      if not w.handle and w.jobs[w.index]then w.handle=assert(g.warm(w.jobs[w.index]));return false end\n      if w.handle then\n        local done,why=g.warm_done(w.handle);assert(not why,why)\n        if not done then return false end\n        g.warm_release(w.handle);w.handle=nil;w.index=w.index+1;return false\n      end\n    else\n      assert(t.covered,'fallback warming requires a drawn opaque loading cover')\n      local q=w.queue[w.index]\n      if q then\n        if not w.active then\n          local p=t.player or t.target\n          if q.kind=='enemy'then w.enemy=assert(g.spawn_enemy(q.value,p.x+12,p.y+4,{facing=-1}))\n          elseif q.kind=='item'then assert(g.item_spawn and g.item_remove,'item fallback warm APIs unavailable');w.item=assert(g.item_spawn(q.value,p.x+12,p.y+4,{}))\n          else w.model=assert(g.model_spawn(q.value,{x=p.x,y=p.y,z=0,rot=0,scale=1,collision=false,visible=true}))end\n          w.active=true;w.draws=0;return false\n        end\n        if w.draws<W.DRAW_FRAMES then return false end\n        W.cleanup(g,t);w.active=nil;w.index=w.index+1;return false\n      end\n    end\n    if not w.done then w.done=true;g.log(('mission: warm complete mode=%s seconds=%.6f'):format(w.native and 'native'or 'covered-draw',g.time()-w.started))end\n    return true\n  end\n  function W.draw(g,t)\n    local a=g.safe_area and g.safe_area()or{w=640,h=480}\n    assert(g.fill,'staging requires an opaque loading cover')\n    g.fill(0,0,a.w,a.h,0x10151FFF);t.covered=true\n    if g.text then g.text(24,32,'Preparing mission...')end\n    if t.warming and t.warming.active then t.warming.draws=t.warming.draws+1 end\n  end\n  return W\nend\n", "@missions/mission_warm.lua", "t"))()(missions)
missions.install = assert(load("-- Resumable install: each engine on_frame callback performs one bounded phase.\nreturn function(D)\n  -- Native writes are synchronous; reserve readiness is queried without setter retries.\n  local function restoration(D)\n  local S={EPS=0.01}\n  local function near(a,b)return a~=nil and b~=nil and math.abs(a-b)<=S.EPS end\n  local function same(a,b)\n    if not a or not b then return false end\n    for k,v in pairs(b)do\n      if type(v)=='number' then if not near(a[k],v)then return false end\n      elseif type(v)=='table' then if not same(a[k],v)then return false end\n      elseif a[k]~=v then return false end\n    end\n    return true\n  end\n  S.same=same\n  function S.origin(g,p)\n    if not same(g.stage_bounds().origin or {x=0,y=0},p)then assert(g.stage_set_origin(p.x,p.y,{frames=0}))end\n  end\n  function S.bounds(g,kind,b)\n    local live=g.stage_bounds()\n    if not same(live[kind],b)then\n      local p=live.origin or {x=0,y=0}\n      assert(g['stage_set_'..kind..'_bounds'](b.left-p.x,b.right-p.x,b.top-p.y,b.bottom-p.y))\n    end\n  end\n  function S.params(g,p)\n    if p and not same(g.camera_params({}),p)then g.camera_params(p)end\n  end\n  function S.spawn(g,slot,p)\n    local x,y=g.stage_spawn(slot)\n    if not near(x,p.x)or not near(y,p.y)then assert(g.stage_set_spawn(slot,p.x,p.y))end\n  end\n  function S.hide(g,t,value)\n    local live=t.hidden\n    if g.stage_isolate then live=g.stage_isolate()end\n    if live~=value then local ok,why=g.stage_hide(value);assert(ok,why);t.hidden=value end\n  end\n  function S.damage(g,n)\n    if n==nil or not g.set_damage then return end\n    n=math.max(0,math.min(999,math.floor(n)))\n    local p=g.player(1)\n    if not p or not near(p.percent,n)then g.set_damage(1,n)end -- returns ZERO Lua values\n    p=g.player(1);assert(p and near(p.percent,n),'P1 percent readback differs from synchronous set_damage')\n  end\n  function S.ready(g,port)\n    local _,entities=g.fighter_benched(port)\n    for _,p in ipairs(entities or {})do\n      if p.present and p.refusal_code and p.refusal_code~=0 then\n        return false,'reserve '..port..' entity '..(p.entity_index or 0)..' refusal_code='..p.refusal_code\n      end\n    end\n    return true\n  end\n  function S.new(r,t)\n    local g=r.g;local ops={}\n    local function add(name,fn)ops[#ops+1]={name='rollback.'..name,run=fn}end\n    if t.changed then\n      add('origin',function()S.origin(g,t.bounds.origin or {x=0,y=0})end)\n      for _,kind in ipairs({'camera','blast'})do local b=t.bounds[kind];if b then add(kind,function()S.bounds(g,kind,b)end)end end\n      add('params',function()S.params(g,t.params)end)\n      for slot,p in pairs(t.spawn)do add('spawn'..slot,function()S.spawn(g,slot,p)end)end\n      add('hide',function()S.hide(g,t,t.old~=nil)end)\n    end\n    add('P1',function()\n      if t.held then\n        local ready,why=S.ready(g,1);if not ready then return false,why end\n        local ok,reason=g.fighter_call(1,t.player.x,t.player.y,{facing=t.player.facing or 1,intangible_frames=60})\n        if not ok then return false,reason end;t.held=nil\n      elseif t.placed then\n        local p=g.player(1)\n        if not p or not near(p.x,t.player.x)or not near(p.y,t.player.y)then g.teleport(1,t.player.x,t.player.y)end\n      end\n    end)\n    add('damage',function()S.damage(g,t.player.percent)end)\n    add('pose',function()\n      if t.camera_held and t.pose and not same(g.camera_get(),{eye=t.pose.eye,interest=t.pose.interest,fov=t.pose.fov,roll=t.pose.roll})then D.camera.cut(g,t.pose)end\n    end)\n    for port,record in pairs(t.c.fighters or {})do\n      add('CPU'..port,function()\n        local previous=t.old and t.old.fighters or r.guests.fighters\n        if t.old then\n          local ready,why=S.ready(g,port);if not ready then return false,why end\n          if previous[port]and previous[port].owned then\n            if not g.fighter_benched(port)then local ok,reason=g.fighter_bench(port);if not ok then return false,reason end end\n          else\n            local p=t.cpus[port]\n            if p then\n              if not g.fighter_benched(port)then local ok,reason=g.fighter_bench(port);if not ok then return false,reason end end\n              local ok,reason=g.fighter_call(port,p.x,p.y,{intangible_frames=60});if not ok then return false,reason end\n              if previous[port]and previous[port].mode and g.cpu_mode then g.cpu_mode(port,previous[port].mode)end\n            end\n          end\n        elseif not previous[port]then D.fighters.stop(g,{fighters={[port]=record}})end\n      end)\n    end\n    return {ops=ops,index=1}\n  end\n  function S.tick(t)\n    local op=t.ops[t.index];if not op then return true end\n    local accepted,why=op.run()\n    if accepted==false then return false,why end\n    t.index=t.index+1;return true\n  end\n  return S\nend\n\n  local T={WAIT_LIMIT=120};local S=restoration(D);D.install_restore=S\n  local function areas(c)\n    local out={};if c and c.root then out[#out+1]=c.root end\n    for _,a in pairs(c and c.stream.loaded or {}) do out[#out+1]=a end\n    return out\n  end\n  local function copy(records)\n    local out={}\n    for port,r in pairs(records or {}) do local q={};for k,v in pairs(r) do q[k]=v end;out[port]=q end\n    return out\n  end\n  function T.begin(r,name,marker,reload)\n    assert(not r.staging,'mission installation already in progress')\n    local g=r.g;local match=g.match()\n    assert(match and match.active and not match.netplay,'active offline match required')\n    local p=assert(g.player(1),'P1 is required')\n    assert(D.fighters.stage_ready(g),'respawning or entry/landing: waiting for reserve-ready P1')\n    local cpus={};for port=2,6 do local q=g.player(port);if q and q.cpu then cpus[port]=q end end\n    if r.current then D.commands.cancel(r)end\n    r.generation=r.generation+1;r.last_install_error=nil\n    r.staging={name=name,marker=marker,reload=reload,old=r.current,phase='prepare',frames=0,\n      player=p,cpus=cpus,bounds=g.stage_bounds(),params=g.camera_params and g.camera_params({}),\n      pose=g.camera_get and g.camera_get(),prefix='mission'..r.generation..'_',assets={},asset_paths={},\n      built={},spawn={},c={fighters=copy(r.current and r.current.fighters or r.guests.fighters)}}\n    local t=r.staging;t.hidden=g.stage_isolate and g.stage_isolate() or t.old~=nil\n    if not r.host_bounds then\n      r.host_bounds=t.bounds;r.host_spawns={}\n      for _,range in ipairs({{0,7},{127,146}})do for slot=range[1],range[2]do\n        local x,y=g.stage_spawn(slot);r.host_spawns[slot]={x=x,y=y}\n      end end\n    end\n    g.log('mission: staging '..name)\n  end\n  local function prepare(r,t)\n    local g=r.g\n    if not t.old then r.guests.fighters=t.c.fighters end -- retain match safety reserve on refusal\n    t.c.doc={level={fighters={}}}\n    local safe,reason=pcall(D.fighters.prepare,g,t.c)\n    if not safe then\n      if D.fighters.transient(reason)then t.wait_condition=tostring(reason);return end\n      error(reason,0)\n    end\n    if not D.fighters.stage_ready(g)then t.wait_condition='waiting for reserve-ready P1';return end\n    assert(g.fighter_bench and g.fighter_call,'mission staging requires fighter reserve APIs')\n    assert(not (g.fighter_benched and g.fighter_benched(1)),'P1 already reserved')\n    local ok,why=g.fighter_bench(1);assert(ok,'P1 bench refused: '..tostring(why));t.held=true\n    if t.pose then D.camera.cut(g,t.pose);t.camera_held=true end\n    t.phase='validate'\n  end\n  local function validate(r,t)\n    local g=r.g;local doc=D.loader.folder(g,t.name);t.doc=doc\n    if t.reload and t.old and t.old.run.state.cp and doc.mission.checkpoints[t.old.run.state.cp] then\n      t.marker='checkpoint'..t.old.run.state.cp\n    end\n    t.target=t.reload and {x=t.player.x,y=t.player.y} or (t.marker and D.glue.marker(doc,t.marker) or doc.mission.start)\n    local initial=D.zones.initial(doc,t.target,t.reload and t.old and t.old.strea