missions.mission_launch = assert(load("-- Engine-held launch uses render ticks; ordinary missions use logic frames.\nreturn function(D)\n  local L={}\n  function L.begin(r,q)\n    if r.launch then return end\n    r.last_install_error=nil;r.pending_error=nil\n    r.launch={frames=0,engine=q.pending==true}\n    local accepted,why=pcall(function()\n      local command\n      if type(q.mission)=='string'and q.mission~=''then D.validator.name(q.mission);command='play '..q.mission\n      elseif q.size and q.size>0 then command=('maze %d %d'):format(q.seed,q.size)\n      else error('launch needs a mission or maze')end\n      r.launch.command=command\n      local ok,reason=r:command(command);assert(ok,reason)\n    end)\n    if not accepted then L.cancel(r,why)end\n  end\n  function L.cancel(r,why)\n    local launch=r.launch;r.launch=nil\n    if launch and launch.engine and r.g.launch_cancel then r.g.launch_cancel(tostring(why))end\n    r.g.log('mission: launch refused '..tostring(why))\n  end\n  function L.tick(r)\n    local q=r.launch;if not q then return end\n    q.frames=q.frames+1\n    if r.last_install_error or r.recovery then L.cancel(r,r.last_install_error or 'staging recovery required');return end\n    if q.engine then\n      if r.staging then D.install.tick(r)\n      elseif r.pending then r:retry()end\n      if D.maze_commands then D.maze_commands.settle(r)end\n    end\n    if r.pending_error or r.last_install_error or r.recovery then L.cancel(r,r.pending_error or r.last_install_error or 'staging recovery required');return end\n    if r.current and not r.staging and not r.pending then\n      if not q.engine or not r.g.launch_ready or r.g.launch_ready()then r.launch=nil;return end\n    end\n    if q.frames>=7200 then L.cancel(r,'mission launch timed out after 7200 ticks')end\n  end\n  function L.autostart(r)\n    if r.launch then return end\n    local q=r.g.launch_request and r.g.launch_request()\n    if q and q.pending then return end -- engine delivers the selected on_launch owner\n    local data=D.loader.data(r.g,'missions/autostart.lua',true)\n    if data then L.begin(r,data);return end\n    -- A level may opt in. Refuse ambiguity, never choose an arbitrary folder.\n    local selected;local entries=r.g.mod_list('missions/')or{}\n    if #entries>64 then r.g.log('mission: autostart scan exceeds 64 folders; use missions/autostart.lua');return end\n    for _,e in ipairs(entries)do if e.dir and type(e.name)=='string'and e.name:match('^[%w_-]+$')then\n      local level=D.loader.data(r.g,'missions/'..e.name..'/level.lua',true)\n      if level and level.autostart==true then\n        if selected then r.g.log('mission: ambiguous level autostart; use missions/autostart.lua');return end\n        selected=e.name\n      end\n    end end\n    if selected then L.begin(r,{mission=selected})end\n  end\n  return L\nend\n", "@missions/mission_launch.lua", "t"))()(missions)
missions.runtime = assert(load("-- Transaction coordinator and lifecycle; module factories also load under plain Lua.\nreturn function(D)\n  local R={};R.__index=R\n  function R.new(g)\n    local r=setmetatable({g=g,current=nil,generation=0,poll=0,guests={fighters={}}},R)\n    g.command('mission',function(arg) return r:command(arg) end,'Standalone mission folders and fly fixtures')\n    return r\n  end\n  function R:attempt(arg)\n    local op=arg:match('^%s*(%S+)')\n    if op=='play' or op=='reload' or op=='restart' or op=='fly' or op=='drop' or ((op=='maze'or op=='world')and not arg:match('%s+map%s*$')) then\n      if not D.fighters.ready(self.g.player(1)) or ((op=='play' or op=='reload' or op=='restart') and not D.fighters.stage_ready(self.g)) then return nil,'waiting for controllable P1',true end\n    end\n    local ok,why=pcall(D.commands.dispatch,self,arg)\n    return ok,why,not ok and D.fighters.transient(why)\n  end\n  function R:command(arg)\n    arg=arg or '';self.pending=nil;self.pending_error=nil\n    if (self.staging or self.recovery or self.stopping or self.world_generation)and not arg:match('^%s*stop%s*$')then\n      local why=self.stopping and 'mission cleanup pending; mission stop retries' or self.recovery and 'staging recovery required; mission stop retries cleanup' or 'mission installation already in progress'\n      self.g.log('mission: refused '..why);return nil,why\n    end\n    local op=arg:match('^%s*(%S+)')\n    local replacing=op=='play'or op=='reload'or op=='restart'or op=='stop'or((op=='maze'or op=='world')and not arg:match('%s+map%s*$'))\n    if self.current and self.current.run.finish and (op=='fly'or op=='drop'or op=='tour'or op=='clear')then\n      return nil,'mission ended; restart, reroll or stop'\n    end\n    local ok,why,retry=self:attempt(arg)\n    if retry then\n      if D.mission_finish and replacing then D.mission_finish.release(self,op~='stop')end\n      self.pending={arg=arg,frames=0};self.g.log('mission: '..arg..' waiting for controllable P1 (600-frame limit)');return true\n    end\n    if not ok then self.g.log('mission: refused '..tostring(why));return nil,why end\n    if D.mission_finish and replacing then D.mission_finish.release(self,op~='stop')end\n    return true\n  end\n  function R:retry()\n    local pending=self.pending;if not pending then return end\n    pending.frames=pending.frames+1\n    if pending.frames%6==0 then\n      local ok,why,retry=self:attempt(pending.arg)\n      if ok or not retry then\n        self.pending=nil\n        if not ok then self.pending_error=tostring(why);self.g.log('mission: refused '..tostring(why))end\n        return\n      end\n    end\n    if pending.frames>=600 then\n      self.pending=nil;self.pending_error=pending.arg..' timed out waiting for controllable P1';self.g.log('mission: '..self.pending_error)\n    end\n  end\n  function R:dispose(c)\n    if not c then return end\n    if c==self.current then D.commands.cancel(self)end\n    D.glue.cleanup(self.g,c.run)\n    D.chunks.stop(c.stream)\n    if c.root then D.world.unload(self.g,c.root) end\n    for _,asset in pairs(c.asset_pool or {}) do pcall(self.g.model_release,asset) end\n  end\n  function R:stop(reason)\n    local g=self.g;self.pending=nil\n    if D.mission_finish then D.mission_finish.release(self)end\n    if D.world_commands then D.world_commands.cancel(self)end\n    if self.stopping and self.stopping.blocked then self.stopping=nil end\n    if self.recovery then self.staging=self.recovery;self.recovery=nil;self.staging.step_key=nil end\n    if self.staging then\n      local match=g.match()\n      if not match or not match.active or match.netplay or reason=='unload' or reason=='state load unsupported' then D.install.abandon(self)\n      else self.staging.stop_reason=reason;D.install.fail(self,'staging cancelled: '..tostring(reason));return end\n    end\n    local match=g.match()\n    if self.current and match and match.active and not match.netplay then\n      -- Settlement precedes a queued scene launch: retire the old floor only after\n      -- leaving grounded callbacks, while its collision is still live.\n      local ok,why=pcall(function()g.fly_attack(1,false);g.fly(1,true);g.fly(1,false)end)\n      if not ok then\n        if not self.stopping then self.stopping={reason=reason,frames=0};g.log('mission: cleanup waiting for airborne P1: '..tostring(why))end\n        return\n      end\n    end\n    self.stopping=nil\n    D.install.dispose_retired(self)\n    D.camera.stop(g)\n    local guests=self.current or self.guests\n    if self.current then self:dispose(self.current);self.current=nil end\n    pcall(g.fly_attack,1,false);pcall(g.fly,1,false)\n    pcall(g.stage_hide,false);pcall(g.stage_restore_bounds)\n    D.fighters.stop(g,guests)\n    self.guests={fighters={}};self.guarded=nil;self.host_bounds=nil;self.host_spawns=nil\n    if reason=='match end'or reason=='unload'then self.autostart_checked=nil end\n    if self.launch and D.mission_launch then D.mission_launch.cancel(self,reason)end\n    g.log('mission: stopped '..tostring(reason))\n  end\n  function R:install(name,marker,reload) return D.install.begin(self,name,marker,reload) end\n  function R:match_start()\n    if self.staging then return end -- partial CPU reservations belong to this transaction\n    local match=self.g.match()\n    if match and match.active and not match.netplay then\n      self.guarded=D.fighters.guard(self.g,self.guests)\n      if D.mission_launch and not self.autostart_checked then self.autostart_checked=true;local ok,why=pcall(D.mission_launch.autostart,self)\n        if not ok then self.g.log('mission: autostart refused '..tostring(why))end end\n    end\n  end\n  function R:pre_frame()\n    local match=self.g.match()\n    if match and match.active and not match.netplay then\n      if not self.guarded then self:match_start() end\n      -- Retirement shares the active frame mutation budget below.\n    end\n  end\n  function R:frame()\n    local match=self.g.match()\n    if not match or not match.active or match.netplay then\n      if self.current or self.pending or self.staging or self.recovery or self.world_generation or next(self.guests.fighters) then self:stop('match end') end;return\n    end\n    if not self.guarded then self:match_start() end\n    if self.stopping then\n      local t=self.stopping;t.frames=t.frames+1\n      if t.frames==120 then t.blocked=true;self.g.log('mission: cleanup refused after 120 frames; mission stop retries');return end\n      if not t.blocked and t.frames%6==0 then self:stop(t.reason)end\n      return\n    end\n    if self.launch and self.launch.engine then return end\n    if self.staging then\n      D.install.tick(self)\n      if D.maze_commands then D.maze_commands.settle(self)end\n      if D.world_commands then D.world_commands.settle(self)end\n      if D.mission_finish then D.mission_finish.tick(self)end\n      return\n    end\n    if self.recovery then return end\n    D.camera.release(self.g) -- also release a rollback pose when no mission is active\n    self:retry()\n    if self.staging then return end\n    if D.world_commands then D.world_commands.tick(self)end\n    if self.staging then return end\n    if not self.current then return end\n    self.poll=self.poll+1\n    if self.poll%15==0 and not self.pending and not self.world_generation and D.fighters.ready(self.g.player(1)) then\n      local c=self.current\n      if not D.loader.same(c.doc.stamps,D.loader.stamps(self.g,c.doc.folder)) then self:command('reload');return end\n    end\n    local c=self.current\n    c.run.frames=c.run.frames+1\n    local ok,why=pcall(function()\n      local player=self.g.player(1) -- one post-physics observation for all bookkeeping\n      local membership=D.zones.sample(self.g,c,player,c.run.frames)\n      player=membership.point\n      D.glue.step(self.g,c,player)\n      local streamed,err=D.chunks.update(c.stream,player,membership)\n      if not streamed then self.g.log('mission: chunk refused '..tostring(err))end\n      if self.retiring and c.stream.load_frame~=membership.frame and c.stream.wave_frame~=membership.frame then\n        c.stream.load_frame=membership.frame;D.install.retire(self)\n      end\n      if D.maze_rewards then D.maze_rewards.tick(self.g,c) end\n      D.fighters.tick(self.g,c)\n      D.camera.tick(self.g,c,player)\n      D.commands.tick(self)\n      if D.mission_finish then D.mission_finish.tick(self)end\n    end)\n    if not ok then self.g.log('mission: frame refused '..tostring(why)) end\n  end\n  function R:tick()\n    if D.mission_launch then D.mission_launch.tick(self)end\n  end\n  function R:launch_start(q)\n    if D.mission_launch then D.mission_launch.begin(self,q)end\n  end\n  function R:draw()\n    if self.staging and D.mission_warm then D.mission_warm.draw(self.g,self.staging);return end\n    D.hud.draw(self.g,self.current)\n    if self.world_generation then self.g.text(16,88,'Generating world - please wait')end\n  end\n  return R\nend\n", "@missions/runtime.lua", "t"))()(missions)
missions.mission_launch = nil -- Envoy owns explicit scene/run launch; no standalone autostart.
local envoy = {loader=missions.loader, maze_set=missions.maze_set, maze=missions.maze}
envoy.pickup_juice = assert(load("-- Reusable offline pickup presentation. Embed this factory in sandbox entries (no require).\n-- One gd.items() snapshot per tick; effects never decide rewards or item physics.\nlocal J={}\nJ.defaults={glow=true,pool=true,sparkles=true,highlight=true,pop_trail=true,collect_burst=true,\n sound=true,hud_flash=true,blink=true,streak_frames=90,streak_step=70,streak_cap=900,\n max_effect_drops=30,max_collect_bursts=12,core_height=5.6875,drop_sound=246,pickup_sound=170,white_sound=250,volume=90,flash_frames=24}\nJ.pitch={red=-100,green=200,blue=0,yellow=100,white=300}\nlocal function call(f,...) if type(f)~='function' then return nil end;local ok,r=pcall(f,...);if ok then return r end end\nfunction J.new(g,settings)\n local s={};for k,v in pairs(J.defaults) do s[k]=v end;for k,v in pairs(settings or {}) do s[k]=v end\n local v={g=g,s=s,drops={},transients={},flash={},frame=0,streak=0,last=nil,seed=0}\n local function finish(h) if h then call(g.fx_end,h,0) end end\n local function play(kind,c,x,y,z)\n  v.seed=(v.seed+1)%2147483647\n  local h=call(g.fx_world,'PickupJuice_'..kind..'_'..c,x,y,z or 0,1,v.seed)\n  if not (type(h)=='number' and h>0) and not v.warned then\n   v.warned=true;call(g.log,'pickup juice: FX unavailable; mount the owning mod at boot (effects disabled safely)')\n  end\n  return type(h)=='number' and h>0 and h or nil\n end\n local function kill(d) for _,h in pairs(d.fx) do finish(h) end;d.fx={} end\n function v:drop(id,colour,x,y,lifetime)\n  if self.drops[id] then self:expire(id) end\n  colour=J.pitch[colour] and colour or 'white'\n  local d={colour=colour,x=x,y=y,z=0,age=0,lifetime=lifetime or 900,fx={}}\n  self.drops[id]=d\n  if s.sound then call(g.play_sound,s.drop_sound,{volume=s.volume,pitch=J.pitch[colour]}) end\n  local active=0;for _,other in pairs(self.drops) do if next(other.fx) then active=active+1 end end\n  if active<s.max_effect_drops then\n  for _,kind in ipairs({'glow','pool','sparkles','highlight','pop_trail'}) do\n   if s[kind] then d.fx[kind]=play(kind,colour,x,y+(kind=='pool' and .15 or 6+s.core_height),0) end\n  end\n  end\n  return d\n end\n function v:expire(id) local d=self.drops[id];if d then kill(d);self.drops[id]=nil end end\n function v:collect(id,colour,collector)\n  local d=self.drops[id];if not d then return nil end\n  colour=d.colour;self:expire(id)\n  if not self.last or self.frame-self.last>s.streak_frames then self.streak=0 else self.streak=self.streak+1 end\n  self.last=self.frame\n  local pitch=math.min(1200,J.pitch[colour]+math.min(s.streak_cap,self.streak*s.streak_step))\n  if s.sound then call(g.play_sound,colour=='white' and s.white_sound or s.pickup_sound,{volume=s.volume,pitch=pitch}) end\n  if s.hud_flash then self.flash[colour]=s.flash_frames end\n  if s.collect_burst then\n   if #self.transients>=s.max_collect_bursts then finish(self.transients[1].h);table.remove(self.transients,1) end\n   local h=play('collect_burst',colour,d.x,(d.visual_y or d.y+6)+s.core_height,d.z)\n   if h then self.transients[#self.transients+1]={h=h,left=24,total=24,x=d.x,y=(d.visual_y or d.y+6)+s.core_height,z=d.z,target=collector} end\n  end\n  return pitch\n end\n function v:tick()\n  self.frame=self.frame+1\n  local by={};for _,r in ipairs(call(g.items) or {}) do if r.handle then by[r.handle]=r end end\n  for id,d in pairs(self.drops) do\n   d.age=d.age+1;local r=by[id]\n   if r then d.seen=true;d.age=r.age or d.age;d.x=r.x;d.y=r.y;d.z=r.z or 0;d.visual_y=r.visual_y or r.y+6 end\n   if (type(id)=='number' and not r and (d.seen or d.age>2)) or d.age>=d.lifetime then self:expire(id)\n   else\n    local visible=not r or r.visible~=false or not s.blink\n    local opacity=visible and 1 or 0\n    for kind,h in pairs(d.fx) do\n     local x,y,z=d.x,(d.visual_y or d.y+6)+s.core_height,d.z\n     if kind=='pool' then y=d.y+.15\n     elseif kind=='highlight' then local angle=r and math.rad(r.rotation or 0) or d.age*math.pi/30;x=x+math.cos(angle)*3;y=y+math.sin(angle)*1.2;z=z+math.sin(angle)*3 end\n     call(g.fx_move,h,x,y,z)\n     -- fx_control overwrites all controls: specify brightness to preserve pop emphasis.\n     local bright=(kind=='pop_trail' or (kind=='glow' and s.pop_trail and d.age<24)) and 2 or 1\n     if d.opacity~=opacity or (kind=='glow' and d.age==24) or (kind=='pop_trail' and d.age==1) then\n      call(g.fx_control,h,-1,{opacity=opacity,brightness=bright},0)\n     end\n     if kind=='pop_trail' and d.age>=24 then finish(h);d.fx[kind]=nil end\n    end\n    d.opacity=opacity\n   end\n  end\n  for c,n in pairs(self.flash) do self.flash[c]=n>1 and n-1 or nil end\n  for i=#self.transients,1,-1 do\n   local t=self.transients[i];t.left=t.left-1\n   if t.left<=0 then finish(t.h);table.remove(self.transients,i)\n   elseif t.target then\n    local f=1-t.left/t.total\n    call(g.fx_move,t.h,t.x+(t.target.x-t.x)*f,t.y+(t.target.y-t.y)*f,t.z)\n   end\n  end\n end\n function v:clear()\n  for id in pairs(self.drops) do self:expire(id) end\n  for _,t in ipairs(self.transients) do finish(t.h) end\n  self.transients={};self.flash={};self.streak=0;self.last=nil\n end\n return v\nend\nreturn J\n", "@lib/pickup_juice.lua", "t"))()
envoy.mod_progression = assert(load("-- Progression grows until numerical/physics safety, independently of event depth.\nreturn function()\n local P={}\n local function integer(n) return type(n)=='number' and n==n and n%1==0 and n>=0 and n<=2147483646 end\n function P.context(depth,loop)\n  if type(depth)=='table' then\n   assert(not getmetatable(depth),'plain progression context required')\n   for k in pairs(depth)do assert(k=='depth' or k=='loop','unknown progression field')end\n   loop=depth.loop;depth=depth.depth\n  end\n  depth=depth or 0;loop=loop or 0;assert(integer(depth) and integer(loop),'depth/loop must be bounded nonnegative integers')\n  return {depth=depth,loop=loop}\n end\n function P.effective(c) c=P.context(c);return c.depth+13*c.loop end\n -- A run's own length sets the New Game+ offset: effective depth = stage + 13 x units x loop, so the loop never starts below the\n -- run's last stage. Classic has 11 stages (one unit, 13); Adventure has 22 (two units, 26). The stage is NOT capped: depth follows\n -- the stage index through the whole run.\n P.run_units={classic=1,adventure=2}\n function P.units(mode) return P.run_units[mode] or 1 end\n function P.run_context(mode,stage,loop) return P.context(stage,(loop or 0)*P.units(mode)) end\n function P.run_loop(mode,context) return math.floor(P.context(context).loop/P.units(mode)) end\n function P.tier(c) return 1+math.floor(P.effective(c)/5) end\n function P.growth(t)\n  assert(type(t)=='number' and t%1==0 and t>=1 and t<=6500000000,'invalid tier')\n  -- Preserve authored EM4 tiers 1..3; logarithmic guard prevents overflow.\n  if t<=3 then return 1+.25*(t-1)end\n  return math.exp(math.min(math.log(1.5)+(t-3)*math.log(1.45),math.log(1000000)))\n end\n function P.launch_growth(t)\n  local growth=P.growth(t);return growth<=1.5 and growth or 1.5*(growth/1.5)^.15\n end\n function P.slots(c) return math.min(6,4+math.floor(P.effective(c)/5)) end\n -- Keystone allowance: one at the start, one more every five effective depth, no ceiling (the pool, the\n -- exclusion rules and the drawback floor in `keystones.lua` are the limits). Kept under the old name too:\n -- drive_bag.lua and mod_engine.lua assert against P.keystones.\n P.keystone_step=5\n function P.allowance(c) return 1+math.floor(P.effective(c)/P.keystone_step) end\n function P.keystones(c) return P.allowance(c) end\n -- RULES PER DRIVE (readability split, 2026-10-05): never more than two. ONE rule below effective depth 5, two from depth 5 on, and no\n -- extra rule for a white drive (the roller alternates a standing rule and a trigger rule, so a two-rule drive is one of each). Rarity stops\n -- meaning \"more rules\": a magic and a rare drive both carry up to two; the better tier comes from merging and from depth.\n -- Bands are in EFFECTIVE depth (depth + 13 per New Game+ loop), so every loop is in the top band.\n P.max_rules=2\n P.affix_bands={{top=4,cap=1},{top=math.huge,cap=P.max_rules}}\n P.rarity_from={common=0,magic=3,rare=6,unique=10}\n function P.affix_cap(c) local e=P.effective(c);for _,b in ipairs(P.affix_bands) do if e<=b.top then return b.cap end end end\n function P.rarity_allowed(c,rarity) return P.effective(c)>=P.rarity_from[rarity] end\n P.rarity_affixes={common=1,magic=2,rare=2}\n -- Natural drop weights by band. Tuned so the build power of a filled set of slots stays within about 10% of the\n -- pre-curve game from depth 5 on (see PLAYTEST: affix-count curve), while early drives are one plain effect.\n P.rarity_bands={{top=2,w={common=100,magic=0,rare=0,unique=0}},{top=5,w={common=85,magic=15,rare=0,unique=0}},\n  {top=9,w={common=82,magic=15,rare=3,unique=0}},{top=math.huge,w={common=80,magic=15,rare=4,unique=1}}}\n function P.rarity_weights(c) local e=P.effective(c);for _,b in ipairs(P.rarity_bands) do if e<=b.top then return b.w end end end\n -- The top of the band an effective depth sits in: the room an opponent's roll may borrow in tier without leaving the depth's rarity band (it keeps an early\n -- opponent from rolling a unique at depth 5). Rarity bands, since the rule-count bands are only two now.\n function P.band_top(c) local e=P.effective(c);for _,b in ipairs(P.rarity_bands) do if e<=b.top then return b.top end end end\n -- The one count rule: rarity's own count, held down by the depth band. `white` is accepted and ignored (White no longer adds a rule).\n function P.affix_count(c,rarity,white)\n  return math.min(P.rarity_affixes[rarity] or 1,P.affix_cap(c))\n end\n -- Opponents roll against the player's ACTUAL build strength times this edge, which grows with effective depth\n -- (was .003: opponents were barely ahead; .010 gives +5% at depth 5, +10% at depth 10, +13% in New Game+ 1, +39% in NG+3; a bigger edge makes the late exchanges lopsided (power_curve test)).\n P.opponent_edge=.010\n -- The edge stops growing at +25%: AI-versus-AI runs (envoy-foes harness, 126 trials) showed opponents out-dealing the player 1.0x at loop 0,\n -- 1.3x at NG+1 (edge 13-23%), 2.5x at NG+2 (26-36%) and 4.6x at NG+3 (39-49%) in damage dealt.\n P.opponent_edge_cap=.25\n function P.factor(c,role)\n  assert(role==nil or role=='normal' or role=='boss' or role=='finalboss','unknown opponent role')\n  return (1+math.min(P.opponent_edge_cap,P.opponent_edge*P.effective(c)))*(role=='boss' and 1.15 or role=='finalboss' and 1.3 or 1)\n end\n function P.exchange(attacker,defender)\n  -- Mario sweetspot forward smash, raw/current-hit18, weight100, KBG95 BKB25.\n  -- Percent-only bonuses enter the next hit's starting percent, never raw damage.\n  -- FD no-DI continuous horizontal-distance proxy at44deg, threshold196.8699.\n  local percent=0\n  local damage,scale\n  if attacker.percent_damage then damage=attacker.percent_damage;scale=attacker.launch\n  else damage=attacker.damage_dealt.potential*defender.damage_taken.potential;scale=attacker.launch_dealt.potential*math.max(.05,math.min(4,defender.launch_taken.potential+(attacker.curse_dealt and attacker.curse_dealt.potential-1 or 0)))end\n  for hits=1,1000 do\n   local after=percent+18\n   local kb=((after/10+after*18/20)*1.4+18)*.95+25\n   if kb*scale>=196.8699 then return hits end\n   percent=math.min(999,percent+18*damage)\n  end\n  return nil,'launch proxy unreachable at percent display ceiling'\n\n end\n -- ---- the Versus set (online Envoy, stage 3) -------------------------------------------------------------------------------------\n -- Pure functions of (set seed, game, seat, the picks so far): every client computes BOTH players' builds and offers the same way, so nothing but the\n -- seed and each pick (an index) crosses the network. The records are passive only (see mod_engine E.online_safe); a build is one starter record,\n -- one keystone, and what the picks added. Needs D.mod_pool, D.mod_codec and D.mod_engine at call time (this module loads first).\n -- Picks use the native lobby's numbering: 0..2 = the offer shown, 3 = keep the build (also the late default would be 0, see gw_netplay.c).\n P.set={offers=3,keep=3,max_tier=3}\n local function set_ids(D,kind)\n  local ids={}\n  for _,m in ipairs(D.mod_pool) do if m.kind==kind and D.mod_engine.online_safe(m) then ids[#ids+1]=m.id end end\n  table.sort(ids);return ids\n end\n -- The starter record and the keystone of one seat. Seats differ (the seed is mixed with the seat) and the choice is a pure function of the seed.\n function P.set_starter(D,seed,seat)\n  local r=D.mod_codec.rng(D.mod_codec.seed_for(seed,0,0,seat*7+1))\n  local normal,keys=set_ids(D,'normal'),set_ids(D,'keystone')\n  assert(#normal>=3 and #keys>=1,'no online-safe records to start a set from')\n  return normal[math.floor(r()*#normal)+1],keys[math.floor(r()*#keys)+1]\n end\n -- Three distinct offers for a seat at a game: online-safe normal records, those already at the top tier last.\n function P.set_offers(D,seed,game,seat,eq)\n  local r=D.mod_codec.rng(D.mod_codec.seed_for(seed,game,0,seat*7+3))\n  local pool=set_ids(D,'normal');local fresh,full={},{}\n  for _,id in ipairs(pool) do local t=eq and eq[id] or 0;if type(t)~='number' then t=0 end;if t>=P.set.max_tier then full[#full+1]=id else fresh[#fresh+1]=id end end\n  local out={}\n  while #out<P.set.offers do\n   local from=#fresh>0 and fresh or full;assert(#from>0,'offer pool empty')\n   local i=math.floor(r()*#from)+1;out[#out+1]=table.remove(from,i)\n  end\n  return out\n end\n -- The build after a pick: the offered record at tier 1, or one tier up if it is held; keep (3) or anything outside the offer changes nothing.\n function P.set_apply(eq,offers,pick)\n  local out={};for k,v in pairs(eq) do out[k]=v end\n  local id=offers[(pick or P.set.keep)+1];if not id or pick==P.set.keep then return out end\n  local t=out[id];out[id]=math.min(P.set.max_tier,(type(t)=='number' and t or 0)+1)\n  return out\n end\n -- The build of a seat at the start of `game` (1 = the starters). picks[g] = {[1]=host's pick,[2]=guest's pick} for g = 2..game.\n function P.set_build(D,seed,game,seat,picks)\n  local starter,key=P.set_starter(D,seed,seat);local eq={[starter]=1,[key]=1}\n  for g=2,game do\n   local pick=picks and picks[g] and picks[g][seat]\n   if pick==nil then pick=0 end -- a missing pick is the deterministic default: the first offer\n   eq=P.set_apply(eq,P.set_offers(D,seed,g,seat,eq),pick)\n  end\n  return eq,{}\n end\n -- Everything a client stages for the next game: both seats' records and passive ops. Returns {[seat]={record=,digest=,ops=,build=}}.\n function P.set_stage(D,seed,game,picks)\n  local out={}\n  for seat=1,2 do\n   local eq,imp=P.set_build(D,seed,game,seat,picks)\n   local record,digest=D.mod_codec.build_record({seed=seed,game=game,loop=0,port=seat},eq,imp)\n   local engine=D.mod_engine.new(seed,D.mod_pool);engine:set_build(seat,eq,imp)\n   out[seat]={record=record,digest=digest,ops=engine:passive_ops(seat,seat),build=eq}\n  end\n  return out\n end\n return P\nend\n", "@envoy/mod_progression.lua", "t"))()(envoy)
envoy.mod_tuning = assert(load("-- The named tuning values of the Envoy mod, in one table, with two presets.\n--   current  : how the mod behaved before the synergy work (the default for every value that is the owner's taste).\n--   proposed : the values the synergy analysis (_research/envoy-synergy-analysis-2026-10-05.md) suggests. `envoy tuning proposed` switches them on\n--              for a run, `envoy tuning current` back; `envoy tuning` lists every value with both columns.\n-- Values here are DATA read by the rule layer (budget, schema, loot), never state that only Lua knows: a preset is applied by the console on\n-- every peer alike (netplay would carry it in the lobby rules). Presentation values (T.fx) are per peer.\nreturn function(D)\n local T={rev=0}\n -- name -> {current, proposed, what it does}\n T.table={\n  strength={'v2','v2','Build strength formula: v2 counts a record for what it does given what the build feeds it; v1 is the old additive number.'},\n  payoff_scale={1,2.5,'Multiplier on the payoff drives of a chain (Pyre, Cinder, Shatter launch/damage bonus; Brittle and Malice curse bonus). Analysis: +5% of total damage is not felt; aim +20..30% on the status uptime.'},\n  plague_scale={1,.5,'Multiplier on the burn damage Plague Bearer applies to the target. Analysis: dealt per minute x2.6 with it; Smasher\\'s Creed measures +31%.'},\n  min_depth_cap={0,4,'Technique and crit drives never roll before this effective depth (0 = their own min_depth, 5 to 8). Analysis: technique crit completes in 4% of 12-stage runs.'},\n  connect_offers={1,1,'1: when none of the offered drives (or keystones) connects to anything held, one offer is swapped for a partner of a held piece (seeded).'},\n }\n T.names={'strength','payoff_scale','plague_scale','min_depth_cap','connect_offers'}\n T.values={};T.preset_name='current'\n local function reset() for _,n in ipairs(T.names) do T.values[n]=T.table[n][1] end end\n reset()\n -- strength v2 and connecting offers are the data-supported changes, so they are on in both columns; the three taste values differ.\n function T.get(name) return T.values[name] end\n function T.set(name,value)\n  assert(T.table[name],'unknown tuning value '..tostring(name))\n  if name=='strength' then assert(value=='v1' or value=='v2','strength is v1 or v2') else value=tonumber(value);assert(value and value==value and value>=0 and value<=64,'a number 0..64 is required') end\n  if T.values[name]~=value then T.values[name]=value;T.rev=T.rev+1 end\n  T.preset_name='custom'\n end\n function T.preset(name)\n  assert(name=='current' or name=='proposed','preset is current or proposed')\n  local col=name=='current' and 1 or 2\n  for _,n in ipairs(T.names) do local v=T.table[n][col];if T.values[n]~=v then T.values[n]=v;T.rev=T.rev+1 end end\n  T.preset_name=name\n end\n -- The payoff drives of the chains and the amount a status effect of a record is scaled by.\n T.payoff_versus={pyre=true,cinder=true,shatter=true}\n T.payoff_curse={brittle=true,malice=true}\n -- Factor on a versus-status ratio delta (S.ratio): only the payoff drives.\n function T.ratio_scale(m) if m and T.payoff_versus[m.id] then return T.values.payoff_scale end;return 1 end\n -- Factor on a status effect's amount (engine apply and budget agree through this one function).\n function T.amount_scale(m,e)\n  if not m then return 1 end\n  if T.payoff_curse[m.id] and e.status=='curse' then return T.values.payoff_scale end\n  if m.id=='plague_bearer' and e.status=='burn' and e.subject=='target' then return T.values.plague_scale end\n  return 1\n end\n -- The minimum depth a record rolls at now; validation accepts the lower of the two presets, so a drive rolled under `proposed` stays valid after `current`.\n function T.min_depth(m)\n  local d=m.min_depth;if not d then return nil end\n  local cap=T.values.min_depth_cap;if cap and cap>0 then d=math.min(d,cap) end\n  return d\n end\n function T.min_depth_floor(m)\n  local d=m.min_depth;if not d then return nil end\n  local cap=T.table.min_depth_cap[2];if cap and cap>0 then d=math.min(d,cap) end\n  return d\n end\n function T.lines()\n  local out={}\n  for _,n in ipairs(T.names) do local r=T.table[n];out[#out+1]=('%-14s now %-6s | current %-5s | proposed %-5s | %s'):format(n,tostring(T.values[n]),tostring(r[1]),tostring(r[2]),r[3]) end\n  return out\n end\n -- Presentation layers (per peer, optional one by one). `intensity` scales every synergy visual 0..1.\n -- THE DEVELOPER OVERLAY (off by default, mod side): one predicate gates every developer-only figure and message: the strength and depth\n -- text on the build strip, the strip's flash text, the opponent-strength figure, the mod's error and teaching toasts (always logged, shown only\n -- with it on), the Modifier LAB text box and the Drive LAB card. `envoy devui on|off` sets it; the ENVOY_DEVUI environment flag ('1' or 'on')\n -- is the default where the mod can read it (nothing here asks the engine for anything).\n local env_on=false\n do local ok,v=pcall(function() return os and os.getenv and os.getenv('ENVOY_DEVUI') end);env_on=ok and (v=='1' or v=='on') end\n T.dev_flag=nil\n function T.dev_ui() if T.dev_flag~=nil then return T.dev_flag end;return env_on end\n function T.set_dev_ui(v) T.dev_flag=v and true or false;T.rev=T.rev+0;return T.dev_flag end\n T.fx={intensity=1,grid_links=true,grid_banner=true,offer_marks=true,chain=true,hud=true,surface=true,announce=true,nameplate=true}\n T.fx_names={'grid_links','grid_banner','offer_marks','chain','hud','surface','announce','nameplate'}\n return T\nend\n", "@envoy/mod_tuning.lua", "t"))()(envoy)
envoy.fighters = assert(load("-- The fighters a run can be played as: the retail roster, and any Geno-defined fighter the mod folder lists in `missions/fighters.txt` (gd.mod_read reads only under missions/)\n-- (the engine has no call that lists mounted Geno fighters, so the folder that mounts one says so: one `geno:<name>  <label>`\n-- line per fighter, `#` comments). A token the engine would refuse is refused here, plainly, before a scene is launched.\nreturn function(D)\n local F={}\n F.retail={}\n for name in ('fox falco mario luigi drmario peach bowser donkey captain ganondorf link younglink zelda sheik samus yoshi kirby pikachu pichu jigglypuff mewtwo ness marth roy iceclimbers gamewatch'):gmatch('%S+') do F.retail[#F.retail+1]=name end\n F.retail_set={};for _,n in ipairs(F.retail) do F.retail_set[n]=true end\n -- The extra (Geno) fighters: {id='geno:vanilla-hero',label='Vanilla Hero'} in file order.\n function F.parse(text)\n  local out,seen={},{}\n  for line in tostring(text or ''):gmatch('[^\\r\\n]+') do\n   line=line:gsub('#.*$','')\n   local id,label=line:match('^%s*(geno:[%w_%-]+)%s*(.-)%s*$')\n   if id and not seen[id] and #id<=80 then seen[id]=true;out[#out+1]={id=id,label=(label~='' and label or id:sub(6))} end\n  end\n  return out\n end\n function F.extras(g)\n  if not (g and g.mod_read) then return {} end\n  local ok,text=pcall(g.mod_read,'missions/fighters.txt')\n  if not ok or type(text)~='string' then return {} end\n  return F.parse(text)\n end\n -- The menu's list: retail names, then the extras as {id,label} rows.\n function F.menu(g)\n  local list={};for _,n in ipairs(F.retail) do list[#list+1]=n end\n  for _,e in ipairs(F.extras(g)) do list[#list+1]={id=e.id,label=e.label} end\n  return list\n end\n -- A token from a command: the id, or nil and a plain reason.\n function F.resolve(g,token)\n  token=tostring(token or ''):lower()\n  if token=='' then return nil,'no fighter given' end\n  if F.retail_set[token] then return token end\n  for _,e in ipairs(F.extras(g)) do if e.id:lower()==token then return e.id end end\n  if token:match('^geno:') then return nil,(\"Geno fighter '\"..token..\"' is not mounted here (add it to this mod's fighters.txt)\") end\n  return nil,(\"unknown fighter '\"..token..\"': use one of \"..table.concat(F.retail,', ')..' or a geno:<name> listed in missions/fighters.txt')\n end\n -- A name for a nameplate: the engine's own unless it only says \"character 127\" (a Geno fighter's number), then the label the\n -- fighter list gives (the only extra fighter's, else a plain \"Custom fighter\").\n function F.plate(g,engine_name,label)\n  local n=tostring(engine_name or '')\n  if n=='' or n=='nil' or n:match('^character %d+$') then\n   if label then return label end\n   local extras=F.extras(g);if #extras==1 then return extras[1].label end\n   return 'Custom fighter'\n  end\n  return n\n end\n return F\nend\n", "@envoy/fighters.lua", "t"))()(envoy)
envoy.mod_echo = assert(load("-- Gameplay descriptions contain scalar delays; presentation consumes the same ages.\nreturn function(D)\n local X={moves={any=true,aerial=true,nair=true,fair=true,bair=true,uair=true,dair=true,unknown=true,grab=true,jab=true,tilt=true,smash=true,special=true,dash_attack=true,throw=true}}\n local function integer(n,lo,hi)assert(type(n)=='number' and n%1==0 and n>=lo and n<=hi,'bounded echo integer required');return n end\n function X.description(e)\n  local count=integer(e.copies or 3,1,3);local delay=integer(e.delay or 8,1,20);local armed={}\n  for _,i in ipairs(e.slots or {})do integer(i,1,count);assert(not armed[i],'duplicate echo copy');armed[i]=true end\n  local out={copies={},visual={}}\n  for i=1,count do local c={age=i*delay};out.copies[i]=c\n   if armed[i]then\n    assert(type(e.damage)=='number' and e.damage==e.damage and e.damage>=.1 and e.damage<=4,'echo damage scale out of bounds')\n    assert(type(e.knockback or 1)=='number' and (e.knockback or 1)>=.1 and (e.knockback or 1)<=4,'echo knockback scale out of bounds')\n    local match=e.match or {move='any'};assert(X.moves[match.move or 'any'],'unknown echo move')\n    c.echo={delay=c.age,match=D.mod_codec and D.mod_codec.decode(D.mod_codec.encode(match)) or {move=match.move},damage=e.damage,knockback=e.knockback or 1,once_per_move=e.once_per_move~=false,element=e.element}\n   end\n  end;return out\n end\n function X.resolve(e,m,tier)\n  local S=D.mod_schema;local n=math.min(3,math.max(1,math.floor(S.resolve(e.copies or 3,m,tier))))\n  local slots={};for _,i in ipairs(e.slots or {1,2,3})do if i<=n then slots[#slots+1]=i end end\n  return X.description{copies=n,slots=slots,delay=S.resolve(e.delay or 8,m,tier),match=e.match,damage=math.min(4,math.max(.1,S.resolve(e.damage or .4,m,tier))),knockback=math.min(4,math.max(.1,S.resolve(e.knockback or 1,m,tier))),once_per_move=e.once_per_move,element=e.element}\n end\n function X.engine(engine,p)\n  local out={copies={},rules={},visual={}};local by_age,by_rule={},{}\n  for _,m in ipairs(engine.list)do local tier=(engine.equipped[p] or {})[m.id]\n   if tier then for _,e in ipairs(m.effects)do if e.op=='echo' and (not e.status or engine:status(p,e.status))then\n    for _,instance in ipairs(D.mod_schema.instances(tier))do local d=X.resolve(e,m,instance)\n     for _,c in ipairs(d.copies)do\n      if not by_age[c.age]then by_age[c.age]={age=c.age};out.copies[#out.copies+1]=by_age[c.age]end\n      if c.echo then\n       local key=tostring(c.age)..D.mod_codec.encode(c.echo.match)..tostring(c.echo.element)..tostring(c.echo.once_per_move);local old=by_rule[key]\n       if old then old.damage=old.damage+c.echo.damage;old.knockback=math.max(old.knockback,c.echo.knockback)\n       else by_rule[key]=c.echo;out.rules[#out.rules+1]=c.echo end\n       by_age[c.age].echo=by_age[c.age].echo or by_rule[key]\n      end\n     end\n    end\n   end end end\n  end\n  for _,r in ipairs(out.rules)do r.damage=math.min(4,r.damage) end\n  table.sort(out.copies,function(a,b)return a.age<b.age end);table.sort(out.rules,function(a,b)if a.delay~=b.delay then return a.delay<b.delay end;return D.mod_codec.encode(a.match)<D.mod_codec.encode(b.match)end)\n  assert(#out.copies<=3 and #out.rules<=8,'echo capacity exceeded');return out\n end\n function X.records()\n  local function r(id,label,kind,copies,damage,cost,live)\n   local effects={{op='echo',copies=copies,delay=8,damage=damage,knockback=1,match={move=kind=='normal' and 'aerial' or 'any'},once_per_move=true}}\n   if live then effects[#effects+1]={op='value',key='damage_dealt',value=live}end\n   return {id=id,label=label,kind=kind,cost=cost,tags={'aerial','damage'},trigger='equip',conditions={},effects=effects,tiers={{copies=1},{copies=2},{copies=3}},stacking={max=1},text='Historical '..(kind=='normal' and 'aerial' or 'all move')..' hitboxes repeat at '..tostring(damage*100)..'% damage; higher tiers arm more copies.',visual={look='momentum',hue=.72,strength=.45,priority=20},families=live and {'echo','damage_dealt'} or {'echo'},affix=kind=='normal' and 'suffix' or nil,group=kind=='normal' and id or nil,weight=kind=='normal' and 100 or nil,fixed_colour=kind=='unique' and 'purple' or nil}\n  end\n  local trail=r('trailing','Trailing','normal',3,.4);trail.affix='prefix';trail.tags={'hasted'};trail.effects[1].slots={};trail.effects[1].status='haste';trail.text='While you have Haste, leave three historical afterimages.';trail.min_depth=5   -- a payoff: it needs Haste from elsewhere\n  return {trail,r('echoes','Echoes','normal','$copies',.4),r('echo_heart','Echo Heart','unique',3,.4,'All attack damage, including echoes, is 25% lower.',.75)}\n end\n return X\nend\n", "@envoy/mod_echo.lua", "t"))()(envoy)
envoy.mod_registry = assert(load("-- One registry of effect descriptors. Schema (field lists), budget (family coverage) and the\n-- checkpoint compiler (which journal operation commits an effect) all read it, so a field, a bound or an\n-- executor cannot be declared in one place and be missing from another.\nreturn function(D)\n local R={}\n local function set(words) local out={};for w in words:gmatch('%S+') do out[w]=true end;return out end\n -- Rule effects (the `effects` list of a modifier record). `journal` names the native sim_commit\n -- operation that carries the effect after a frame; 'lua_state' effects live in the exported\n -- checkpoint blob and are restored by the snapshot, never replayed through a native setter.\n R.effects={\n  status={fields=set('op status subject duration amount max refresh when'),journal='lua_state'},\n  stacks={fields=set('op status subject duration amount max refresh when'),journal='lua_state'},\n  remove_status={fields=set('op status subject when count'),journal='lua_state'},\n  value={fields=set('op key value when'),journal='fighter_mod'},\n  heal={fields=set('op amount subject when'),journal='damage'},\n  damage={fields=set('op amount subject when'),journal='damage'},\n  emit={fields=set('op event subject tag when'),journal='lua_state'},\n  echo={fields=set('op copies slots delay match damage knockback element once_per_move status'),journal='echoes'},\n  clank_damage={fields=set('op subject'),journal='lua_state'},\n  convert={fields=set('op match change'),journal='hit_rules'},\n  ['versus-status']={fields=set('op status match change'),journal='hit_rules'},\n  -- Technique effects (native timed effects with their own expiry, from a trigger; or passive caps/crit from equip).\n  armor={fields=set('op type value frames direction subject when'),journal='fighter_armor'},\n  intangible={fields=set('op frames subject when'),journal='fighter_effect'},\n  air_jumps={fields=set('op count'),journal='fighter_caps'},\n  restrict={fields=set('op forbid'),journal='fighter_caps'},\n  -- No sim_commit operation exists for an interrupt window: it is a direct gd.fighter_interrupt on the event frame (not journalled).\n  interrupt={fields=set('op frames exits guard restore_jumps subject when'),journal='direct'},\n  crit={fields=set('op chance multiplier multiplier_max launch tag min_percent status'),journal='crit'},\n  crit_next={fields=set('op count multiplier subject when'),journal='crit'},\n  -- Apply a status to the nearest OTHER opponent of the victim (Conductor's Shock chain). Lua-side target choice from the frame's positions.\n  chain_status={fields=set('op status duration amount max refresh when'),journal='lua_state'},\n }\n -- Journal operations the native checkpoint admits (gw_script_sim_state.inc). `key` is the entity field\n -- ('port' 1..6 for the first four, 'entity' 1..12 for the capability writers). Bounds mirror the C\n -- parser and the gd.* setter each one calls, so a rule is refused here before the native refusal.\n R.operations={\n  fighter_mod={key='port'},damage={key='port',fields={value={0,999}}},hit_rules={key='port'},echoes={key='port'},\n  fighter_caps={key='entity',fields={values={table=true}}},\n  fighter_effect={key='entity',fields={effect={enum={'intangible','invincible','metal','size'}},value={0,4},frames={0,3600,integer=true}}},\n  fighter_armour={key='entity',fields={damage={0,1000},knockback={0,1000}}},\n  fighter_armor={key='entity',fields={type={enum={'knockback','damage_threshold','knockback_threshold','super','hit_count','damage_pool'}},value={0,1000},frames={0,36000,integer=true},state={-1,65535,integer=true},from={-1,100000},to={-1,100000},direction={enum={'any','front','back'}},clear={boolean=true}}},\n  shock={key='entity',fields={frames={1,3600,integer=true},charges={1,8,integer=true},hitstun={1,4},bonus={0,120,integer=true},stack={boolean=true},clear={boolean=true}}},\n  crit={key='entity',fields={slot={enum={'default','jab','dash_attack','tilt','smash','aerial','grab','throw','special','projectile'}},begin={boolean=true},release={boolean=true},chance={0,1},multiplier={1,16},multiplier_max={1,16},launch={1,4},min_percent={0,999},force={0,255,integer=true}}},\n  timed_status={key='entity',fields={channel={1,4,integer=true},value={-100000,100000},frames={0,3600,integer=true}}},\n }\n function R.field_set(op) return assert(R.effects[op],'unsupported effect (no connecting-hit mutation)').fields end\n function R.journal(op) return assert(R.effects[op],'unsupported effect').journal end\n -- Validates one journal operation table the way the native parser will. Returns the table.\n function R.operation(o)\n  assert(type(o)=='table','operation table required');local d=assert(R.operations[o.op],'unsupported journal operation')\n  local limit=d.key=='entity' and 12 or 6;local at=o[d.key]\n  assert(type(at)=='number' and at%1==0 and at>=1 and at<=limit,d.key..' 1..'..limit..' required')\n  for k,v in pairs(o) do if k~='op' and k~=d.key and not (d.key=='port' and (k=='values' or k=='rules' or k=='status_bits' or k=='sub' or k=='value' or k=='copies' or k=='slots')) then\n   local f=d.fields and d.fields[k];assert(f,'unknown field '..tostring(k)..' for '..o.op)\n   if f.enum then local ok;for _,n in ipairs(f.enum) do ok=ok or n==v end;assert(ok,'invalid '..k)\n   elseif f.boolean then assert(type(v)=='boolean','boolean required for '..k)\n   elseif f.table then assert(type(v)=='table','table required for '..k)\n   else assert(type(v)=='number' and v==v and v>=f[1] and v<=f[2] and (not f.integer or v%1==0),k..' out of bounds') end\n  end end\n  return o\n end\n return R\nend\n", "@envoy/mod_registry.lua", "t"))()(envoy)
envoy.mod_status = assert(load("-- The one declaration of the named statuses. Their mirrored hit-rule bits, event tags, loot-budget\n-- contributions, fighter-value effects and looks are all read from here, so a status is added or\n-- retuned in one place. The live instances (stacks, origin, expiry) stay in mod_engine.statuses; the\n-- native numeric timed channels (gd.fighter_timed_status) are a separate, private mechanism.\n-- Names are mechanics, not marketing: 'guarded' is a percent resistance, not reaction armour.\n--\n-- THE WORDS (readability split, 2026-10-05). Five core statuses everyone learns (Burning, Chilled, Haste, Guarded, Marked), one\n-- counter (Momentum: a stored number, not a status look) and one private status (Shock, the electric theme's own). Each has ONE word\n-- in every text a player reads; its numbers live in the glossary below, not in every sentence. The internal ids never change\n-- (`curse` is still the id of Marked, so saves and build records stay valid). `label` is the word; `puts` says it on a target.\nreturn function(D)\n local M={}\n M.defs={\n  {name='burn',bit=1,tag='burning',look='burn',implemented=true,label='Burning',puts='sets the target Burning',gloss='Burning: the target takes damage every second.',core=true,\n   budget=function(amount,max) return {sustain=amount*(max or 1)} end},\n  -- Shock is native now (gd.shock, journal op `shock`): the target's next hit taken has more hitstun. The host mirrors the Lua\n  -- status into that native state. It has no hit-rule bit (versus-status rules cannot test it), so it stays out of M.bits.\n  {name='shock',bit=2,tag='shocked',look='shock',implemented=true,no_bit=true,label='Shock',puts='Shocks the target',private=true,\n   gloss='Shock: the target\\'s next hit taken stuns longer (private to the electric theme).',\n   budget=function() return {launch_taken=.06} end},\n  {name='chill',bit=4,tag='chilled',look='chill',implemented=true,label='Chilled',puts='Chills the target',gloss='Chilled: 20% slower.',core=true,\n   budget=function() return {speed=-.2} end,values={run_speed=-.2,air_speed=-.2}},\n  {name='curse',bit=8,tag='cursed',look='curse',implemented=true,label='Marked',puts='Marks the target',gloss='Marked: your later hits launch the target farther.',core=true,\n   budget=function(amount) return {launch_taken=amount} end,values=function(v) return {knockback_taken=v.amount} end},\n  {name='haste',bit=16,tag='hasted',look='haste',implemented=true,label='Haste',puts='gives you Haste',gloss='Haste: 20% faster run and air speed.',core=true,\n   budget=function() return {speed=.2} end,values={run_speed=.2,air_speed=.2}},\n  {name='guarded',bit=32,tag='guarded',look='guarded',implemented=true,label='Guarded',puts='gives you Guarded',gloss='Guarded: 25% less damage and 15% less launch taken.',core=true,\n   budget=function() return {damage_taken=-.25,launch_taken=-.15} end,values={damage_taken=-.25,knockback_taken=-.15}},\n  -- Momentum is a COUNTER: up to 5 stored stacks that a landing rule spends. It keeps its engine slot (the surface channel still has a\n  -- lane for it) but it is not one of the five statuses a player learns; the later visual pass draws it as 1 to 5 orbs from `counter()`.\n  {name='momentum',bit=64,tag='momentum',look='momentum',implemented=true,label='Momentum',puts='gives you Momentum',counter=true,\n   gloss='Momentum: a counter, up to 5, spent when you land.',\n   budget=function(_,max) return {momentum=max or 5} end},\n }\n M.order,M.by_name,M.bits,M.tags,M.implemented={},{},{},{},{}\n M.core,M.counter_name,M.private_name={},'momentum','shock'\n for _,d in ipairs(M.defs) do\n  M.order[#M.order+1]=d.name;M.by_name[d.name]=d\n  if d.core then M.core[#M.core+1]=d.name end\n  if d.implemented then if not d.no_bit then M.bits[d.name]=d.bit end;M.tags[d.name]=d.tag;M.implemented[d.name]=true end\n end\n -- The one word for a status in player-read text.\n function M.label(name) local d=M.by_name[name];return d and d.label or tostring(name) end\n -- Words a text may never use for these (the old synonyms): the tests scan every line a player reads for them.\n M.banned_words={'Curse','Cursed','curse','cursed','moving fast','speed boost','Hasted','hasted'}\n -- The glossary: one line per word a player learns, the crit rule included (a crit is x1.5 unless a piece says otherwise).\n function M.glossary()\n  local out={}\n  for _,name in ipairs({'burn','chill','haste','guarded','curse','momentum','shock'}) do out[#out+1]=M.by_name[name].gloss end\n  out[#out+1]='Crit: a hit that deals x1.5 damage.'\n  return out\n end\n function M.budget(name,amount,max)\n  local d=M.by_name[name];assert(d and d.budget,'unbudgeted status');return d.budget(amount,max)\n end\n -- Fighter-value keys a live status contributes (v is the engine's instance record).\n function M.values(name,v)\n  local d=M.by_name[name];local x=d and d.values\n  if type(x)=='function' then return x(v) end\n  return x or {}\n end\n return M\nend\n", "@envoy/mod_status.lua", "t"))()(envoy)
envoy.mod_skill = assert(load("-- The one declaration of the technique (\"skill\") vocabulary: which engine skill events the modifier engine\n-- accepts as triggers, whether each was verified in the game, who can perform it, the plain words for it and\n-- the colour of the afterimage a status earned by it shows. Pure data; schema, host, text and the earned\n-- afterimage module all read it, so a technique is declared once.\n--\n-- Presentation table (ONE meaning per output):\n--   surface treatment  = a status you have (equipped rules and statuses)\n--   earned afterimage  = a status you EARNED through technique, only while it lasts, coloured by its cause\n--   tracer             = THIS hit carries something extra (a crit)\n--   particle burst / post pass = a moment (a crit, a keystone), never continuous\nreturn function(D)\n local M={}\n -- kind -> {verified, cpu, words, cause, noun}\n --  verified: seen firing in the game by the engine lane (docs/scripting.md \"Skill events\"); false = available but flagged\n --  cpu: whether a CPU opponent performs it. 'live' = hits and knockdowns happen anyway; 'driven' = the retail AI never does it but foe_driver.lua\n --       performs it for an opponent whose build rewards it: through the engine assist gd.cpu_assist (fight mode, no plan reset) at a\n --       skill that grows with depth, or, on an exe without the assist, a fight -> script -> fight switch (perfect shield lands ~37% of presses);\n --       'maybe' = retail AI does it at some levels (unmeasured); 'dead' = retail AI never performs it, so an opponent's roll is inert\n --  cause: afterimage colour family; the status the technique grants shows that colour while it lasts\n M.kinds={\n  lcancel={verified=true,cpu='driven',words='L-cancel a landing',cause='lcancel'},\n  lcancel_hit={verified=true,cpu='driven',words='L-cancel a landing after the aerial hit',cause='lcancel'},\n  lcancel_miss={verified=true,cpu='maybe',words='miss an L-cancel',cause='miss'},\n  wavedash={verified=true,cpu='driven',words='wavedash',cause='wave'},\n  perfect_shield={verified=true,cpu='driven',words='perfect shield',cause='shield',legacy=true},\n  tech={verified=true,cpu='driven',words='tech',cause='shield'},\n  tech_miss={verified=true,cpu='live',words='miss a tech',cause='miss'},\n  short_hop={verified=true,cpu='maybe',words='short hop',cause='move'},\n  fast_fall={verified=true,cpu='driven',words='fast fall',cause='move'},\n  dash_dance={verified=true,cpu='dead',words='dash dance',cause='move'},\n  jump_cancel_grab={verified=true,cpu='dead',words='jump-cancel a grab',cause='combo'},\n  combo={verified=true,cpu='live',words='land a hit inside a combo',cause='combo'},\n  combo_end={verified=true,cpu='live',words='finish a combo',cause='combo'},\n  -- Available, flagged: seen in the build but not confirmed in play (engine lane report), or only partly measured.\n  waveland={verified=false,cpu='dead',words='waveland',cause='wave'},\n  ledge_dash={verified=false,cpu='dead',words='ledge dash',cause='wave'},\n  sdi={verified=false,cpu='maybe',words='smash DI during hitlag',cause='shield'},\n  shield_drop={verified=false,cpu='maybe',words='drop your shield',cause='shield'},\n  auto_cancel={verified=false,cpu='maybe',words='auto-cancel a landing',cause='lcancel'},\n  air_dodge={verified=false,cpu='driven',words='air dodge',cause='wave'},\n  full_hop={verified=false,cpu='maybe',words='full hop',cause='move'},\n  jump_cancel_usmash={verified=false,cpu='dead',words='jump-cancel an up smash',cause='combo'},\n  -- Not a technique: a consequence the engine reports (crit decision, armour absorbing a hit).\n  crit={verified=true,cpu='live',words='land a crit',cause='crit',consequence=true},\n  armor={verified=true,cpu='live',words='have your armour absorb a hit',cause='shield',consequence=true},\n }\n M.order={'lcancel','lcancel_hit','lcancel_miss','wavedash','perfect_shield','tech','tech_miss','short_hop','fast_fall','dash_dance','jump_cancel_grab','combo','combo_end','waveland','ledge_dash','sdi','shield_drop','auto_cancel','air_dodge','full_hop','jump_cancel_usmash','crit','armor'}\n -- Engine hooks that deliver each kind (on_<kind>); perfect_shield keeps the retail-signature hook.\n function M.is_skill(kind) return M.kinds[kind]~=nil and not M.kinds[kind].consequence end\n function M.is_technique(kind) return M.is_skill(kind) end\n function M.verified(kind) return M.kinds[kind] and M.kinds[kind].verified==true end\n function M.cpu(kind) return M.kinds[kind] and M.kinds[kind].cpu or 'live' end\n -- Afterimage colour by cause (tint, tail), 0..1 RGBA. One meaning each; a status's afterimage is its cause's colour.\n M.cause={\n  lcancel={name='blue',words='blue (speed from an L-cancel)',index=1,tint={.15,.45,1,.8},tail={.05,.1,.6,0}},\n  shield={name='teal',words='teal (a defence earned by shield or tech)',index=2,tint={.1,.9,.8,.8},tail={0,.35,.45,0}},\n  wave={name='gold',words='gold (a wave technique: armour and speed)',index=3,tint={1,.78,.25,.8},tail={.55,.3,0,0}},\n  combo={name='red',words='red (an offensive state from combos and cancels)',index=4,tint={1,.3,.25,.8},tail={.5,.05,.1,0}},\n  move={name='white',words='white (a movement technique)',index=5,tint={.9,.95,1,.75},tail={.4,.45,.6,0}},\n  miss={name='violet',words='violet (a state paid for a miss)',index=6,tint={.7,.35,1,.75},tail={.25,.05,.45,0}},\n  crit={name='orange',words='orange (a crit)',index=7,tint={1,.55,.15,.85},tail={.5,.15,0,0}},\n }\n function M.cause_of(kind) local k=M.kinds[kind];return k and k.cause or nil end\n -- How long an earned afterimage may last at most (frames): a presentation bound, never longer than the status.\n M.max_frames=600\n -- Plain words of a trigger for a sentence (\"When you L-cancel a landing after the aerial hit, ...\").\n function M.words(kind,conditions)\n  local k=M.kinds[kind];if not k then return nil end\n  local out=k.words\n  for _,c in ipairs(conditions or {}) do\n   if c.combo_at_least then\n    if kind=='combo' then out='land a hit that makes a combo of at least '..tostring(c.combo_at_least) elseif kind=='combo_end' then out='finish a combo of at least '..tostring(c.combo_at_least) end\n   end\n  end\n  return out\n end\n return M\nend\n", "@envoy/mod_skill.lua", "t"))()(envoy)
envoy.mod_schema = assert(load("-- Only a shared vocabulary can express rules. No move IDs or modifier references.\nreturn function(D)\n local S={}\n local function set(words) local out={};for w in words:gmatch('%S+') do out[w]=true end;return out end\n S.tags=set('jab tilt smash aerial special grab throw projectile dash_attack grounded airborne normal fire electric ice darkness burning shocked chilled cursed hasted guarded momentum damage healing unique keystone technique critical')\n S.events=set('equip hit_dealt hit_taken ko_dealt stock_lost shield_hit perfect_shield clank jump air_jump landing ledge_grab grab throw taunt item_pickup stage_start interval status_applied status_removed stacks_changed')\n -- Technique triggers come from the engine's skill events (mod_skill declares them, verified or flagged), plus the crit and armour reports.\n for kind in pairs(D.mod_skill.kinds) do S.events[kind]=true end\n S.statuses=D.mod_status.implemented -- Shock's hitstun effect awaits safe hit mutation (see mod_status).\n S.values=set('damage_dealt damage_taken run_speed air_speed shield_max jump_height air_jump_height knockback_taken fall_speed weight shield_regen status_duration')\n S.status_bits=D.mod_status.bits\n S.hit_moves=set('any unknown jab dash_attack tilt smash aerial special grab throw projectile')\n S.elements=set('normal fire electric ice darkness')\n local record=set('id label kind cost tags tiers trigger interval conditions also effects stacking text visual affix group weight fixed_colour families notes min_depth')\n local cond=set('tag self_status target_status status self_damage_above self_damage_below target_damage_above grounded airborne last_stock recently stage_kind combo_at_least combo_damage_above hit aerial direction strength_above armor_result air_frames_above aerial_hit')\n -- Effect field lists come from the one effect registry (mod_registry), shared with budget and the checkpoint compiler.\n local fields=setmetatable({},{__index=function(_,op) local d=D.mod_registry.effects[op];return d and d.fields end})\n local function keys(t,allowed) assert(type(t)=='table' and not getmetatable(t),'plain record required');for k in pairs(t) do assert(allowed[k],'unsupported record field '..tostring(k)) end end\n local function number(v,m)\n  if type(v)=='string' then assert(v:match('^%$[a-z_]+$'),'only tier references allowed');for _,tier in ipairs(m.tiers) do assert(type(tier[v:sub(2)])=='number','missing tier value') end\n  else assert(type(v)=='number' and v==v and math.abs(v)<=100000,'finite bounded value required') end\n end\n local function array(t,minimum,maximum)\n  assert(type(t)=='table' and not getmetatable(t),'dense array required');local n=0\n  for k in pairs(t) do assert(type(k)=='number' and k%1==0 and k>=1,'dense array required');n=n+1 end\n  assert(n==#t and n>=minimum and n<=maximum,'array size out of bounds');for i=1,n do assert(t[i]~=nil,'dense array required') end\n end\n local function range(v,m,lo,hi,integer)\n  number(v,m);for i=1,#m.tiers do local x=type(v)=='string' and m.tiers[i][v:sub(2)] or v\n   assert(x>=lo and x<=hi and (not integer or x%1==0),'parameter out of bounds') end\n end\n  local function check_conditions(m,trigger,conditions)\n  array(conditions or {},0,8)\n  if trigger=='equip' then assert(#(conditions or {})==0,'passive equip conditions unsupported') end\n  for _,c in ipairs(conditions or {}) do keys(c,cond);for k,v in pairs(c) do\n   if k=='tag' then assert(S.tags[v],'condition tag must be vocabulary')\n   elseif k=='self_status' or k=='target_status' or k=='status' then assert(v=='any' or S.statuses[v],'unsupported status condition')\n   elseif k=='recently' then keys(v,set('event frames'));assert(S.events[v.event]);range(v.frames,m,1,3600,true)\n   elseif k=='stage_kind' then assert(set('battle team giant metal bonus boss')[v],'unsupported stage kind')\n   elseif k=='grounded' or k=='airborne' or k=='last_stock' or k=='hit' or k=='aerial_hit' then assert(type(v)=='boolean')\n    if k=='hit' or k=='aerial_hit' then assert(D.mod_skill.is_skill(trigger),'technique condition needs a technique trigger') end\n   elseif k=='combo_at_least' then assert(trigger=='combo' or trigger=='combo_end','combo condition needs a combo trigger');range(v,m,2,30,true)\n   elseif k=='combo_damage_above' then assert(trigger=='combo' or trigger=='combo_end','combo condition needs a combo trigger');range(v,m,0,999)\n   elseif k=='aerial' then assert(set('nair fair bair uair dair')[v] and D.mod_skill.is_skill(trigger),'unknown aerial')\n   elseif k=='direction' then assert(trigger=='tech' and set('in_place toward away wall ceiling')[v],'unknown tech direction')\n   elseif k=='strength_above' then assert(trigger=='crit');range(v,m,0,1)\n   elseif k=='armor_result' then assert(trigger=='armor' and (v=='absorbed' or v=='broke'),'armour result absorbed or broke')\n   elseif k=='air_frames_above' then assert(D.mod_skill.is_skill(trigger));range(v,m,0,600,true)\n   else number(v,m) end\n  end end\n  end\n function S.validate(m)\n  keys(m,record);assert(type(m.id)=='string' and m.id:match('^[a-z][a-z_]+$') and #m.id<=40,'invalid modifier id')\n  assert(type(m.label)=='string' and #m.label<=50 and type(m.text)=='string','label/text required')\n  assert(m.kind=='normal' or m.kind=='unique' or m.kind=='keystone','invalid rarity')\n  if m.kind~='normal' then assert(type(m.cost)=='string' and #m.cost>0,'rule-breaker needs explicit cost') end\n  if m.affix then assert(m.kind=='normal' and (m.affix=='prefix' or m.affix=='suffix'),'invalid affix');assert(type(m.group)=='string' and #m.group>0 and type(m.weight)=='number' and m.weight>0 and m.weight<100000,'invalid loot metadata') end\n  if m.fixed_colour then assert(m.kind=='unique' and set('red green blue yellow purple white')[m.fixed_colour],'invalid unique colour') end\n  if m.min_depth~=nil then assert(m.kind=='normal' and type(m.min_depth)=='number' and m.min_depth%1==0 and m.min_depth>=0 and m.min_depth<=100,'invalid minimum depth') end\n  if m.notes~=nil then assert(type(m.notes)=='string' and #m.notes<=240,'notes must be short text') end\n  array(m.tags,0,8);for _,tag in ipairs(m.tags) do assert(S.tags[tag],'tag must be vocabulary, never a move/modifier name') end\n  array(m.tiers,1,5)\n  for _,tier in ipairs(m.tiers) do assert(type(tier)=='table');for k,v in pairs(tier) do assert(type(k)=='string' and k:match('^[a-z_]+$'));number(v,m);assert(type(v)=='number','numeric tier required') end end\n  assert(S.events[m.trigger],'unsupported trigger')\n  if m.trigger=='interval' then range(m.interval,m,1,3600,true) else assert(m.interval==nil,'interval requires interval trigger') end\n  check_conditions(m,m.trigger,m.conditions)\n  if m.also~=nil then\n   array(m.also,1,3);for _,a in ipairs(m.also) do keys(a,set('trigger conditions'));assert(S.events[a.trigger] and a.trigger~='equip','an alternative trigger must be a real event');check_conditions(m,a.trigger,a.conditions) end\n   assert(m.trigger~='equip','an equip rule has no alternative triggers')\n  end\n  array(m.effects,1,8)\n  for _,e in ipairs(m.effects) do assert(fields[e.op],'unsupported effect (no connecting-hit mutation)');keys(e,fields[e.op])\n   if e.subject then assert(e.subject=='self' or e.subject=='target','unsupported effect subject') end\n   if e.when then assert(e.when==m.trigger,'effect event must match trigger') end\n   if e.op=='echo' then\n    assert(m.trigger=='equip','echo requires unconditional equip');range(e.copies or 3,m,1,3,true);range(e.delay or 12,m,1,20,true);range(e.damage or .4,m,.1,4);range(e.knockback or 1,m,.1,4)\n    if e.slots then array(e.slots,0,3);local seen={};for _,i in ipairs(e.slots)do assert(type(i)=='number' and i%1==0 and i>=1 and i<=3 and not seen[i],'invalid echo slots');seen[i]=true end end\n    keys(e.match or {},set('move element airborne'));assert(not e.match or not e.match.move or D.mod_echo.moves[e.match.move],'unknown echo move');assert(not e.match or not e.match.element or S.elements[e.match.element]);assert(not e.match or e.match.airborne==nil or type(e.match.airborne)=='boolean')\n    assert(e.element==nil or S.elements[e.element]);assert(e.once_per_move==nil or type(e.once_per_move)=='boolean');assert(e.status==nil or S.statuses[e.status])\n   elseif e.op=='convert' or e.op=='versus-status' then\n    assert(m.trigger=='equip','native hit rules require unconditional equip')\n    keys(e.match,set('move grounded element incoming'));assert(e.match.move==nil or S.hit_moves[e.match.move],'hit match must use vocabulary')\n    assert(e.match.element==nil or S.elements[e.match.element],'only ordinary original elements supported')\n    if e.match.grounded~=nil then assert(type(e.match.grounded)=='boolean') end\n    if e.match.incoming~=nil then assert(type(e.match.incoming)=='boolean') end\n    if e.op=='convert' then\n     assert(not e.match.incoming,'incoming rules cannot modify creation')\n     keys(e.change,set('element percent_damage launch damage knockback_growth knockback_base shield_damage hitstun'))\n     if e.change.element then assert(S.elements[e.change.element],'special element conversion refused') end\n    else\n     assert(e.match.incoming or e.status==nil or S.status_bits[e.status],'unknown native status')\n     if e.status then assert(S.status_bits[e.status],'unknown status') end\n     keys(e.change,set('percent_damage launch damage knockback_taken'))\n    end\n    assert(next(e.change),'native change required')\n    for k,v in pairs(e.change) do\n     if k=='shield_damage' then range(v,m,0,50,true) elseif k=='hitstun' then range(v,m,0,30,true)\n     elseif k=='percent_damage' then range(v,m,-1e9,1e9)\n     elseif k=='launch' then range(v,m,-1e9,1e9)\n     elseif k~='element' then range(v,m,.1,4) end\n    end\n   elseif e.op=='value' then assert(m.trigger=='equip' and S.values[e.key],'fighter values require unconditional equip');range(e.value,m,.1,4)\n   elseif e.op=='status' or e.op=='stacks' or e.op=='chain_status' then assert(m.trigger~='equip' and S.statuses[e.status],'unsupported status');if e.op=='chain_status' then assert(m.trigger=='hit_dealt','a status chain needs a hit trigger') end;range(e.duration,m,1,3600,true);range(e.amount or 1,m,0,100);assert(e.refresh=='refresh' or e.refresh=='extend' or e.refresh=='keep');assert(type(e.max)=='number' and e.max%1==0 and e.max>=1 and e.max<=8)\n   elseif e.op=='clank_damage' then assert(m.trigger=='clank' and e.subject=='target','clank damage requires opposing fighter')\n   elseif e.op=='remove_status' then assert(S.statuses[e.status]);if e.count~=nil then assert(type(e.count)=='number' and e.count%1==0 and e.count>=1 and e.count<=8,'remove count 1..8') end\n   elseif e.op=='emit' then assert(S.events[e.event] and S.tags[e.tag])\n   elseif e.op=='armor' or e.op=='intangible' or e.op=='interrupt' or e.op=='crit_next' then\n    -- Native timed effects (armour, intangibility, an interrupt window, a forced crit) run from a trigger and carry their own expiry.\n    assert(e.subject==nil or e.subject=='self','technique effects apply to yourself')\n    if e.op=='armor' then\n     local limits={super={30,nil},damage_threshold={12,300},knockback_threshold={40,300},hit_count={3,600},damage_pool={30,600}}\n     local lim=assert(limits[e.type],'unsupported armour type')\n     if e.frames==nil then assert(m.trigger=='equip' and e.type=='damage_threshold','only a threshold armour may be permanent, on an equip rule');range(e.value,m,1,10)\n     else assert(m.trigger~='equip','timed armour needs a trigger');range(e.frames,m,1,lim[2] or lim[1],true);if e.type=='super' then range(e.frames,m,1,30,true) end end\n     if e.type=='super' then assert(e.value==nil or (type(e.value)=='number' and e.value==1),'super armour takes no value') else range(e.value,m,1,lim[1],e.type=='hit_count') end\n     assert(e.direction==nil or e.direction=='any' or e.direction=='front' or e.direction=='back','invalid armour direction')\n    elseif e.op=='intangible' then assert(m.trigger~='equip','intangibility needs a trigger');range(e.frames,m,1,24,true)\n    elseif e.op=='interrupt' then\n     assert(m.trigger~='equip','an interrupt window needs a trigger');range(e.frames,m,1,20,true)\n     if e.exits then array(e.exits,1,13);local ok=set('jab tilt smash aerial special grab jump dash crouch turn walk escape shield air_dodge air_jump');local seen={};for _,x in ipairs(e.exits) do assert(ok[x] and not seen[x],'unknown interrupt exit');seen[x]=true end end\n     assert(e.guard==nil or type(e.guard)=='boolean');assert(e.restore_jumps==nil or type(e.restore_jumps)=='boolean')\n    else assert(m.trigger~='equip','a forced crit needs a trigger');range(e.count,m,1,3,true);range(e.multiplier,m,1.1,4) end\n   elseif e.op=='air_jumps' then assert(m.trigger=='equip','air jumps are a passive rule');range(e.count,m,0,6,true)\n   elseif e.op=='restrict' then\n    assert(m.trigger=='equip','a restriction is a passive rule');array(e.forbid,1,2);local ok=set('shield air_dodge run grab specials');local seen={}\n    for _,x in ipairs(e.forbid) do assert(ok[x] and not seen[x],'unknown restriction');seen[x]=true end\n   elseif e.op=='crit' then\n    assert(m.trigger=='equip','crit chance is a passive rule');assert(e.chance~=nil or e.multiplier~=nil,'crit needs a chance or a multiplier')\n    if e.chance~=nil then range(e.chance,m,0,(type(e.min_percent)=='number' and e.min_percent>=80) and 1 or .6) end -- a certain crit needs a percent floor\n    if e.multiplier~=nil then range(e.multiplier,m,1,4) end\n    if e.multiplier_max~=nil then range(e.multiplier_max,m,1,4);assert(e.multiplier~=nil,'multiplier_max needs multiplier') end\n    if e.launch~=nil then range(e.launch,m,1,1.25) end\n    if e.min_percent~=nil then range(e.min_percent,m,0,300) end\n    if e.tag~=nil then assert(set('jab dash_attack tilt smash aerial grab throw special projectile')[e.tag],'crit tag must be a move tag') end\n    if e.status~=nil then assert(S.statuses[e.status],'unsupported crit status') end\n   else range(e.amount,m,0,100) end\n  end\n  keys(m.stacking,set('max'));assert(m.stacking.max==1,'step1 equips each rule once')\n  keys(m.visual,set('look hue strength priority'));assert(set('burn shock chill curse haste guarded momentum')[m.visual.look]);assert(type(m.visual.hue)=='number' and m.visual.hue>=0 and m.visual.hue<=1 and type(m.visual.strength)=='number' and m.visual.strength>=0 and m.visual.strength<=1)\n  if m.visual.priority then assert(type(m.visual.priority)=='number' and m.visual.priority%1==0 and m.visual.priority>=0 and m.visual.priority<=100) end\n  for key in m.text:gmatch('{([a-z_]+)%%?}') do for _,tier in ipairs(m.tiers) do assert(type(tier[key])=='number','unknown tooltip tier') end end\n  return true\n end\n function S.level(tier)\n  if type(tier)=='table' then\n   assert(not getmetatable(tier),'plain modifier stack required');for k in pairs(tier)do assert(k=='tier' or k=='copies' or k=='tiers','unknown modifier stack field')end\n   if tier.tiers then\n    array(tier.tiers,1,6);local highest=0\n    for _,t in ipairs(tier.tiers)do D.mod_progression.growth(t);highest=math.max(highest,t)end\n    assert(tier.tier==nil or tier.tier==highest,'stack display tier mismatch')\n    assert(tier.copies==nil or tier.copies==#tier.tiers,'stack copy count mismatch');return highest\n   end\n   assert(type(tier.copies)=='number' and tier.copies%1==0 and tier.copies>=1 and tier.copies<=6,'invalid modifier copies');tier=tier.tier\n  end\n  tier=tier or 1;D.mod_progression.growth(tier);return tier\n end\n function S.copies(tier) S.level(tier);return type(tier)=='table' and (tier.tiers and #tier.tiers or tier.copies) or 1 end\n function S.instances(tier)\n  local highest=S.level(tier);local out={}\n  if type(tier)=='table' and tier.tiers then for _,t in ipairs(tier.tiers)do out[#out+1]=t end\n  else for _=1,S.copies(tier)do out[#out+1]=highest end end\n  return out\n end\n function S.resolve(v,m,tier)\n  tier=S.level(tier)\n  if type(v)~='string' then return v end\n  local key=v:sub(2);if m.tiers[tier] then return m.tiers[tier][key]end\n  local base=assert(m.tiers[1][key],'missing tier value');local growth=D.mod_progression.growth(tier)\n  if key=='ratio' then return 1+(base-1)*growth end\n  return base*(key=='bonus' and D.mod_progression.launch_growth(tier) or growth)\n end\n function S.ratio(v,m,tier,family)\n  local delta=0\n  for _,t in ipairs(S.instances(tier))do\n   local n=S.resolve(v,m,t)\n   -- Costs retain their authored size; each physical unique keeps its own growth.\n   if type(v)=='number' and m.kind~='normal' and ((family=='damage_dealt' and n>1) or (family=='damage_taken' and n<1)) then n=1+(n-1)*D.mod_progression.growth(t)end\n   if (family=='launch_taken' or family=='launch_dealt') and type(v)=='string' then n=1+(n-1)*D.mod_progression.launch_growth(t)/D.mod_progression.growth(t)end\n   delta=delta+n-1\n  end\n  -- The payoff drives of a chain are scaled by one named tuning value (mod_tuning: payoff_scale; 1 = as authored).\n  local k=D.mod_tuning and D.mod_tuning.ratio_scale(m);if k and k~=1 then delta=delta*k end\n  local n=1+delta;assert(n==n and math.abs(n)<=1e9,'native contribution exceeds finite safety');return n\n end\n function S.describe(m,tier)\n  S.validate(m);local text=m.text:gsub('{([a-z_]+)(%%?)}',function(k,pct) local v=S.resolve('$'..k,m,tier);return pct=='%' and tostring(v*100)..'%' or tostring(v) end)\n  local has_echo=false;for _,effect in ipairs(m.effects)do if effect.op=='echo' then has_echo=true end end\n  if m.kind=='unique' and not has_echo then\n   local lines={};local changed=false\n   local labels={damage_dealt='Attack percent damage',damage_taken='Attack percent damage taken',run_speed='Run speed',air_speed='Air speed'}\n   for _,e in ipairs(m.effects)do\n    if e.op=='value' then\n     changed=true;local n=S.ratio(e.value,m,tier,D.mod_budget.families[e.key])-1\n     if e.key=='damage_taken' and n<0 then lines[#lines+1]='Resistance +'..string.format('%.1f',-n*100)..'%; combined damage taken has a 15% floor.'\n     else lines[#lines+1]=(labels[e.key] or e.key)..' '..string.format('%+.1f%%',n*100)..'.'end\n    elseif e.op=='convert' and e.change.element then local name=e.change.element;lines[#lines+1]='Ordinary owned hitboxes become '..name:sub(1,1):upper()..name:sub(2)..'.'end\n   end\n   if changed then text='Tier '..S.level(tier)..': '..table.concat(lines,' ')end\n  end\n  return text\n end\n function S.tooltip(m,tier) return m.label..': '..S.describe(m,tier)..(m.cost and ' Cost: '..m.cost or '')end\n\n return S\nend\n", "@envoy/mod_schema.lua", "t"))()(envoy)
envoy.mod_codec = assert(load("-- Canonical bounded data encoding. No load(), functions, metatables or wall clock.\nreturn function(D)\n local C={}\n -- One shared output buffer (a table's pieces are appended in place, one concat at the end) rather than a\n -- string per node: the checkpoint is encoded every logic frame, so allocation, not parsing, is its cost.\n -- Sequences (keys exactly 1..n) skip the sort, which for them is the identity. Output bytes are unchanged.\n local format,concat,sort=string.format,table.concat,table.sort\n local function order(a,b) if type(a)~=type(b) then return type(a)=='number' end;return a<b end\n function C.encode(value)\n  local nodes,active=0,{}\n  local buf,n={},0\n  local pack\n  function pack(v,depth)\n   nodes=nodes+1;assert(nodes<=6000 and depth<=20,'modifier state too complex')\n   local kind=type(v)\n   if kind=='boolean' then n=n+1;buf[n]=v and 't' or 'f';return end\n   if kind=='number' then assert(v==v and math.abs(v)<1e15,'non-finite state');local s=format('%.17g',v);n=n+1;buf[n]='d'..#s..':'..s;return end\n   if kind=='string' then n=n+1;buf[n]='s'..#v..':'..v;return end\n   assert(kind=='table' and not getmetatable(v) and not active[v],'plain acyclic state required');active[v]=true\n   local count=0;for k in pairs(v) do assert(type(k)=='string' or type(k)=='number' and k%1==0,'invalid state key');count=count+1 end\n   assert(count<=512,'checkpoint table too large')\n   n=n+1;buf[n]='{'..count..':'\n   local seq=#v==count;if seq then for i=1,count do if v[i]==nil then seq=false;break end end end -- a border can equal the count with holes\n   if seq then for i=1,count do pack(i,depth+1);pack(v[i],depth+1) end\n   else\n    local keys,i={},0;for k in pairs(v) do i=i+1;keys[i]=k end\n    sort(keys,order)\n    for j=1,count do local k=keys[j];pack(k,depth+1);pack(v[k],depth+1) end\n   end\n   active[v]=nil\n  end\n  pack(value,0);local out=concat(buf,'',1,n);assert(#out<=16384,'modifier checkpoint exceeds 16 KiB');return out\n end\n function C.decode(text)\n  assert(type(text)=='string' and #text<=16384,'invalid modifier checkpoint');local at,nodes=1,0\n  local function count()\n   local endat=text:find(':',at,true);assert(endat and endat-at<7,'invalid checkpoint length')\n   local s=text:sub(at,endat-1);assert(s:match('^%d+$'),'invalid checkpoint count');at=endat+1;return tonumber(s)\n  end\n  local function read(depth)\n   nodes=nodes+1;assert(nodes<=6000 and depth<=20,'checkpoint too complex')\n   local kind=text:sub(at,at);at=at+1\n   if kind=='t' then return true elseif kind=='f' then return false end\n   if kind=='s' or kind=='d' then\n    local n=count();assert(at+n-1<=#text,'truncated checkpoint');local s=text:sub(at,at+n-1);at=at+n\n    if kind=='s' then return s end;local v=tonumber(s);assert(v and v==v and math.abs(v)<1e15,'invalid state number');return v\n   end\n   assert(kind=='{','invalid checkpoint type');local n=count();assert(n<=512,'checkpoint table too large');local out={}\n   for _=1,n do local k=read(depth+1);assert(type(k)=='string' or type(k)=='number' and k%1==0,'invalid checkpoint key');assert(out[k]==nil,'duplicate checkpoint key');out[k]=read(depth+1) end\n   return out\n  end\n  local out=read(0);assert(at==#text+1,'trailing checkpoint bytes');return out\n end\n -- ---- online play (Envoy netplay plan, stages 0 and 1) ------------------------------------------------------------------------\n -- Everything two peers must AGREE on is built here from pure functions: seeds, a canonical build record, and digests of both.\n -- No wall clock, no math.random except in the one named per-peer draw (fresh_seed), and every set is written in sorted order, so\n -- two processes (Lua randomises string hashing per state, so `pairs` order differs between them) write the same bytes.\n C.record_version=1\n local function fnv32(text,h)\n  h=h or 2166136261\n  for i=1,#text do h=((h~text:byte(i))*16777619)&0xFFFFFFFF end\n  return h\n end\n C.fnv32=fnv32\n -- 64-bit digest as 16 hex characters: two FNV-1a words, the second salted. Not cryptographic: it detects difference, not tampering.\n function C.digest64(text,salt) return ('%08x%08x'):format(fnv32(text),fnv32(text,fnv32(salt or 'envoy:'))) end\n -- The one formula every roll derives from (run_host.lua, coop.lua and drive_loot.lua carry the same; the tests pin that they agree).\n function C.seed_for(seed,stage,loop,k) return (seed+stage*104729+loop*15485863+k*32452843)%2147483646+1 end\n -- A deterministic [0,1) stream (Park-Miller, warmed so adjacent seeds do not share a first draw): what a hosted run uses instead of math.random.\n function C.rng(seed) local state=seed%2147483646+1;local function nxt(n) state=state*16807%2147483647;return (state-1)/2147483646*(n or 1) end;for _=1,6 do nxt() end;return nxt end\n -- The ONLY per-peer random draw of a run: where the run seed comes from when nobody supplied one. Offline it is math.random; online\n -- it is refused, because the lobby host chooses the seed and both peers receive it.\n function C.fresh_seed(g,random)\n  local m=g and g.match and g.match()\n  assert(not (m and m.netplay),'online run seeds come from the lobby host, never a local draw')\n  return (random or math.random)(0,2147483646)\n end\n -- Tier of one record in a build: a level 1..9, or a stack table. Canonical text: \"2\", \"2x3\" (level 2, three copies) or \"t1.2.2\" (an explicit list).\n local function tier_text(t)\n  if type(t)=='number' then assert(t%1==0 and t>=1 and t<=9,'tier out of range');return tostring(t) end\n  assert(type(t)=='table' and not getmetatable(t),'tier must be a level or a stack')\n  if t.tiers then local o={};for i,x in ipairs(t.tiers) do assert(type(x)=='number' and x%1==0 and x>=1 and x<=9,'tier out of range');o[i]=tostring(x) end;assert(#o>=1 and #o<=6,'stack size');return 't'..concat(o,'.') end\n  assert(type(t.tier)=='number' and t.tier%1==0 and t.tier>=1 and t.tier<=9,'tier out of range')\n  local copies=t.copies or 1;assert(copies%1==0 and copies>=1 and copies<=6,'copies out of range')\n  return copies==1 and tostring(t.tier) or (t.tier..'x'..copies)\n end\n local function tier_parse(s)\n  if s:match('^[1-9]$') then return tonumber(s) end\n  local lv,n=s:match('^([1-9])x([1-6])$');if lv then return {tier=tonumber(lv),copies=tonumber(n)} end\n  local list=s:match('^t([1-9%.]+)$');if list then local out={};for d in list:gmatch('[1-9]') do out[#out+1]=tonumber(d) end;assert(#out>=1 and #out<=6 and concat(out,'.')==list,'bad tier list');return {tiers=out} end\n  error('bad tier text '..s)\n end\n C.tier_text,C.tier_parse=tier_text,tier_parse\n local function sorted_keys(t) local k={};for key in pairs(t or {}) do k[#k+1]=key end;sort(k);return k end\n -- A digest of the rules themselves (ids, kinds, tiers, triggers, conditions, effects: not the wording or the look), so a peer with a\n -- different pool is refused rather than silently computing different numbers.\n function C.pool_digest(list)\n  list=list or (D and D.mod_pool);assert(type(list)=='table','no pool to digest')\n  local rows={}\n  for _,m in ipairs(list) do rows[#rows+1]={id=m.id,kind=m.kind,tiers=m.tiers,trigger=m.trigger,conditions=m.conditions,effects=m.effects,interval=m.interval or 0,cost=m.cost or ''} end\n  sort(rows,function(a,b) return a.id<b.id end)\n  local parts={};for i,r in ipairs(rows) do parts[i]=C.encode(r) end\n  return C.digest64(concat(parts,'\\0'),'pool:')\n end\n -- The build record of ONE player: the modifiers (sorted by id, with tier), the colour implicits (sorted by key) and the run context.\n -- meta = {seed=,game=,loop=,port=} (integers). Text form (one line, ASCII, no separators inside a field):\n --   EB1|<seed>|<game>|<loop>|<port>|<pool digest>|<id>=<tier>,<id>=<tier>...|<key>=<number>,...|<keystone ids>|<digest of everything before it>\n function C.build_record(meta,equipped,implicits,pool)\n  meta=meta or {}\n  for _,k in ipairs({'seed','game','loop','port'}) do assert(type(meta[k])=='number' and meta[k]%1==0 and meta[k]>=0 and meta[k]<=2147483647,'record '..k..' must be an integer') end\n  local mods,ks={},{}\n  local list=pool or (D and D.mod_pool);local kind={};for _,m in ipairs(list or {}) do kind[m.id]=m.kind end\n  for _,id in ipairs(sorted_keys(equipped)) do\n   assert(type(id)=='string' and id:match('^[%l%d_]+$'),'bad modifier id');assert(not list or kind[id],'unknown modifier '..id)\n   mods[#mods+1]=id..'='..tier_text(equipped[id]);if kind[id]=='keystone' then ks[#ks+1]=id end\n  end\n  local imps={}\n  for _,key in ipairs(sorted_keys(implicits)) do\n   local v=implicits[key];assert(type(key)=='string' and key:match('^[%l%d_]+$') and type(v)=='number' and v==v and math.abs(v)<1000,'bad implicit')\n   imps[#imps+1]=key..'='..format('%.17g',v)\n  end\n  local body=concat({'EB'..C.record_version,format('%d',meta.seed),format('%d',meta.game),format('%d',meta.loop),format('%d',meta.port),C.pool_digest(list),concat(mods,','),concat(imps,','),concat(ks,',')},'|')\n  local digest=C.digest64(body,'build:')\n  return body..'|'..digest,digest\n end\n -- Strict parse. Returns {meta=,equipped=,implicits=,keystones=,pool=,digest=} or nil,reason. Refuses a wrong version, a bad digest, a keystone list that\n -- is not exactly the keystones among the modifiers (when a pool is known), unsorted or duplicate fields.\n function C.parse_build_record(text,pool)\n  if type(text)~='string' or #text>400 or text:find('[^%g]') then return nil,'record is not compact ASCII' end\n  local f={};for field in (text..'|'):gmatch('([^|]*)|') do f[#f+1]=field end\n  if #f~=10 then return nil,'record has '..#f..' fields, expected 10' end\n  if f[1]~='EB'..C.record_version then return nil,'record version '..f[1]..' is not supported (this build reads EB'..C.record_version..')' end\n  local body=concat(f,'|',1,9);if C.digest64(body,'build:')~=f[10] then return nil,'record digest does not match its contents' end\n  local meta={};for i,k in ipairs({'seed','game','loop','port'}) do local v=math.tointeger(tonumber(f[i+1]));if not v or v<0 or v>2147483647 or tostring(v)~=f[i+1] then return nil,'bad '..k end;meta[k]=v end\n  if not f[6]:match('^%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x$') then return nil,'bad pool digest' end\n  local eq,last={},nil\n  for item in f[7]:gmatch('[^,]+') do\n   local id,t=item:match('^([%l%d_]+)=(.+)$');if not id then return nil,'bad modifier entry' end\n   if last and id<=last then return nil,'modifiers not strictly sorted' end;last=id\n   local ok,tier=pcall(tier_parse,t);if not ok then return nil,'bad tier for '..id end;eq[id]=tier\n  end\n  local imp;last=nil\n  for item in f[8]:gmatch('[^,]+') do\n   local key,v=item:match('^([%l%d_]+)=(.+)$');v=v and tonumber(v);if not key or not v then return nil,'bad implicit entry' end\n   if last and key<=last then return nil,'implicits not strictly sorted' end;last=key;imp=imp or {};imp[key]=v\n  end\n  local keys={};last=nil\n  for id in f[9]:gmatch('[^,]+') do if last and id<=last then return nil,'keystones not sorted' end;last=id;if not eq[id] then return nil,'keystone '..id..' is not in the build' end;keys[#keys+1]=id end\n  local list=pool or (D and D.mod_pool)\n  if list then\n   local kind={};for _,m in ipairs(list) do kind[m.id]=m.kind end\n   for id in pairs(eq) do if not kind[id] then return nil,'unknown modifier '..id end end\n   local want={};for id in pairs(eq) do if kind[id]=='keystone' then want[#want+1]=id end end;sort(want)\n   if concat(want,',')~=concat(keys,',') then return nil,'keystone list does not match the modifiers' end\n   if C.pool_digest(list)~=f[6] then return nil,'the record was made with a different modifier pool' end\n  end\n  return {meta=meta,equipped=eq,implicits=imp or {},keystones=keys,pool=f[6],digest=f[10]}\n end\n\n return C\nend\n", "@envoy/mod_codec.lua", "t"))()(envoy)
envoy.mod_graph = assert(load("-- The derived interaction graph: who feeds whom, computed ONCE per pool from the records (trigger, conditions, effects), never typed.\n-- It is the single source for: the strength formula's \"what does the rest of the build feed this record\" (mod_budget), connecting offers\n-- (run_host), the grid's link display and the archetype banners (synergy_fx), and the chain visuals.\n-- Vocabulary of a key:  status:X:self | status:X:target | status:X (a status_applied trigger) | status:any | elem:E | event:crit | event:armor | critchance\n--   gives(record) = the keys its effects produce; reads(record) = the keys its trigger, conditions or effects need.\n-- Edge kinds: feed (A gives what B reads), enable (A gives a crit chance a crit multiplier needs).\n-- Archetypes are named sets of ROLES over those records; their members are checked against the pool when the graph is built.\nreturn function(D)\n local G={}\n -- ---- profiles ------------------------------------------------------------------------------------------------------------\n -- sources: alternatives (the main trigger and each `also` trigger), each a list of keys; effect_reads[i]: keys effect i needs.\n local cache=setmetatable({},{__mode='k'})\n local function source_reads(trigger,conditions)\n  local r={}\n  if trigger=='status_applied' then for _,c in ipairs(conditions or {}) do if c.status then r[#r+1]='status:'..c.status end end end\n  if trigger=='crit' then r[#r+1]='event:crit' end\n  if trigger=='armor' then r[#r+1]='event:armor' end\n  for _,c in ipairs(conditions or {}) do\n   if c.tag then r[#r+1]='ev:'..trigger..':'..c.tag end   -- a tag an `emit` effect of another record can supply\n   if c.tag=='fire' or c.tag=='ice' or c.tag=='electric' then r[#r+1]='elem:'..c.tag end\n   if c.self_status then r[#r+1]=c.self_status=='any' and 'status:any' or 'status:'..c.self_status..':self' end\n   if c.target_status then r[#r+1]=c.target_status=='any' and 'status:any' or 'status:'..c.target_status..':target' end\n  end\n  return r\n end\n function G.profile(m)\n  local p=cache[m];if p and p.cref==m.conditions and p.eref==m.effects and p.tref==m.trigger and p.aref==m.also then return p end\n  p={id=m.id,gives={},sources={},effect_reads={},trigger=m.trigger,cref=m.conditions,eref=m.effects,tref=m.trigger,aref=m.also}\n  p.sources[1]=source_reads(m.trigger,m.conditions)\n  for _,a in ipairs(m.also or {}) do p.sources[#p.sources+1]=source_reads(a.trigger,a.conditions) end\n  local function give(k) p.gives[k]=true end\n  for i,e in ipairs(m.effects) do\n   local er={}\n   if e.op=='versus-status' and e.status then er[#er+1]='status:'..e.status..':target' end\n   if e.op=='echo' and e.status then er[#er+1]='status:'..e.status..':self' end\n   if e.op=='crit' and not e.chance then er[#er+1]='critchance' end\n   if e.op=='crit' and e.status then er[#er+1]='status:'..e.status..':self' end\n   p.effect_reads[i]=er\n   if e.op=='status' or e.op=='stacks' or e.op=='chain_status' then\n    local sj=e.op=='chain_status' and 'target' or (e.subject or 'self')\n    give('status:'..e.status..':'..sj);give('status:'..e.status);if sj=='target' then give('status:any') end\n   elseif e.op=='convert' and e.change.element then give('elem:'..e.change.element)\n   elseif (e.op=='crit' and e.chance) or e.op=='crit_next' then give('event:crit');give('critchance')\n   elseif e.op=='armor' then give('event:armor')\n   elseif e.op=='emit' then give('event:'..e.event);give('ev:'..e.event..':'..e.tag) end\n  end\n  p.reads={};local seen={}\n  for _,s in ipairs(p.sources) do for _,k in ipairs(s) do if not seen[k] then seen[k]=true;p.reads[#p.reads+1]=k end end end\n  for _,er in ipairs(p.effect_reads) do for _,k in ipairs(er) do if not seen[k] then seen[k]=true;p.reads[#p.reads+1]=k end end end\n  cache[m]=p;return p\n end\n -- How much of what effect `i` of the record needs does `provided` (a set of keys held by the OTHER records) give: 0..1, or nil when it needs nothing.\n -- A triggered record needs its trigger side (the best of its alternative triggers) AND the effect's own reads.\n function G.supply(m,i,provided,triggered)\n  local p=G.profile(m);local need,have=0,0\n  if triggered then\n   local best\n   for _,s in ipairs(p.sources) do\n    if #s==0 then best=1;break end\n    local ok=0;for _,k in ipairs(s) do if provided[k] then ok=ok+1 end end\n    local f=ok/#s;if not best or f>best then best=f end\n   end\n   if #p.sources[1]>0 or #(m.also or {})>0 then need=need+1;have=have+(best or 0) end\n  end\n  local er=p.effect_reads[i]\n  if er and #er>0 then local ok=0;for _,k in ipairs(er) do if provided[k] then ok=ok+1 end end;need=need+1;have=have+ok/#er end\n  if need==0 then return nil end\n  return have/need\n end\n -- ---- the graph -------------------------------------------------------------------------------------------------------------\n local graphs=setmetatable({},{__mode='k'})\n function G.graph(pool)\n  local g=graphs[pool];if g and g.n==#pool then return g end\n  g={n=#pool,out={},into={},partners={},list={},prof={}}\n  for _,m in ipairs(pool) do g.prof[m.id]=G.profile(m);g.out[m.id]={};g.into[m.id]={};g.partners[m.id]={} end\n  for _,a in ipairs(pool) do local pa=g.prof[a.id]\n   for _,b in ipairs(pool) do if a~=b then local pb=g.prof[b.id]\n    for _,k in ipairs(pb.reads) do\n     if pa.gives[k] then\n      if not g.out[a.id][b.id] then\n       local e={from=a.id,to=b.id,kind=k=='critchance' and 'enable' or 'feed',why=k}\n       g.out[a.id][b.id]=e;g.into[b.id][a.id]=e;g.list[#g.list+1]=e;g.partners[a.id][b.id]=true;g.partners[b.id][a.id]=true\n      end\n      break\n     end\n    end\n   end end\n  end\n  graphs[pool]=g;return g\n end\n function G.connected(pool,a,b) local g=G.graph(pool);return (g.out[a] and g.out[a][b]) or (g.out[b] and g.out[b][a]) or nil end\n -- Does any of `ids` connect to any of the held set `held` (id -> truthy)? Returns true, offered id, held id.\n function G.connects(pool,ids,held)\n  local g=G.graph(pool)\n  for _,id in ipairs(ids) do local ps=g.partners[id]\n   if ps then for h in pairs(held) do if h~=id and ps[h] then return true,id,h end end end\n  end\n  return false\n end\n -- ---- archetypes ------------------------------------------------------------------------------------------------------------\n -- roles: {name, alts}; alts = alternatives, each a list of ids that must ALL be held. colour 0xRRGGBB; motif names the emblem and the surface treatment.\n G.archetypes={\n  {id='burn',name='Burn stacking',colour=0xFF4A2A,motif='flame',blurb='Your hits set Burn and your payoff drives turn it into damage.',\n   roles={{name='a Burning applier',alts={{'plague_bearer'},{'kindling'}}},{name='a payoff',alts={{'pyre'},{'cinder'},{'everburn'}}}}},\n  {id='chill',name='Chill stacking',colour=0x7FD6FF,motif='frost',blurb='Your hits Chill and your payoff drives turn it into damage.',\n   roles={{name='a Chill applier',alts={{'deep_freeze'},{'icebound'}}},{name='a payoff',alts={{'brittle'},{'shatter'}}}}},\n  {id='shock',name='Shock chain',colour=0x21E6E6,motif='arc',blurb='Electric hits Shock one opponent and chain it to the next.',\n   roles={{name='an electric source',alts={{'charged'},{'storm_shell'}}},{name='Conductor',alts={{'conductor'}}}}},\n  {id='momentum',name='Momentum speed',colour=0xFFB11F,motif='chevron',blurb='Hits build Momentum and a landing spends it.',\n   roles={{name='a Momentum source',alts={{'updraft'},{'rush'}}},{name='a landing payoff',alts={{'crosswind'},{'bastion'}}}}},\n  {id='haste',name='Haste web',colour=0x5CF04C,motif='web',blurb='Haste feeds your Haste payoffs, and they feed Haste again.',\n   roles={{name='a Haste source',alts={{'ledge'},{'clean_landing'},{'combo_surge'},{'perpetual_motion'},{'hit_and_run'},{'critical_flow'},{'crosswind'},{'fury'},{'clean_lander'}}},{name='a payoff',alts={{'rush'},{'echo_weaver'},{'trailing'}}}}},\n  {id='guard',name='Guard and heal',colour=0x4C7BFF,motif='plate',blurb='Guarded turns into healing.',\n   roles={{name='a Guarded source',alts={{'reprisal'},{'bastion'},{'shelter'},{'tech_guard'},{'parry_master'},{'iron_resolve'},{'last_stand'}}},{name='Renewal',alts={{'renewal'}}}}},\n  {id='technique',name='Technique crit',colour=0xFF3FA4,motif='sight',blurb='A technique forces a crit and the crit pays out.',\n   roles={{name='a technique trigger',alts={{'wave_edge'},{'combo_conduit'}}},{name='a crit payoff',alts={{'critical_flow'}}}}},\n  {id='crit',name='Passive crit',colour=0xA67CFF,motif='burst',blurb='Crit chance meets a stronger crit.',\n   roles={{name='a crit chance',alts={{'keen'},{'ruthless'},{'finishing'},{'gambler'},{'executioner'}}},{name='a crit payoff',alts={{'brutal'},{'critical_flow'}}}}},\n  {id='armour',name='Armour retaliation',colour=0xC8D2DC,motif='spike',blurb='Armour that absorbs a hit makes your next hit a crit.',\n   roles={{name='an armour source',alts={{'shield_stance'},{'wavedasher'},{'juggernaut'}}},{name='Retaliation',alts={{'retaliation'}}}}},\n }\n G.by_id={};for i,a in ipairs(G.archetypes) do G.by_id[a.id]=a;a.index=i end\n local piece_cache=setmetatable({},{__mode='k'})\n -- id -> list of archetypes the record is a piece of (only ids that exist in the pool count)\n function G.pieces(pool)\n  local c=piece_cache[pool];if c and c.n==#pool then return c end\n  local exists={};for _,m in ipairs(pool) do exists[m.id]=true end\n  c={n=#pool,of={},missing={}}\n  for _,a in ipairs(G.archetypes) do for _,r in ipairs(a.roles) do for _,alt in ipairs(r.alts) do for _,id in ipairs(alt) do\n   if exists[id] then c.of[id]=c.of[id] or {};local l=c.of[id];local dup;for _,x in ipairs(l) do if x==a then dup=true end end;if not dup then l[#l+1]=a end\n   else c.missing[#c.missing+1]=a.id..':'..id end\n  end end end end\n  piece_cache[pool]=c;return c\n end\n -- Roles filled by the held set: {filled,total,complete,missing=name of the first open role,used=set of ids that filled a role}.\n function G.progress(a,held)\n  local filled,missing=0,nil;local used={}\n  for _,r in ipairs(a.roles) do\n   local ok=false\n   for _,alt in ipairs(r.alts) do local all=true;for _,id in ipairs(alt) do if not held[id] then all=false;break end end\n    if all then ok=true;for _,id in ipairs(alt) do used[id]=true end;break end\n   end\n   if ok then filled=filled+1 elseif not missing then missing=r.name end\n  end\n  return {filled=filled,total=#a.roles,complete=filled==#a.roles,missing=missing,used=used}\n end\n -- Archetypes with at least one role filled, completed ones first. `held` is id -> truthy.\n function G.analyze(held)\n  local out={}\n  for i,a in ipairs(G.archetypes) do local p=G.progress(a,held);if p.filled>0 then p.archetype=a;out[#out+1]=p end end\n  table.sort(out,function(x,y)\n   if x.complete~=y.complete then return x.complete end\n   if x.filled~=y.filled then return x.filled>y.filled end\n   return x.archetype.index<y.archetype.index\n  end)\n  return out\n end\n function G.completed(held) local out={};for _,p in ipairs(G.analyze(held)) do if p.complete then out[#out+1]=p.archetype end end;return out end\n -- What a set of ids (an offered drive's affixes, a keystone) would do to the held set: 'complete' (finishes an archetype), 'advance' (fills one more role of an\n -- archetype you already have a part of), or nil; and the archetype.\n function G.effect_of(ids,held)\n  local after={};for k,v in pairs(held) do after[k]=v end;for _,id in ipairs(ids) do after[id]=true end\n  local adv\n  for _,a in ipairs(G.archetypes) do\n   local b,f=G.progress(a,held),G.progress(a,after)\n   if f.complete and not b.complete then return 'complete',a end\n   if f.filled>b.filled and b.filled>0 and not adv then adv=a end\n  end\n  if adv then return 'advance',adv end\n  return nil\n end\n -- The archetype a chain link (record `src` fed record `dst`) belongs to: one that has both as pieces, else one that has dst, else src.\n function G.chain_archetype(pool,src,dst)\n  local of=G.pieces(pool).of\n  for _,a in ipairs(of[dst] or {}) do for _,b in ipairs(of[src] or {}) do if a==b then return a end end end\n  return (of[dst] or {})[1] or (of[src] or {})[1]\n end\n -- ---- connecting offers ---------------------------------------------------------------------------------------------------\n -- When none of the offered drive records connects to anything held, replace one (index from `pick`) with a roll of the same rarity pulled toward partners of\n -- a held piece. `seed_of(try,k)` gives the seed of each attempt, so the same stage always shows the same offers. Returns the index replaced, or nil.\n function G.connect_offers(pool,loot,offers,held,pick,ctx,rarity_of,seed_of)\n  if #offers==0 or not next(held) then return nil end\n  local function ids(r) local l={};for _,a in ipairs(r.affixes) do l[#l+1]=a.id end;return l end\n  for _,r in ipairs(offers) do if G.connects(pool,ids(r),held) then return nil end end\n  local graph=G.graph(pool);local bias={}\n  for h in pairs(held) do for p in pairs(graph.partners[h] or {}) do if not held[p] then bias[p]=12 end end end\n  if not next(bias) then return nil end\n  local k=1+(pick%#offers)\n  for try=1,24 do\n   local ok,r=pcall(loot.roll,loot,seed_of(try,k),ctx,rarity_of(k),nil,bias)\n   if ok and r and G.connects(pool,ids(r),held) then offers[k]=r;return k,r end\n  end\n  return nil\n end\n -- ---- words -------------------------------------------------------------------------------------------------------------------\n -- ONE word per status (mod_status.label): the link text says Burning, Chilled, Haste, Guarded, Marked, never the old names.\n local function status_name(st) return D.mod_status.label(st) end\n local function sets_phrase(key)\n  local st,subj=key:match('^status:(%a+):(%a+)$')\n  if st then if subj=='target' then return 'Puts '..status_name(st)..' on the target' end;return 'Gives you '..status_name(st) end\n  st=key:match('^status:(%a+)$');if st and st~='any' then return 'Gives '..status_name(st) end\n  if key=='status:any' then return 'Puts a status on the target' end\n  local e=key:match('^elem:(%a+)$');if e then return 'Makes your hits '..e:sub(1,1):upper()..e:sub(2) end\n  if key=='event:crit' then return 'Sets up a crit' end\n  if key=='critchance' then return 'Gives you a crit chance' end\n  if key=='event:armor' then return 'Gives armour to absorb a hit' end\n  return 'Feeds'\n end\n -- One short line for a link: \"Sets Burn on the target, which your Cinder drive turns into +10% damage.\"\n function G.link_text(pool,a_id,b_id,tier)\n  local g=G.graph(pool);local e=(g.out[a_id] or {})[b_id] or (g.out[b_id] or {})[a_id];if not e then return nil end\n  local by={};for _,m in ipairs(pool) do by[m.id]=m end\n  local to=by[e.to];if not (by[e.from] and to) then return nil end\n  tier=tier or 1\n  local uses\n  for _,eff in ipairs(to.effects) do\n   if eff.op=='versus-status' and eff.status then\n    local S=D.mod_schema;local c=eff.change\n    if c.percent_damage then uses='turns into +'..math.floor((S.ratio(c.percent_damage,to,tier,'damage_dealt')-1)*100+.5)..'% damage' break end\n    if c.launch then uses='turns into +'..math.floor((S.ratio(c.launch,to,tier,'launch_dealt')-1)*100+.5)..'% launch' break end\n   end\n  end\n  local noun=to.kind=='keystone' and 'keystone' or 'drive'\n  if not uses then if e.kind=='enable' then uses='then makes use of' else uses=to.trigger=='equip' and 'builds on' or 'fires from' end end\n  return sets_phrase(e.why)..', which your '..to.label..' '..noun..' '..uses..'.',e\n end\n return G\nend\n", "@envoy/mod_graph.lua", "t"))()(envoy)
envoy.mod_budget = assert(load("-- One authority: additive deltas, numerical safety families, bounded utility, conservative pool audit.\nreturn function(D)\n local S=D.mod_schema;local B={}\n -- Every registered effect needs a budget answer; a field the schema admits cannot be silently unbudgeted.\n B.effect_ops={echo=true,value=true,convert=true,['versus-status']=true,status=true,stacks=true,remove_status=true,heal=true,damage=true,clank_damage=true,emit=true,armor=true,intangible=true,interrupt=true,chain_status=true,crit_next=true,air_jumps=true,restrict=true,crit=true}\n for op in pairs(D.mod_registry.effects) do assert(B.effect_ops[op],'registered effect has no budget rule: '..op) end\n for op in pairs(B.effect_ops) do assert(D.mod_registry.effects[op],'budget rule for an unregistered effect: '..op) end\n B.order={'echo','damage_dealt','launch_dealt','damage_taken','launch_taken','speed','jump','status_duration','sustain','conversion','momentum','clank','cleanse','curse_dealt','armor','intangible','air_jumps','restrict','interrupt','crit','fall','weight'}\n B.caps={echo={0,12},damage_dealt={-.95,63},launch_dealt={-.95,3},damage_taken={-.85,63},launch_taken={-.95,3},speed={-.8,1},jump={-.8,1},status_duration={-.95,19},sustain={0,100},conversion={0,30},momentum={0,40},clank={0,6},cleanse={0,30},curse_dealt={0,3},armor={0,12},intangible={0,3},air_jumps={-1,5},restrict={0,4},interrupt={0,2},crit={0,3},fall={-.6,1.5},weight={-.5,1.5}}\n B.families={damage_dealt='damage_dealt',launch_dealt='launch_dealt',damage_taken='damage_taken',knockback_taken='launch_taken',run_speed='speed',air_speed='speed',jump_height='jump',air_jump_height='jump',status_duration='status_duration',fall_speed='fall',weight='weight'}\n B.implicit_families={red={'damage_dealt'},green={'speed'},blue={'launch_taken'},yellow={'jump'},purple={'status_duration'},white={}}\n -- STRENGTH v2 (the synergy-aware number; `mod_tuning` strength=v2, the default; v1 is the old additive one, kept for comparison).\n -- A record counts for what it actually does given what the build feeds it: a reader counts 0.1 + 0.9 x (what the OTHER held records provide of what\n -- it reads, from the derived graph, mod_graph); a status a trigger grants counts for rate x duration of its trigger, not for ever; Echo is capped to\n -- what it measures; speed counts a little; cleansing counts less. Constants are chosen from the synergy analysis (measured rates), not tuned by play.\n B.rates=B.rates or {hit_dealt=.8,landing=.45,hit_taken=.45,jump=.09,air_jump=.035,ko_dealt=.018,clank=.02,ledge_grab=.006,perfect_shield=.018,interval=1,status_applied=.3,crit=.05,combo=.25,combo_end=.05,lcancel_hit=.002,wavedash=.005,tech=.01,air_dodge=.02,armor=.02}\n B.crit_w=B.crit_w or 1;B.skill=B.skill or .6;B.speed_w=B.speed_w or .25;B.echo_cap=B.echo_cap or .6;B.cleanse_w=B.cleanse_w or .03\n B.human=B.human or {lcancel_hit=.15,wavedash=.08,perfect_shield=.05,tech=.05,air_dodge=.05}   -- placeholder technique rates a person performs, x skill; needs the owner's counters\n function B.mode() if D.mod_tuning and D.mod_tuning.get('strength')=='v1' then return 'v1' end;return D.mod_graph and 'v2' or 'v1' end\n function B.uptime(m,duration)\n  local t=m.trigger;if t=='interval' then return 1 end;if t=='status_applied' then return .5 end\n  local r=B.rates[t] or .3;if B.human[t] then r=B.human[t]*B.skill end\n  return math.max(.05,math.min(1,r*(duration or 60)/60))\n end\n local function clamp(f,n) local c=assert(B.caps[f],'uncapped family');return math.max(c[1],math.min(c[2],n)) end\n local function add(t,f,n) t[f]=(t[f] or 0)+n end\n local status=D.mod_status.budget\n local function effect(e,m,tier)\n  local out={};local function value(v) return S.resolve(v,m,tier) end\n  if e.op=='echo' then\n   local d=D.mod_echo.resolve(e,m,tier);out.echo=0;for _,c in ipairs(d.copies)do if c.echo then out.echo=out.echo+c.echo.damage*c.echo.knockback end end;out.echo=out.echo*S.copies(tier)\n  elseif e.op=='value' then add(out,assert(B.families[e.key],'unbudgeted fighter value'),S.ratio(e.value,m,tier,B.families[e.key])-1)\n  elseif e.op=='convert' or e.op=='versus-status' then\n   for k,v in pairs(e.change) do\n    if k=='element' then out.conversion=S.copies(tier)\n    elseif k=='percent_damage' then add(out,e.match.incoming and 'damage_taken' or 'damage_dealt',S.ratio(v,m,tier,e.match.incoming and 'damage_taken' or 'damage_dealt')-1)\n    elseif k=='launch' then add(out,e.match.incoming and 'launch_taken' or 'launch_dealt',S.ratio(v,m,tier,e.match.incoming and 'launch_taken' or 'launch_dealt')-1)\n    else error('unbudgeted native field '..k) end\n   end\n  elseif e.op=='status' or e.op=='stacks' or e.op=='chain_status' then out=status(e.status,value(e.amount or 1)*(D.mod_tuning and D.mod_tuning.amount_scale(m,e) or 1),e.max);if e.op=='chain_status' then out.conversion=(out.conversion or 0)+S.copies(tier) end\n   if B.mode()=='v2' then local u=B.uptime(m,value(e.duration or 60));for k,v in pairs(out) do out[k]=v*u end end\n  elseif e.op=='remove_status' then out=status(e.status,0,0);for k in pairs(out) do out[k]=0 end;out.cleanse=e.count and 0 or S.copies(tier)   -- spending a stack of your own buff (count) is not cleansing\n  elseif e.op=='heal' or e.op=='damage' then out.sustain=0;for _,instance in ipairs(S.instances(tier))do out.sustain=out.sustain+math.min(100,S.resolve(e.amount,m,instance))end\n  elseif e.op=='clank_damage' then out.clank=S.copies(tier)\n  elseif e.op=='emit' then out.conversion=S.copies(tier)\n  elseif e.op=='armor' then\n   -- Protection-seconds: a type's weight times how long it stands. A permanent threshold counts as two seconds a point per ten.\n   out.armor=0;for _,instance in ipairs(S.instances(tier)) do\n    local v=e.value and S.resolve(e.value,m,instance) or 1;local f=e.frames and S.resolve(e.frames,m,instance)\n    v=math.min(v,e.type=='hit_count' and 3 or 40);if f then f=math.min(f,e.type=='super' and 30 or 600) end\n    local n\n    if e.type=='super' then n=f/60 elseif e.type=='damage_threshold' then n=f and v/10*f/60*.8 or v/10*2\n    elseif e.type=='hit_count' then n=v*.35 elseif e.type=='damage_pool' then n=v/30*1.5 else n=v/40 end\n    out.armor=out.armor+n\n   end\n  elseif e.op=='intangible' then out.intangible=0;for _,instance in ipairs(S.instances(tier)) do out.intangible=out.intangible+math.min(24,S.resolve(e.frames,m,instance))/60 end\n  elseif e.op=='interrupt' then out.interrupt=0;for _,instance in ipairs(S.instances(tier)) do out.interrupt=out.interrupt+math.min(20,S.resolve(e.frames,m,instance))/60 end\n  elseif e.op=='air_jumps' then out.air_jumps=(S.resolve(e.count,m,tier)-1)*S.copies(tier)\n  elseif e.op=='restrict' then out.restrict=#e.forbid*S.copies(tier)\n  elseif e.op=='crit_next' then out.crit=0;for _,instance in ipairs(S.instances(tier)) do out.crit=out.crit+math.min(3,S.resolve(e.count,m,instance))*(math.min(4,S.resolve(e.multiplier,m,instance))-1)*.12 end\n  elseif e.op=='crit' then\n   -- Expected extra damage: a chance times its multiplier gain, scaled by how often it can apply. A multiplier alone is worth a\n   -- fraction (it needs a chance from elsewhere); a tag, a status gate or a percent floor each narrow it.\n   out.crit=0;for _,instance in ipairs(S.instances(tier)) do\n    local c=e.chance and math.min(1,S.resolve(e.chance,m,instance));local mult=math.min(4,e.multiplier and S.resolve(e.multiplier,m,instance) or 1.5)\n    -- v2: the engine draws a crit uniformly up to multiplier_max, so its mean is the midpoint (Gambler measured x1.25, v1 said x0.94)\n    if e.multiplier_max and B.mode()=='v2' then mult=(mult+math.min(4,S.resolve(e.multiplier_max,m,instance)))/2 end\n    local n\n    if c then n=c*(mult-1) elseif mult>1 then n=(mult-1)*.15 else n=0 end\n    if e.tag then n=n*.35 end;if e.status then n=n*.6 end;if e.min_percent and e.min_percent>0 then n=n*(B.mode()=='v2' and .4 or .6) end   -- v2: a target above 100% is a minority of a fight\n    out.crit=out.crit+n\n   end\n  else error('unbudgeted effect') end\n  return out\n end\n -- The families a record's effects touch at any tier (what its `families` declaration must say). Used by pool\n -- builders that write many records (keystones.lua) so a declaration is derived, never typed twice.\n function B.effect_families(m)\n  local seen,out={},{}\n  for tier=1,#m.tiers do for _,e in ipairs(m.effects) do for f in pairs(effect(e,m,tier)) do if not seen[f] then seen[f]=true;out[#out+1]=f end end end end\n  table.sort(out);return out\n end\n -- A pool is data fixed at load: validating the same table against the same implicit definitions twice is pure\n -- repetition (every drive_loot.new, i.e. every candidate an opponent roll constructs, did it: ~half the\n -- instructions of a deep roll). Keyed by the pool and implicit-definition tables' identity; a failure is never remembered.\n local validated=setmetatable({},{__mode='k'})\n function B.validate_pool(pool,implicitdefs)\n  local seen_defs=validated[pool]\n  if seen_defs and seen_defs[implicitdefs or false] and #pool==seen_defs.n then return true end\n  local ok=B.validate_pool_uncached(pool,implicitdefs)\n  seen_defs=seen_defs or {n=#pool};seen_defs.n=#pool;seen_defs[implicitdefs or false]=true;validated[pool]=seen_defs\n  return ok\n end\n function B.validate_pool_uncached(pool,implicitdefs)\n  local ids={}\n  for _,m in ipairs(pool) do\n   S.validate(m);assert(not ids[m.id],'duplicate modifier');ids[m.id]=true\n   assert(type(m.families)=='table','family declaration required');local declared,seen={},{}\n   for _,f in ipairs(m.families) do assert(B.caps[f] and not declared[f],'unknown/duplicate family');declared[f]=true end\n   for tier=1,#m.tiers do\n    local totals={}\n    for _,e in ipairs(m.effects) do for f,n in pairs(effect(e,m,tier)) do\n     assert(declared[f],'undeclared effect family');seen[f]=true\n     assert(n==n and math.abs(n)<=1e9,'individual contribution exceeds finite safety');add(totals,f,n)\n    end end\n    for f,n in pairs(totals) do assert(n==n and math.abs(n)<=1e9,'record contribution exceeds finite safety') end\n   end\n   for f in pairs(declared) do assert(seen[f],'lying family declaration') end\n  end\n  for colour,base in pairs(implicitdefs or {}) do\n   local allowed={};for _,f in ipairs(assert(B.implicit_families[colour],'unknown implicit colour')) do allowed[f]=true end\n   local seen={};for key,v in pairs(base) do local f=assert(B.families[key],'unknown implicit family');assert(allowed[f],'undeclared implicit');assert(type(v)=='number' and v==v and v-1>=B.caps[f][1] and v-1<=B.caps[f][2],'implicit over budget');seen[f]=true end\n   for f in pairs(allowed) do assert(seen[f],'missing implicit family') end\n  end\n  return true\n end\n local function compose(pool,mods,implicits,statuses)\n  local raw,potential,keys,power={},{},{},{}\n  -- Held keystones must be compatible (no exclusive pair, stacked drawbacks inside the limits): one rule for the\n  -- bag, the foe roll and the engine, since all of them reach the budget.\n  if D.keystones then local held={};for id,t in pairs(mods or {}) do if D.keystones.meta[id] then held[#held+1]=id end end\n   table.sort(held);if #held>1 then local ok,why=D.keystones.check(held);assert(ok,why or 'incompatible keystones') end end\n  for k,v in pairs(implicits or {}) do local f=assert(B.families[k],'unknown implicit');assert(type(v)=='number' and v==v and math.abs(v)<100,'invalid implicit');keys[k]=v-1 end\n  local found={}\n  local v2=B.mode()=='v2';local counts\n  if v2 then counts={};for _,m in ipairs(pool) do if (mods or {})[m.id] then for k in pairs(D.mod_graph.profile(m).gives) do counts[k]=(counts[k] or 0)+1 end end end end\n  for _,m in ipairs(pool) do local tier=(mods or {})[m.id];if tier then\n   S.level(tier);found[m.id]=true\n   local provided\n   if v2 then local own=D.mod_graph.profile(m).gives\n    provided=setmetatable({},{__index=function(_,k) local n=counts[k] or 0;if own[k] then n=n-1 end;return n>0 end}) end\n   for i,e in ipairs(m.effects) do\n    local contributions=effect(e,m,tier)\n    if v2 then local sup=D.mod_graph.supply(m,i,provided,m.trigger~='equip')\n     if sup then local gw=.1+.9*sup;for f,n in pairs(contributions) do contributions[f]=n*gw end end end\n    for f,n in pairs(contributions) do local pf=e.subject=='target' and f=='launch_taken' and 'curse_dealt' or f;add(potential,pf,n);local incoming=f=='damage_taken' or f=='launch_taken';local score=incoming and -n or n;if e.subject=='target' and (incoming or f=='speed') then score=-score end;add(power,f,score) end\n    if e.op=='value' then add(keys,e.key,S.ratio(e.value,m,tier,B.families[e.key])-1)\n    elseif e.op=='versus-status' or e.op=='convert' then\n     if not e.status and not e.match.incoming and (not e.match.move or e.match.move=='any') and not e.match.element and e.change.launch then add(raw,'launch_dealt',S.ratio(e.change.launch,m,tier,'launch_dealt')-1) end\n    end\n   end\n  end end\n  for id in pairs(mods or {}) do assert(found[id],'unknown modifier') end\n  for name,v in pairs(statuses or {}) do\n   for k,n in pairs(D.mod_status.values(name,v)) do add(keys,k,n) end\n  end\n  -- Multiple keys in speed/jump share caps but do not double-count one implicit.\n  local familykeys={}\n  for k,n in pairs(keys) do local f=B.families[k];if familykeys[f]==nil or math.abs(n)>math.abs(familykeys[f]) or (math.abs(n)==math.abs(familykeys[f]) and n>familykeys[f]) then familykeys[f]=n end end\n  for f,n in pairs(familykeys) do add(raw,f,n) end\n  for k,v in pairs(implicits or {}) do local f=B.families[k];if k~='air_speed' and k~='air_jump_height' then add(potential,f,v-1);add(power,f,(f=='damage_taken' or f=='launch_taken') and 1-v or v-1) end end\n  if D.mod_echo then\n   local d=D.mod_echo.engine({list=pool,equipped={[1]=mods or {}},status=function(_,_,name)return (statuses or {})[name]end},1);local n=0\n   for _,r in ipairs(d.rules)do n=n+r.damage*r.knockback end;potential.echo=n;power.echo=n\n  end\n  return raw,potential,keys,power\n end\n -- Restrictions are only ever a price. At most two at once, and never the pair that leaves a fighter with no defence at all.\n function B.restrictions_ok(list)\n  local n,has=0,{};for _,x in ipairs(list or {}) do n=n+1;has[x]=true end\n  if n>2 then return false,'Those keystones forbid too many actions.' end\n  if has.shield and has.air_dodge then return false,'Those keystones leave you with no defence.' end\n  if has.run and has.air_dodge and has.specials then return false,'Those keystones forbid too many actions.' end\n  return true\n end\n function B.sustain_delta(previous,delta) local cap=B.caps.sustain[2];local next=math.max(-cap,math.min(cap,(previous or 0)+delta));return next,next-(previous or 0) end\n function B.build(pool,mods,implicits,statuses)\n  local raw,potential,_,scores=compose(pool,mods,implicits,statuses);local out,strength={},1\n  for _,f in ipairs(B.order) do local c=B.caps[f]\n   local n=raw[f] or 0;local p=potential[f] or 0;out[f]={raw=n,value=1+clamp(f,n),potential=1+clamp(f,p)}\n  end\n  -- A crit is an expectation, not a certainty: it counts at half weight in build strength.\n  local offence=out.damage_dealt.potential*(1+(out.crit.potential-1)*.5)\n  local toughness=1/out.damage_taken.potential\n  -- Weight divides the launch taken (a heavier fighter flies less far); more protection and mobility add to utility.\n  local launch=out.launch_dealt.potential*out.curse_dealt.potential/math.max(.05,out.launch_taken.potential/math.max(.2,out.weight.potential))\n  local utility=math.max(.5,1+.025*math.max(0,out.sustain.potential-1)+.04*math.max(0,out.momentum.potential-1)+.12*math.max(0,out.conversion.potential-1)+.2*math.max(0,out.clank.potential-1)+.1*math.max(0,out.cleanse.potential-1)+.08*math.max(0,out.armor.potential-1)+.15*math.max(0,out.intangible.potential-1)+.12*math.max(0,out.interrupt.potential-1)+.03*math.max(0,out.air_jumps.potential-1)-.08*math.max(0,out.restrict.potential-1)+.06*math.max(0,1-out.fall.potential)-.02*math.max(0,out.fall.potential-1))\n  if B.mode()=='v2' then\n   local cw=B.cleanse_w-.1  -- v1 weights cleansing .1 a point; v2 .03\n   utility=math.max(.5,utility+cw*math.max(0,out.cleanse.potential-1))\n   offence=out.damage_dealt.potential*(1+(out.crit.potential-1)*B.crit_w)   -- v1 counted a crit at half weight; measured, an expectation counts in full\n   local echoterm=1+math.min(B.echo_cap,math.max(0,out.echo.potential-1));local speedterm=1+B.speed_w*math.max(0,out.speed.potential-1)\n   strength=echoterm*offence*toughness^.25*math.max(.25,launch)^.25*utility*speedterm\n  else strength=(1+math.max(0,out.echo.potential-1))*offence*toughness^.25*math.max(.25,launch)^.25*utility end\n  return out,math.max(1,strength)\n end\n function B.values(pool,mods,implicits,statuses)\n  local _,_,keys=compose(pool,mods,implicits,statuses);local out={}\n  for k,n in pairs(keys) do out[k]=1+clamp(B.families[k],n) end\n  return out\n end\n function B.worst_case(pool,implicitdefs)\n  B.validate_pool(pool,implicitdefs);local low,high={},{}\n  -- Superset of all reachable distinct highest-tier IDs (including every unique and\n  -- every keystone) plus four strongest implicits. This is conservative, not sampling.\n  for _,m in ipairs(pool) do\n   local lo,hi={},{}\n   for tier=1,#m.tiers do local sums={};for _,e in ipairs(m.effects) do for f,n in pairs(effect(e,m,tier)) do add(sums,f,n) end end\n    for f,n in pairs(sums) do lo[f]=math.min(lo[f] or 0,n);hi[f]=math.max(hi[f] or 0,n) end\n   end\n   for f,n in pairs(lo) do add(low,f,n) end;for f,n in pairs(hi) do add(high,f,n) end\n  end\n  for f in pairs(B.caps) do local lo,hi=0,0\n   for _,base in pairs(implicitdefs or {}) do for k,v in pairs(base) do if B.families[k]==f then lo=math.min(lo,v-1);hi=math.max(hi,v-1) end end end\n   add(low,f,4*lo);add(high,f,4*hi)\n  end\n  local result={};for f in pairs(B.caps) do result[f]={raw_min=low[f] or 0,raw_max=high[f] or 0,min=1+clamp(f,low[f] or 0),max=1+clamp(f,high[f] or 0)} end\n  return result\n end\n -- ---- content memo ----------------------------------------------------------------------------------------------------------------\n -- build/values are pure functions of (pool, mods, implicits, statuses, strength mode, tuning revision). Probe engines, the bag's draft views,\n -- the foe roller and the publication check all ask the same question many times a frame at deep loops (the campaigns hit the 2 M instruction\n -- budget there); one shared, bounded cache answers repeats, and keeps the work an interrupted publication already did, so a retry makes\n -- progress. Results are shared tables: callers read them, none writes them.\n local pool_ids=setmetatable({},{__mode='k'});local npool=0\n local cache,cache_n={},0\n local function tier_text(t)\n  if type(t)~='table' then return tostring(t) end\n  local o={};if t.tier then o[#o+1]='t'..tostring(t.tier) end;if t.copies then o[#o+1]='c'..tostring(t.copies) end\n  if t.tiers then o[#o+1]='['..table.concat(t.tiers,',')..']' end;return table.concat(o,'/')\n end\n local function content_key(kind,pool,mods,implicits,statuses)\n  local id=pool_ids[pool];if not id then npool=npool+1;id=npool;pool_ids[pool]=id end\n  local parts,n={},0\n  for mid,t in pairs(mods or {}) do n=n+1;parts[n]=mid..'='..tier_text(t) end;table.sort(parts)\n  local out={kind,id,B.mode(),D.mod_tuning and D.mod_tuning.rev or 0,table.concat(parts,';')}\n  local im={};for k,v in pairs(implicits or {}) do im[#im+1]=k..'='..tostring(v) end;table.sort(im);out[#out+1]=table.concat(im,';')\n  local st={};for name,v in pairs(statuses or {}) do st[#st+1]=name..':'..tostring(type(v)=='table' and v.stacks)..':'..tostring(type(v)=='table' and v.amount) end;table.sort(st);out[#out+1]=table.concat(st,';')\n  return table.concat(out,'|')\n end\n local function remember(key,a,b)\n  if cache_n>=600 then cache,cache_n={},0 end\n  cache[key]={a,b};cache_n=cache_n+1\n end\n local raw_build,raw_values=B.build,B.values\n B.cache_stats={hits=